package com.renderreplay;

import com.google.common.collect.MapMaker;
import java.util.Arrays;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Shares equal arrays between the model copies of one recording. An animated model gets a new copy for every pose,
 * and those copies differ only in their vertex positions: faces, colours and the rest are the same arrays again.
 * Arrays are held weakly, so they go away with the last frame that uses them. Shared arrays must not be written to.
 */
final class ArrayPool
{
	private final ConcurrentMap<Long, Object> arrays = new MapMaker().weakValues().makeMap();
	private final AtomicLong added = new AtomicLong();

	int[] share(int[] a)
	{
		if (a == null)
		{
			return null;
		}
		Long key = key(0, a.length, Arrays.hashCode(a));
		Object hit = arrays.get(key);
		if (hit instanceof int[] && Arrays.equals((int[]) hit, a))
		{
			return (int[]) hit;
		}
		return keep(key, a, 4L * a.length);
	}

	float[] share(float[] a)
	{
		if (a == null)
		{
			return null;
		}
		Long key = key(1, a.length, Arrays.hashCode(a));
		Object hit = arrays.get(key);
		if (hit instanceof float[] && Arrays.equals((float[]) hit, a))
		{
			return (float[]) hit;
		}
		return keep(key, a, 4L * a.length);
	}

	short[] share(short[] a)
	{
		if (a == null)
		{
			return null;
		}
		Long key = key(2, a.length, Arrays.hashCode(a));
		Object hit = arrays.get(key);
		if (hit instanceof short[] && Arrays.equals((short[]) hit, a))
		{
			return (short[]) hit;
		}
		return keep(key, a, 2L * a.length);
	}

	byte[] share(byte[] a)
	{
		if (a == null)
		{
			return null;
		}
		Long key = key(3, a.length, Arrays.hashCode(a));
		Object hit = arrays.get(key);
		if (hit instanceof byte[] && Arrays.equals((byte[]) hit, a))
		{
			return (byte[]) hit;
		}
		return keep(key, a, a.length);
	}

	/** Counts bytes kept for a recording outside the pool, so one total covers a frame's models. */
	void added(long bytes)
	{
		added.addAndGet(bytes);
	}

	/** Bytes added since the last call. */
	long takeAdded()
	{
		return added.getAndSet(0);
	}

	private static Long key(int type, int length, int hash)
	{
		return ((long) hash << 32) | ((long) length << 2 & 0xFFFFFFFCL) | type;
	}

	private <T> T keep(Long key, T a, long bytes)
	{
		arrays.put(key, a);
		added.addAndGet(16 + bytes);
		return a;
	}
}

package com.renderreplay;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;

/** Growable byte buffer and reader with the variable-length integers the codecs use. */
final class Bytes
{
	private Bytes()
	{
	}

	static final class Out
	{
		byte[] b;
		int n;

		Out(int size)
		{
			b = new byte[Math.max(16, size)];
		}

		private void need(int k)
		{
			if (n + k > b.length)
			{
				b = Arrays.copyOf(b, Math.max(b.length * 2, n + k));
			}
		}

		void u8(int v)
		{
			need(1);
			b[n++] = (byte) v;
		}

		/** Unsigned variable-length integer. */
		void varint(long v)
		{
			need(10);
			while ((v & ~0x7FL) != 0)
			{
				b[n++] = (byte) ((v & 0x7F) | 0x80);
				v >>>= 7;
			}
			b[n++] = (byte) v;
		}

		/** Signed, zigzag-coded. */
		void zz(long v)
		{
			varint((v << 1) ^ (v >> 63));
		}

		void bytes(byte[] a, int off, int len)
		{
			need(len);
			System.arraycopy(a, off, b, n, len);
			n += len;
		}

		void bytes(byte[] a)
		{
			bytes(a, 0, a.length);
		}

		void str(String s)
		{
			byte[] u = s.getBytes(StandardCharsets.UTF_8);
			varint(u.length);
			bytes(u);
		}

		byte[] toArray()
		{
			return Arrays.copyOf(b, n);
		}
	}

	static final class In
	{
		final byte[] b;
		int p;
		final int end;

		In(byte[] b)
		{
			this(b, 0, b.length);
		}

		In(byte[] b, int off, int len)
		{
			this.b = b;
			this.p = off;
			this.end = off + len;
		}

		int u8()
		{
			if (p >= end)
			{
				throw new IllegalArgumentException("truncated data");
			}
			return b[p++] & 0xFF;
		}

		long varint()
		{
			long v = 0;
			for (int shift = 0; ; shift += 7)
			{
				int x = u8();
				v |= (long) (x & 0x7F) << shift;
				if ((x & 0x80) == 0)
				{
					return v;
				}
				if (shift > 63)
				{
					throw new IllegalArgumentException("bad varint");
				}
			}
		}

		int varint32()
		{
			return (int) varint();
		}

		long zz()
		{
			long v = varint();
			return (v >>> 1) ^ -(v & 1);
		}

		String str()
		{
			int k = varint32();
			if (k < 0 || p + k > end)
			{
				throw new IllegalArgumentException("bad string");
			}
			String s = new String(b, p, k, StandardCharsets.UTF_8);
			p += k;
			return s;
		}

		boolean done()
		{
			return p >= end;
		}
	}
}

package com.renderreplay;

import java.util.Set;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Texture;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.hooks.DrawCallbacks;

/**
 * Every DrawCallbacks method the recorder handles, as a typed value. A call is stored as (Call, Object[] args) and
 * re-issued with an ordinary, statically typed method call in invoke().
 */
enum Call
{
	DRAW_PROJ("draw", Projection.class, Scene.class, Renderable.class, int.class, int.class, int.class, int.class, long.class),
	DRAW_SCENE_PAINT("drawScenePaint", Scene.class, SceneTilePaint.class, int.class, int.class, int.class),
	DRAW_SCENE_TILE_MODEL("drawSceneTileModel", Scene.class, SceneTileModel.class, int.class, int.class),
	DRAW_FRAME_END("draw", int.class),
	DRAW_SCENE("drawScene", double.class, double.class, double.class, double.class, double.class, int.class),
	POST_DRAW_SCENE("postDrawScene"),
	ANIMATE("animate", Texture.class, int.class),
	LOAD_SCENE("loadScene", Scene.class),
	SWAP_SCENE("swapScene", Scene.class),
	TILE_IN_FRUSTUM("tileInFrustum", Scene.class, float.class, float.class, float.class, float.class, int.class, int.class, int.class, int.class, int.class, int.class),
	ZONE_IN_FRUSTUM("zoneInFrustum", int.class, int.class, int.class, int.class),
	LOAD_SCENE_WV("loadScene", WorldView.class, Scene.class),
	DESPAWN_WORLD_VIEW("despawnWorldView", WorldView.class),
	PRE_SCENE_DRAW_PROJ("preSceneDraw", Scene.class, Projection.class, float.class, float.class, float.class, float.class, float.class, int.class, int.class, int.class, Set.class),
	PRE_SCENE_DRAW("preSceneDraw", Scene.class, float.class, float.class, float.class, float.class, float.class, int.class, int.class, int.class, Set.class),
	POST_SCENE_DRAW("postSceneDraw", Scene.class),
	DRAW_PASS("drawPass", Projection.class, Scene.class, int.class),
	DRAW_ZONE_OPAQUE("drawZoneOpaque", Projection.class, Scene.class, int.class, int.class),
	DRAW_ZONE_ALPHA("drawZoneAlpha", Projection.class, Scene.class, int.class, int.class, int.class),
	DRAW_DYNAMIC("drawDynamic", Projection.class, Scene.class, TileObject.class, Renderable.class, Model.class, int.class, int.class, int.class, int.class),
	DRAW_DYNAMIC_WORKER("drawDynamic", int.class, Projection.class, Scene.class, TileObject.class, Renderable.class, Model.class, int.class, int.class, int.class, int.class),
	DRAW_TEMP("drawTemp", Projection.class, Scene.class, GameObject.class, Model.class, int.class, int.class, int.class, int.class),
	INVALIDATE_ZONE("invalidateZone", Scene.class, int.class, int.class);

	/** The DrawCallbacks method name, as written in the recording files. */
	final String methodName;
	/** Parameter types, used to convert numbers read from a recording file. */
	final Class<?>[] types;

	Call(String methodName, Class<?>... types)
	{
		this.methodName = methodName;
		this.types = types;
	}

	int arity()
	{
		return types.length;
	}

	/** The frame-end draw(int) call: passed through live after the recorded 2D layer is drawn. */
	boolean isFrameEnd()
	{
		return this == DRAW_FRAME_END;
	}

	/** The client's own scene changes: never replayed, handled apart from drawing (DrawRecorder.sceneChange). */
	boolean isSceneChange()
	{
		return this == LOAD_SCENE || this == LOAD_SCENE_WV || this == SWAP_SCENE || this == INVALIDATE_ZONE || this == DESPAWN_WORLD_VIEW;
	}

	private static int i(Object o)
	{
		return ((Number) o).intValue();
	}

	private static float f(Object o)
	{
		return ((Number) o).floatValue();
	}

	private static double d(Object o)
	{
		return ((Number) o).doubleValue();
	}

	/** Issues this call on t. Returns the result for the two boolean methods, else null. */
	@SuppressWarnings("unchecked")
	Object invoke(DrawCallbacks t, Object[] a)
	{
		switch (this)
		{
			case DRAW_PROJ:
				t.draw((Projection) a[0], (Scene) a[1], (Renderable) a[2], i(a[3]), i(a[4]), i(a[5]), i(a[6]), ((Number) a[7]).longValue());
				return null;
			case DRAW_SCENE_PAINT:
				t.drawScenePaint((Scene) a[0], (SceneTilePaint) a[1], i(a[2]), i(a[3]), i(a[4]));
				return null;
			case DRAW_SCENE_TILE_MODEL:
				t.drawSceneTileModel((Scene) a[0], (SceneTileModel) a[1], i(a[2]), i(a[3]));
				return null;
			case DRAW_FRAME_END:
				t.draw(i(a[0]));
				return null;
			case DRAW_SCENE:
				t.drawScene(d(a[0]), d(a[1]), d(a[2]), d(a[3]), d(a[4]), i(a[5]));
				return null;
			case POST_DRAW_SCENE:
				t.postDrawScene();
				return null;
			case ANIMATE:
				t.animate((Texture) a[0], i(a[1]));
				return null;
			case LOAD_SCENE:
				t.loadScene((Scene) a[0]);
				return null;
			case SWAP_SCENE:
				t.swapScene((Scene) a[0]);
				return null;
			case TILE_IN_FRUSTUM:
				return t.tileInFrustum((Scene) a[0], f(a[1]), f(a[2]), f(a[3]), f(a[4]), i(a[5]), i(a[6]), i(a[7]), i(a[8]), i(a[9]), i(a[10]));
			case ZONE_IN_FRUSTUM:
				return t.zoneInFrustum(i(a[0]), i(a[1]), i(a[2]), i(a[3]));
			case LOAD_SCENE_WV:
				t.loadScene((WorldView) a[0], (Scene) a[1]);
				return null;
			case DESPAWN_WORLD_VIEW:
				t.despawnWorldView((WorldView) a[0]);
				return null;
			case PRE_SCENE_DRAW_PROJ:
				t.preSceneDraw((Scene) a[0], (Projection) a[1], f(a[2]), f(a[3]), f(a[4]), f(a[5]), f(a[6]), i(a[7]), i(a[8]), i(a[9]), (Set<Integer>) a[10]);
				return null;
			case PRE_SCENE_DRAW:
				t.preSceneDraw((Scene) a[0], f(a[1]), f(a[2]), f(a[3]), f(a[4]), f(a[5]), i(a[6]), i(a[7]), i(a[8]), (Set<Integer>) a[9]);
				return null;
			case POST_SCENE_DRAW:
				t.postSceneDraw((Scene) a[0]);
				return null;
			case DRAW_PASS:
				t.drawPass((Projection) a[0], (Scene) a[1], i(a[2]));
				return null;
			case DRAW_ZONE_OPAQUE:
				t.drawZoneOpaque((Projection) a[0], (Scene) a[1], i(a[2]), i(a[3]));
				return null;
			case DRAW_ZONE_ALPHA:
				t.drawZoneAlpha((Projection) a[0], (Scene) a[1], i(a[2]), i(a[3]), i(a[4]));
				return null;
			case DRAW_DYNAMIC:
				t.drawDynamic((Projection) a[0], (Scene) a[1], (TileObject) a[2], (Renderable) a[3], (Model) a[4], i(a[5]), i(a[6]), i(a[7]), i(a[8]));
				return null;
			case DRAW_DYNAMIC_WORKER:
				t.drawDynamic(i(a[0]), (Projection) a[1], (Scene) a[2], (TileObject) a[3], (Renderable) a[4], (Model) a[5], i(a[6]), i(a[7]), i(a[8]), i(a[9]));
				return null;
			case DRAW_TEMP:
				t.drawTemp((Projection) a[0], (Scene) a[1], (GameObject) a[2], (Model) a[3], i(a[4]), i(a[5]), i(a[6]), i(a[7]));
				return null;
			case INVALIDATE_ZONE:
				t.invalidateZone((Scene) a[0], i(a[1]), i(a[2]));
				return null;
			default:
				throw new IllegalStateException(this.name());
		}
	}

	/** Finds the call by its name and argument count (recording files store exactly these two). */
	static Call find(String methodName, int arity)
	{
		for (Call c : values())
		{
			if (c.methodName.equals(methodName) && c.arity() == arity)
			{
				return c;
			}
		}
		return null;
	}
}

package com.renderreplay;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Shares equal draw calls between consecutive frames. Nearly every call of a frame repeats one of the frame before, so
 * a frame keeps a reference to that call instead of its own copy. A call is {Call, Object[] args}; shared calls must
 * not be written to.
 */
final class CallPool
{
	private Map<Key, Object[]> previous = new HashMap<>();
	private Map<Key, Object[]> current = new HashMap<>();
	private long added;

	/** The equal call of this frame or the previous one, or a new call. */
	Object[] share(Call m, Object[] args)
	{
		Key k = new Key(m, args);
		Object[] call = current.get(k);
		if (call == null)
		{
			call = previous.get(k);
			if (call == null)
			{
				call = new Object[]{m, args};
				added += sizeOf(args);
			}
			k.args = (Object[]) call[1];
			current.put(k, call);
		}
		return call;
	}

	/** Estimated bytes of a call that is not shared: its two arrays, boxed numbers and the copies frozen for it. */
	private static long sizeOf(Object[] args)
	{
		long bytes = 48;
		for (int i = 0; args != null && i < args.length; i++)
		{
			Object a = args[i];
			bytes += 4;
			if (a instanceof Double || a instanceof Long)
			{
				bytes += 24;
			}
			else if (a instanceof Float || (a instanceof Integer && ((Integer) a < -128 || (Integer) a > 127)))
			{
				bytes += 16;
			}
			else if (a instanceof Set)
			{
				bytes += 64 + 48L * ((Set<?>) a).size();
			}
			else if (a instanceof FrozenProjection)
			{
				bytes += 96;
			}
			else if (a instanceof StandIns.StandInGameObject)
			{
				bytes += 160;
			}
		}
		return bytes;
	}

	/** Ends the frame. Returns the estimated bytes of the calls it could not share. */
	long endFrame()
	{
		previous = current;
		current = new HashMap<>();
		long bytes = added;
		added = 0;
		return bytes;
	}

	private static final class Key
	{
		private final Call m;
		private Object[] args;
		private final int hash;

		Key(Call m, Object[] args)
		{
			this.m = m;
			this.args = args;
			int h = m.hashCode();
			for (int i = 0; args != null && i < args.length; i++)
			{
				h = 31 * h + hashOf(args[i]);
			}
			this.hash = h;
		}

		@Override
		public int hashCode()
		{
			return hash;
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Key))
			{
				return false;
			}
			Key k = (Key) o;
			if (m != k.m || hash != k.hash || (args == null) != (k.args == null))
			{
				return false;
			}
			if (args == null || args == k.args)
			{
				return true;
			}
			if (args.length != k.args.length)
			{
				return false;
			}
			for (int i = 0; i < args.length; i++)
			{
				if (!same(args[i], k.args[i]))
				{
					return false;
				}
			}
			return true;
		}
	}

	// Values and the recorder's own frozen copies are compared by content; everything else (scenes, models, live
	// objects) is the same only when it is the same object.

	private static boolean byContent(Object a)
	{
		return a instanceof Number || a instanceof Boolean || a instanceof Set || a instanceof FrozenProjection;
	}

	private static int hashOf(Object a)
	{
		if (a == null)
		{
			return 0;
		}
		if (byContent(a))
		{
			return a.hashCode();
		}
		if (a instanceof StandIns.StandInGameObject)
		{
			StandIns.StandInGameObject g = (StandIns.StandInGameObject) a;
			return 31 * (31 * Long.hashCode(g.hash) + g.x) + g.y;
		}
		return System.identityHashCode(a);
	}

	private static boolean same(Object a, Object b)
	{
		if (a == b)
		{
			return true;
		}
		if (a == null || b == null)
		{
			return false;
		}
		if (byContent(a))
		{
			return a.equals(b);
		}
		if (a instanceof StandIns.StandInGameObject && b instanceof StandIns.StandInGameObject)
		{
			StandIns.StandInGameObject g = (StandIns.StandInGameObject) a, h = (StandIns.StandInGameObject) b;
			return g.hash == h.hash && g.id == h.id && g.plane == h.plane && g.x == h.x && g.y == h.y && g.z == h.z
				&& g.orientation == h.orientation && g.modelOrientation == h.modelOrientation && g.config == h.config
				&& g.sizeX == h.sizeX && g.sizeY == h.sizeY && g.wv == h.wv
				&& Objects.equals(g.min, h.min) && Objects.equals(g.max, h.max) && same(g.renderable, h.renderable);
		}
		if (a instanceof StandIns.StandInRenderable && b instanceof StandIns.StandInRenderable)
		{
			StandIns.StandInRenderable r = (StandIns.StandInRenderable) a, s = (StandIns.StandInRenderable) b;
			return r.height == s.height && r.mode == s.mode && r.model == s.model;
		}
		return false;
	}
}

package com.renderreplay;

import net.runelite.api.Projection;

/**
 * The client's world projection, rebuilt from a frame's drawScene camera (x, y, z, pitch, yaw): moves a point into
 * camera space. The GPU plugin calls it to sort a model's faces and to drop those facing away, so a replayed frame
 * must hand it the recorded camera, not the live one.
 */
final class CameraProjection implements Projection
{
	private final double cx, cy, cz, ps, pc, ys, yc;

	CameraProjection(double cx, double cy, double cz, double pitch, double yaw)
	{
		this.cx = cx;
		this.cy = cy;
		this.cz = cz;
		this.ps = Math.sin(pitch);
		this.pc = Math.cos(pitch);
		this.ys = Math.sin(yaw);
		this.yc = Math.cos(yaw);
	}

	/** The projection of a drawScene call's arguments, or null if they are not a camera. */
	static CameraProjection of(Object[] drawSceneArgs)
	{
		if (drawSceneArgs == null || drawSceneArgs.length < 5)
		{
			return null;
		}
		double[] v = new double[5];
		for (int i = 0; i < 5; i++)
		{
			if (!(drawSceneArgs[i] instanceof Number))
			{
				return null;
			}
			v[i] = ((Number) drawSceneArgs[i]).doubleValue();
		}
		return new CameraProjection(v[0], v[1], v[2], v[3], v[4]);
	}

	@Override
	public float[] project(float x, float y, float z)
	{
		return project(x, y, z, new float[3]);
	}

	@Override
	public float[] project(float x, float y, float z, float[] out)
	{
		if (out == null || out.length < 3)
		{
			out = new float[3];
		}
		double dx = x - cx, dy = y - cy, dz = z - cz;
		double x1 = dx * yc + dz * ys;
		double z1 = dz * yc - dx * ys;
		out[0] = (float) x1;
		out[1] = (float) (dy * pc - z1 * ps);
		out[2] = (float) (dy * ps + z1 * pc);
		return out;
	}
}

package com.renderreplay;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Lossless inter-frame compression of the per-frame call list written to *.draws.jsonl.
 * Consecutive frames repeat almost every call (about 98% measured), so a frame is written as a JSON array whose
 * elements are either a full call row or {"p":[start,len]}: "calls start..start+len-1 of the previous frame".
 * Decoding a frame needs only the previous decoded frame; every KEYFRAME_EVERY frames a frame is written in full so a
 * file can also be read from the middle.
 */
final class DrawDelta
{
	static final int KEYFRAME_EVERY = 120;

	private List<String> prev = new ArrayList<>();
	private int sinceKey;

	/** rows = each call already serialised as JSON; returns the JSON array text for the frame. */
	String encode(List<String> rows)
	{
		boolean key = sinceKey == 0 || prev.isEmpty();
		StringBuilder sb = new StringBuilder(key ? rows.size() * 64 : 256).append('[');
		if (key)
		{
			for (int i = 0; i < rows.size(); i++)
			{
				sb.append(i == 0 ? "" : ",").append(rows.get(i));
			}
		}
		else
		{
			Map<String, Integer> index = new HashMap<>();
			for (int i = prev.size() - 1; i >= 0; i--)
			{
				index.put(prev.get(i), i); // first occurrence wins
			}
			int runStart = -1, runLen = 0;
			boolean first = true;
			for (String r : rows)
			{
				if (runLen > 0 && runStart + runLen < prev.size() && prev.get(runStart + runLen).equals(r))
				{
					runLen++;
					continue;
				}
				if (runLen > 0)
				{
					sb.append(first ? "" : ",").append("{\"p\":[").append(runStart).append(',').append(runLen).append("]}");
					first = false;
					runLen = 0;
				}
				Integer at = index.get(r);
				if (at != null)
				{
					runStart = at;
					runLen = 1;
				}
				else
				{
					sb.append(first ? "" : ",").append(r);
					first = false;
				}
			}
			if (runLen > 0)
			{
				sb.append(first ? "" : ",").append("{\"p\":[").append(runStart).append(',').append(runLen).append("]}");
			}
		}
		prev = new ArrayList<>(rows);
		sinceKey = (sinceKey + 1) % KEYFRAME_EVERY;
		return sb.append(']').toString();
	}

	/**
	 * Inverse of encode for tests and tools: elems are the frame's array elements as JSON text ({"p":..} objects are
	 * recognised by their prefix); prevRows is the previous decoded frame.
	 */
	static List<String> decode(List<String> elems, List<String> prevRows)
	{
		List<String> out = new ArrayList<>();
		for (String e : elems)
		{
			if (e.startsWith("{\"p\":["))
			{
				String[] n = e.substring(6, e.indexOf(']')).split(",");
				int start = Integer.parseInt(n[0]), len = Integer.parseInt(n[1]);
				out.addAll(prevRows.subList(start, start + len));
			}
			else
			{
				out.add(e);
			}
		}
		return out;
	}
}

