	// Copies of the scenes the client loaded while a recorder was installed; shared by all recorders.
	static final SceneKeeper KEEPER = new SceneKeeper();

	private Object handle(Call m, Object[] args)
	{
		if (m.isSceneChange())
		{
			return sceneChange(m, args);
		}
		boolean frameEnd = m.isFrameEnd();
		if (m == Call.DRAW_PASS || m == Call.DRAW_ZONE_OPAQUE || m == Call.DRAW_DYNAMIC || m == Call.DRAW_DYNAMIC_WORKER || m == Call.DRAW_TEMP)
		{
			noteProjection(args);
		}
		if (playing)
		{
			if (m == Call.DRAW_SCENE)
			{
				replayFrame();
				return null;
			}
			if (WORLD_CALLS.contains(m.methodName) && !frameEnd)
			{
				return null;
			}
			if (frameEnd)
			{
				try
				{
					applyUi();
				}
				catch (RuntimeException e)
				{
					log.debug("could not draw the recorded 2D layer", e);
				}
			}
			return m.invoke(delegate, args);
		}
		if (!capturing)
		{
			return m.invoke(delegate, args);
		}

		// Record before delegating, so the file shows what the renderer was handed even if it throws.
		try
		{
			record(m, args);
		}
		catch (RuntimeException e)
		{
			log.debug("could not record {}", m.methodName, e);
		}
		byte[] ui = null;
		boolean key = false;
		int[] pixels = null;
		boolean skipFrame = false;
		if (frameEnd)
		{
			if (store != null)
			{
				// memory stays bounded when the writer falls behind: first the 2D layer copy is skipped, then whole frames
				int backlog = writer.getQueue().size();
				if (backlog >= SKIP_FRAME_BACKLOG)
				{
					skipFrame = true;
				}
				else if (backlog >= SKIP_UI_BACKLOG)
				{
					uiSkipped++;
				}
				else
				{
					pixels = copyUi();
				}
			}
			else
			{
				key = uiFrameCounter++ % UI_KEYFRAME_EVERY == 0;
				ui = captureUi(key);
			}
		}
		Object r = m.invoke(delegate, args);
		if (frameEnd)
		{
			if (store != null)
			{
				if (skipFrame)
				{
					skipFrame();
				}
				else
				{
					flushToStore(args[0], pixels);
				}
			}
			else
			{
				flush(args[0], ui, key);
			}
		}
		return r;
	}

	private void record(Call m, Object[] args)
	{
		if (args != null && (m.methodName.equals("loadScene") || m.methodName.equals("swapScene")))
		{
			synchronized (sceneIds)
			{
				for (Object a : args)
				{
					sceneIds.remove(a);
				}
			}
		}
		Object[] row = new Object[1 + (args == null ? 0 : args.length)];
		row[0] = m.methodName;
		if (args != null)
		{
			for (int i = 0; i < args.length; i++)
			{
				row[i + 1] = describe(args[i]);
			}
		}
		if (args != null && args.length > 0 && args[0] instanceof Integer && m.methodName.equals("drawDynamic")
			&& (Integer) args[0] >= dynWorkers && (Integer) args[0] < 64)
		{
			dynWorkers = (Integer) args[0] + 1;   // learn how many workers the client dispatched to
		}
		synchronized (lock)
		{
			if (store != null)
			{
				if (m == Call.DRAW_SCENE && args[4] instanceof Double)
				{
					frameYaw = (Double) args[4];
				}
				if (frameScene == null && args != null && WORLD_CALLS.contains(m.methodName))
				{
					for (Object a : args)
					{
						if (a instanceof Scene)
						{
							frameScene = a;
							break;
						}
					}
				}
			}
			else if (WORLD_CALLS.contains(m.methodName) && !m.isFrameEnd())
			{
				rawCalls.add(callPool.share(m, frozen(m, args, row)));
			}
			if (calls.size() < MAX_CALLS_PER_FRAME)
			{
				calls.add(row);
			}
			else
			{
				dropped++;
			}
		}
	}

	// Writer backlog (frames queued) from which the 2D layer is not copied, and from which whole frames are skipped.
	static final int SKIP_UI_BACKLOG = 8, SKIP_FRAME_BACKLOG = 120;
	private volatile int uiSkipped, framesSkipped;

	/** The writer is too far behind to take this frame: its calls are let go. */
	private void skipFrame()
	{
		synchronized (lock)
		{
			calls = new ArrayList<>();
			frameScene = null;
			projCache.clear();
		}
		framesSkipped++;
	}

	/** A copy of the 2D layer for the writer thread, in a reused buffer (null when there is none). */
	private int[] copyUi()
	{
		int[] px = probe == null ? null : probe.uiPixels();
		if (px == null)
		{
			return null;
		}
		int[] copy = pixelPool.poll();
		if (copy == null || copy.length != px.length)
		{
			copy = new int[px.length];
		}
		System.arraycopy(px, 0, copy, 0, px.length);
		return copy;
	}

	/** Frame end of a recording kept in the store: the writer thread writes the file and codes the frame. */
	private void flushToStore(Object overlayColor, int[] pixels)
	{
		List<Object[]> batch;
		long drop;
		Object scene;
		float yaw;
		synchronized (lock)
		{
			batch = calls;
			calls = new ArrayList<>();
			drop = dropped;
			dropped = 0;
			scene = frameScene;
			frameScene = null;
			yaw = (float) frameYaw;
			projCache.clear();
		}
		final long wall = System.currentTimeMillis();
		final long fr = frame++;
		final int tick = probe == null ? 0 : probe.tick(), scale = probe == null ? 0 : probe.scale();
		final int cycle = probe == null ? -1 : probe.gameCycle(), width = probe == null ? 0 : probe.uiWidth();
		final float[] player = probe == null ? null : probe.playerLocal();
		final int[] mm = probe == null ? null : probe.minimap();
		final FrameStore st = store;
		writer.execute(() ->
		{
			if (fullAt >= 0)
			{
				// memory filled at an earlier frame: what was queued behind it is not kept
				if (pixels != null)
				{
					pixelPool.offer(pixels);
				}
				return;
			}
			writeFrame(batch, fr, wall, overlayColor, drop);
			try
			{
				st.append(wall, tick, scale, cycle, player, yaw, scene, batch, pixels, width > 0 ? width : pixels == null ? 0 : pixels.length, mm);
				if (st.size() >= minFrames && (st.bytes() >= budgetBytes || st.size() >= RETAIN_FRAMES))
				{
					// full: stop here and keep everything so far; nothing is saved until the user asks
					fullAt = wall;
					capturing = false;
					log.debug("memory full at {} frames, about {} KB: recording stopped", st.size(), st.bytes() >> 10);
				}
			}
			catch (RuntimeException e)
			{
				log.debug("could not keep a frame", e);
			}
			if (pixels != null)
			{
				pixelPool.offer(pixels);
			}
		});
	}

	private void flush(Object overlayColor, byte[] ui, boolean key)
	{
		List<Object[]> batch;
		long drop;
		synchronized (lock)
		{
			rawCalls.trimToSize();
			retained.add(new RawFrame(System.currentTimeMillis(), rawCalls, callPool.endFrame() + arrays.takeAdded(), ui, key,
				probe == null ? 0 : probe.scale(), probe == null ? null : probe.playerLocal(), probe == null ? 0 : probe.tick(),
				probe == null ? -1 : probe.gameCycle()));
			retainedBytes += retained.get(retained.size() - 1).bytes;
			// Drop the oldest frames while over budget, but only down to a keyframe so the 2D-layer chain stays decodable.
			while ((retainedBytes > budgetBytes || retained.size() > RETAIN_FRAMES) && retained.size() > minFrames
				&& !retained.get(1).keyframe)
			{
				retainedBytes -= retained.remove(0).bytes;
			}
			if ((retainedBytes > budgetBytes || retained.size() > RETAIN_FRAMES) && retained.size() > minFrames)
			{
				retainedBytes -= retained.remove(0).bytes;
			}
			rawCalls = new ArrayList<>(rawCalls.size());
			projCache.clear();
			batch = calls;
			calls = new ArrayList<>();
			drop = dropped;
			dropped = 0;
		}
		final long wall = System.currentTimeMillis();
		final long fr = frame++;
		// Serialising, delta-encoding and writing happen on the writer thread, not the render thread.
		writer.execute(() -> writeFrame(batch, fr, wall, overlayColor, drop));
	}

	private void writeFrame(List<Object[]> batch, long fr, long wall, Object overlayColor, long drop)
	{
		List<String> rows = new ArrayList<>(batch.size());
		for (Object[] r : batch)
		{
			rows.add(gson.toJson(r));
		}
		String text = "{\"frame\":" + fr + ",\"wallMs\":" + wall + ",\"overlay\":" + gson.toJson(overlayColor)
			+ ",\"dropped\":" + drop + ",\"enc\":\"d1\",\"calls\":" + delta.encode(rows) + "}";
		try
		{
			synchronized (out)
			{
				out.write(text);
				out.newLine();
				out.flush();
			}
		}
		catch (IOException e)
		{
			log.debug("could not write a frame", e);
		}
	}

	// Bounded queue: when the writer falls behind, the render thread writes the frame itself.
	private final java.util.concurrent.ThreadPoolExecutor writer = new java.util.concurrent.ThreadPoolExecutor(1, 1, 0L,
		TimeUnit.MILLISECONDS, new java.util.concurrent.LinkedBlockingQueue<>(1500), r ->
		{
			Thread t = new Thread(r, "render-replay-writer");
			t.setDaemon(true);
			return t;
		}, new java.util.concurrent.ThreadPoolExecutor.CallerRunsPolicy());
	private final DrawDelta delta = new DrawDelta();

	/** Waits until every frame handed to the writer thread has been written and stops the thread. Call before closing the files. */
	static void drainWrites(DrawCallbacks cb)
	{
		MoreExecutors.shutdownAndAwaitTermination(handler(cb).writer, 30, TimeUnit.SECONDS);
	}

	/** Compact description of an argument for the draws file. Never calls anything that could compute a model. */
	private Object describe(Object a)
	{
		if (a == null || a instanceof Number || a instanceof Boolean || a instanceof String)
		{
			return a;
		}
		if (a instanceof Model)
		{
			return geometry("model", (Model) a);
		}
		if (a instanceof Scene)
		{
			return sceneRef((Scene) a);
		}
		if (a instanceof SceneTileModel)
		{
			return geometry("tilemodel", (SceneTileModel) a);
		}
		if (a instanceof SceneTilePaint)
		{
			SceneTilePaint t = (SceneTilePaint) a;
			return new int[]{t.getRBG(), t.getSwColor(), t.getSeColor(), t.getNwColor(), t.getNeColor(),
				t.getTexture(), t.isFlat() ? 1 : 0};
		}
		if (a instanceof GameObject)
		{
			return describeGameObject((GameObject) a);
		}
		if (a instanceof TileObject)
		{
			TileObject t = (TileObject) a;
			Map<String, Object> o = new LinkedHashMap<>();
			o.put("tobj", t.getId());
			o.put("plane", t.getPlane());
			o.put("hash", t.getHash());
			return o;
		}
		if (a instanceof net.runelite.api.Renderable)
		{
			net.runelite.api.Renderable r = (net.runelite.api.Renderable) a;
			Map<String, Object> o = new LinkedHashMap<>();
			o.put("rend", a instanceof NPC ? "NPC{" + ((NPC) a).getId() + "}" : a instanceof Player ? "Player" : "Renderable");
			try
			{
				o.put("h", r.getModelHeight());
				o.put("m", r.getRenderMode());
			}
			catch (RuntimeException e)
			{
				o.put("err", String.valueOf(e));
			}
			return o;
		}
		if (a instanceof WorldView)
		{
			return "WorldView{" + ((WorldView) a).getId() + "}";
		}
		if (a instanceof Set)
		{
			return java.util.Collections.singletonMap("set", new ArrayList<Object>((Set<?>) a));
		}
		if (a instanceof net.runelite.api.Projection)
		{
			// the GPU plugin calls project(x,y,z) on it: keep the matrix if there is one, else 4 sample points (an affine map)
			net.runelite.api.Projection pr = (net.runelite.api.Projection) a;
			Map<String, Object> o = new LinkedHashMap<>();
			o.put("proj", a instanceof net.runelite.api.FloatProjection ? "float" : "other");
			try
			{
				if (a instanceof net.runelite.api.FloatProjection)
				{
					o.put("m", ((net.runelite.api.FloatProjection) a).getProjection());
				}
				o.put("s", new float[][]{pr.project(0, 0, 0).clone(), pr.project(128, 0, 0).clone(), pr.project(0, 128, 0).clone(), pr.project(0, 0, 128).clone()});
			}
			catch (RuntimeException e)
			{
				o.put("err", String.valueOf(e));
			}
			return o;
		}
		return "object";
	}

	/** Everything drawTemp/drawDynamic read from a GameObject wrapper, captured now (the client reuses the wrapper). */
	private static Object describeGameObject(GameObject go)
	{
		Map<String, Object> o = new LinkedHashMap<>();
		try
		{
			o.put("go", go.getId());
			o.put("hash", go.getHash());
			o.put("xyz", new int[]{go.getX(), go.getY(), go.getZ()});
			o.put("plane", go.getPlane());
			o.put("ori", new int[]{go.getOrientation(), go.getModelOrientation(), go.getConfig()});
			o.put("size", new int[]{go.sizeX(), go.sizeY()});
		}
		catch (RuntimeException e)
		{
			o.put("err", String.valueOf(e));
		}
		// each part on its own, so one that fails does not lose the others
		try
		{
			net.runelite.api.Point mn = go.getSceneMinLocation(), mx = go.getSceneMaxLocation();
			if (mn != null && mx != null)
			{
				o.put("box", new int[]{mn.getX(), mn.getY(), mx.getX(), mx.getY()});
			}
		}
		catch (RuntimeException e)
		{
			// no scene bounds
		}
		try
		{
			net.runelite.api.Renderable r = go.getRenderable();
			if (r != null)
			{
				o.put("h", r.getModelHeight());
				o.put("m", r.getRenderMode());
			}
		}
		catch (RuntimeException e)
		{
			// no renderable to describe
		}
		return o;
	}

	/** Returns {"model": id}; writes the geometry to modelsOut the first time this exact content is seen. */
	private Object geometry(String kind, Object g)
	{
		Map<String, Object> body = new LinkedHashMap<>();
		if (g instanceof Model)
		{
			Model m = (Model) g;
			// The API hands back oversized backing arrays; only the first vn / fn entries are real.
			int vn = m.getVerticesCount(), fn = m.getFaceCount();
			body.put("vx", trim(m.getVerticesX(), vn));
			body.put("vy", trim(m.getVerticesY(), vn));
			body.put("vz", trim(m.getVerticesZ(), vn));
			body.put("f1", trim(m.getFaceIndices1(), fn));
			body.put("f2", trim(m.getFaceIndices2(), fn));
			body.put("f3", trim(m.getFaceIndices3(), fn));
			body.put("c1", trim(m.getFaceColors1(), fn));
			body.put("c2", trim(m.getFaceColors2(), fn));
			body.put("c3", trim(m.getFaceColors3(), fn));
			body.put("vn", vn);
			body.put("fn", fn);
			body.put("tr", trim(m.getFaceTransparencies(), fn));
			body.put("pri", trim(m.getFaceRenderPriorities(), fn));
			// Format v2 extras: the rest of what the GPU plugin reads from a Model, so a file can rebuild a stand-in model.
			try
			{
				body.put("ft", trim(m.getFaceTextures(), fn));
				body.put("fb", trim(m.getFaceBias(), fn));
				body.put("ov", new int[]{m.getOverrideAmount(), m.getOverrideHue(), m.getOverrideSaturation(), m.getOverrideLuminance()});
				body.put("tp", (int) m.getTransparency());
				byte[] tf = m.getTextureFaces();
				body.put("tf", tf);
				body.put("t1", m.getTexIndices1());
				body.put("t2", m.getTexIndices2());
				body.put("t3", m.getTexIndices3());
				// Radius and diameter are left out: the client fills them in lazily, so until then they hold whatever an
				// earlier model left there, and equal geometry would count as new. Stand-ins compute their own.
			}
			catch (RuntimeException e)
			{
				body.put("v2err", String.valueOf(e));
			}
		}
		else
		{
			SceneTileModel t = (SceneTileModel) g;
			body.put("vx", t.getVertexX());
			body.put("vy", t.getVertexY());
			body.put("vz", t.getVertexZ());
			body.put("f1", t.getFaceX());
			body.put("f2", t.getFaceY());
			body.put("f3", t.getFaceZ());
			body.put("c1", t.getTriangleColorA());
			body.put("c2", t.getTriangleColorB());
			body.put("c3", t.getTriangleColorC());
			body.put("tex", t.getTriangleTextureId());
			body.put("flat", t.isFlat());
		}
		long h = kind.hashCode();
		for (Object v : body.values())
		{
			h = h * 1099511628211L + hashValue(v);
		}
		int id;
		synchronized (geometryIds)
		{
			Integer known = geometryIds.get(h);
			if (known != null)
			{
				if (store != null && store.lost(known))
				{
					// seen before, but the store no longer has it (never drawn by a kept frame, or freed): offer it again
					body.put("id", known);
					body.put("kind", kind);
					store.offerBody(known, body);
				}
				return java.util.Collections.singletonMap(kind, known);
			}
			id = nextId.getAndIncrement();
			geometryIds.put(h, id);
		}
		body.put("id", id);
		body.put("kind", kind);
		if (store != null)
		{
			store.offerBody(id, body);
		}
		try
		{
			synchronized (modelsOut)
			{
				modelsOut.write(gson.toJson(body));
				modelsOut.newLine();
				modelsOut.flush();
			}
		}
		catch (IOException e)
		{
			// keep rendering
		}
		return java.util.Collections.singletonMap(kind, id);
	}

	private static long hashValue(Object v)
	{
		if (v instanceof int[])
		{
			return Arrays.hashCode((int[]) v) * 31L + ((int[]) v).length;
		}
		if (v instanceof float[])
		{
			return Arrays.hashCode((float[]) v) * 31L + ((float[]) v).length;
		}
		if (v instanceof short[])
		{
			return Arrays.hashCode((short[]) v);
		}
		if (v instanceof byte[])
		{
			return Arrays.hashCode((byte[]) v);
		}
		return v == null ? 0 : v.hashCode();
	}

	private static int[] trim(int[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	private static float[] trim(float[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	private static short[] trim(short[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	private static byte[] trim(byte[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	/** Returns {"scene": id}; writes the scene's base to modelsOut the first time the scene is seen. */
	private Object sceneRef(Scene sc)
	{
		int id;
		synchronized (sceneIds)
		{
			Integer known = sceneIds.get(sc);
			if (known != null)
			{
				return java.util.Collections.singletonMap("scene", known);
			}
			id = nextId.getAndIncrement();
			sceneIds.put(sc, id);
			sceneObjs.put(id, sc);
			sceneBase.put(id, new int[]{sc.getBaseX(), sc.getBaseY()});
		}
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("id", id);
		body.put("kind", "scene");
		body.put("worldView", sc.getWorldViewId());
		body.put("baseX", sc.getBaseX());
		body.put("baseY", sc.getBaseY());
		try
		{
			synchronized (modelsOut)
			{
				modelsOut.write(gson.toJson(body));
				modelsOut.newLine();
				modelsOut.flush();
			}
		}
		catch (IOException e)
		{
			// keep rendering
		}
		return java.util.Collections.singletonMap("scene", id);
	}

	// ---- frames, from the compressed store or from a recording read from a file ----

	private int nFrames()
	{
		FrameStore s = store;
		if (s != null)
		{
			return s.size();
		}
		synchronized (lock)
		{
			return retained.size();
		}
	}

	private long wallAt(int i)
	{
		return store != null ? store.wallMs(i) : retained.get(i).wallMs;
	}

	private int tickAt(int i)
	{
		return store != null ? store.tick(i) : retained.get(i).tick;
	}

	private int scaleAt(int i)
	{
		return store != null ? store.scale(i) : retained.get(i).scale;
	}

	private int cycleAt(int i)
	{
		return store != null ? store.cycle(i) : retained.get(i).cycle;
	}

	private float pxAt(int i)
	{
		return store != null ? store.playerX(i) : retained.get(i).playerX;
	}

	private float pzAt(int i)
	{
		return store != null ? store.playerZ(i) : retained.get(i).playerZ;
	}

	private Object sceneAt(int i)
	{
		return store != null ? store.scene(i) : retained.get(i).scene;
	}

	private List<Object[]> callsAt(int i)
	{
		return store != null ? store.calls(i) : retained.get(i).calls;
	}

	/** The last frame recorded at or before wall time t (binary search). */
	private int indexAtTime(long t)
	{
		if (store != null)
		{
			return store.indexAt(t);
		}
		int lo = 0, hi = retained.size() - 1;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			if (retained.get(mid).wallMs <= t)
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return Math.max(0, lo);
	}

	// ---- playback ----

	/** Shifts the playback clock once so the recorded frames' texture phase equals the live one (see phaseShiftMs). */
	private void alignPhase()
	{
		if (probe == null || pauseAtIdx >= 0)
		{
			return;
		}
		int live = probe.gameCycle();
		long elapsed = System.currentTimeMillis() - playStartMs;
		int cycle = cycleAt(indexAtTime(wallAt(0) + elapsed));
		if (live < 0 || cycle < 0)
		{
			return; // unknown (imported recording): leave the clock alone
		}
		long shift = phaseShiftMs(live, cycle);
		playStartMs -= shift;
	}

	private void replayFrame()
	{
		int n = nFrames();
		if (n == 0 || endRequested)
		{
			endPlayback();
			return;
		}
		if (store == null)
		{
			playFrames = retained; // a recording read from a file does not change while it plays
		}
		int idx;
		if (holdIndex >= 0)
		{
			// frozen on one frame
			idx = Math.min(holdIndex, n - 1);
		}
		else
		{
			if (alignPending)
			{
				alignPending = false;
				alignPhase();
			}
			long elapsed = System.currentTimeMillis() - playStartMs;
			long base = wallAt(0);
			if (elapsed > wallAt(n - 1) - base)
			{
				endPlayback();
				return;
			}
			idx = indexAtTime(base + elapsed);
			int stop = pauseAtIdx;
			if (stop >= 0 && idx >= stop)
			{
				// the tick step has played through: freeze on the first frame of the next tick
				idx = Math.min(stop, n - 1);
				holdIndex = idx;
				pauseAtIdx = -1;
			}
		}
		lastReplayIndex = idx;
		ensureScene(sceneAt(idx));
		int liveScale = probe == null ? 0 : probe.scale();
		int fScale = scaleAt(idx);
		float fpx = pxAt(idx), fpz = pzAt(idx);
		for (Object[] c : callsAt(idx))
		{
			Call cm = (Call) c[0];
			Object[] callArgs = resolveLive(dynIndex(cm, compensateZoom(cm, (Object[]) c[1], fScale, fpx, fpz, liveScale)));
			if (cm == Call.DRAW_SCENE)
			{
				// later calls of this frame project with the camera the frame is drawn from
				CameraProjection cam = CameraProjection.of(callArgs);
				replayCamera = cam != null ? cam : replayCamera;
			}
			try
			{
				cm.invoke(delegate, callArgs);
			}
			catch (RuntimeException | Error e)
			{
				// A bad replayed call must not take the client down.
				log.debug("replayed {} failed", cm.methodName, e);
			}
		}
	}

	// ---- multi-scene playback ----
	// The GPU plugin draws terrain from the zones of the scene it has loaded. A recording made across a map change holds
	// frames of several scenes, so before replaying a frame of another scene the GPU plugin is made to load a copy of it
	// with the calls the client itself uses (loadScene, loadScene(worldView, scene), swapScene). The live scene is put
	// back when playback ends.
	//
	// The client prepares a new scene in loadScene(worldView, scene) on its map-loading thread and installs it in
	// swapScene(scene) on the client thread; in between, the prepared zones wait inside the GPU plugin. So:
	//  - nothing here may throw out of the client's own scene calls;
	//  - while a live load is pending, no swap of ours runs;
	//  - a live load that starts while a recorded scene is loaded first waits for the client thread to put the live
	//    scene back;
	//  - a renderer failure in these calls during playback is contained: the client's scene is reloaded and playback ends.
	private volatile Object sceneInUse;    // the top-level scene the GPU plugin holds now (a recorded one while swapped)
	private volatile boolean sceneSwapFailed;
	private volatile Object clientScene;   // the top-level scene the client itself last handed the GPU plugin
	private volatile boolean liveLoadPending;
	private volatile boolean endRequested; // playback must end at the next frame
	// How long the map-loading thread waits for the client thread to put the live scene back.
	static volatile long loadGuardTimeoutMs = 2000;

	private Object sceneChange(Call m, Object[] args)
	{
		Scene sc = null;
		boolean top = false;
		try
		{
			Object a = m == Call.LOAD_SCENE_WV ? args[1] : m == Call.DESPAWN_WORLD_VIEW ? null : args[0];
			sc = a instanceof Scene ? (Scene) a : null;
			top = sc != null && sc.getWorldViewId() == 0;
		}
		catch (Throwable t)
		{
			log.debug("{} bookkeeping failed", m.methodName, t);
		}
		try
		{
			if (m == Call.INVALIDATE_ZONE && sc != null)
			{
				KEEPER.refreshZone(sc, ((Number) args[1]).intValue(), ((Number) args[2]).intValue());
			}
		}
		catch (Throwable t)
		{
			log.debug("{} bookkeeping failed", m.methodName, t);
		}
		try
		{
			if (top && m == Call.LOAD_SCENE_WV)
			{
				beforeLiveLoad();
			}
			if (capturing && !playing)
			{
				record(m, args);
			}
		}
		catch (Throwable t)
		{
			log.debug("{} bookkeeping failed", m.methodName, t);
		}
		if (playing && m == Call.INVALIDATE_ZONE && sceneInUse != null && sceneInUse != clientScene)
		{
			return null; // the GPU plugin holds a recorded scene: a live zone invalidation would rebuild it from the live scene
		}
		try
		{
			Object r = m.invoke(delegate, args);
			if (top && m == Call.SWAP_SCENE)
			{
				clientScene = sc;
				sceneInUse = sc;
				liveLoadPending = false;
			}
			return r;
		}
		catch (RuntimeException | Error t)
		{
			log.debug("{} bookkeeping failed", m.methodName, t);
			if (!playing)
			{
				throw t; // not caused by a replay: the client sees its renderer's error as it would without this plugin
			}
			recover(m, sc, top);
			return null;
		}
		finally
		{
			if (m == Call.LOAD_SCENE_WV && sc != null)
			{
				copyLoadedScene(sc);
			}
		}
	}

	/**
	 * Copies a scene right after the renderer's own loadScene: the GPU plugin's "hide unrelated maps" removes tiles from
	 * the scene there, and replay loads skip that step, so the copy must already be pruned.
	 */
	private void copyLoadedScene(Scene sc)
	{
		try
		{
			KEEPER.capture(sc);
		}
		catch (RuntimeException | Error t)
		{
			// A scene that cannot be copied cannot be replayed later; the client's load goes on.
			log.debug("could not copy the loaded scene", t);
		}
	}

	/** Map-loading thread, at a live top-level loadScene. */
	private void beforeLiveLoad()
	{
		liveLoadPending = true;
		// A swap of ours already running on the client thread finishes before this load reaches the renderer: switchScene
		// checks liveLoadPending after taking switchLock, and this thread takes the lock after raising liveLoadPending.
		switchLock.lock();
		switchLock.unlock();
		if (!playing || probe == null || sceneInUse == null || sceneInUse == clientScene)
		{
			return;
		}
		java.util.concurrent.CountDownLatch done = new java.util.concurrent.CountDownLatch(1);
		AtomicInteger phase = new AtomicInteger(); // 0 waiting, 1 running, 2 abandoned
		probe.onClientThread(() ->
		{
			if (!phase.compareAndSet(0, 1))
			{
				return;
			}
			try
			{
				putBackClientScene(true);
			}
			finally
			{
				done.countDown();
			}
		});
		if (!Uninterruptibles.awaitUninterruptibly(done, loadGuardTimeoutMs, TimeUnit.MILLISECONDS))
		{
			if (phase.compareAndSet(0, 2))
			{
				// the client thread never got to it: proceed, with our swaps off
				sceneSwapFailed = true;
				endRequested = true;
			}
			else
			{
				Uninterruptibles.awaitUninterruptibly(done); // it is running right now: let it finish before the load continues
			}
		}
	}

	/** A scene call failed during playback: reload the client's scene from its copy and end playback. */
	private void recover(Call m, Scene sc, boolean top)
	{
		sceneSwapFailed = true;
		endRequested = true;
		if (top && m == Call.SWAP_SCENE && sc != null)
		{
			clientScene = sc;
			liveLoadPending = false;
			sceneInUse = null; // unknown after a failed swap: force the reload below
			sceneSwapFailed = false;
			switchScene(sc);
			sceneSwapFailed = true;
		}
	}

	private void ensureScene(Object frameScene)
	{
		if (!(frameScene instanceof Scene))
		{
			return;
		}
		Scene scene = (Scene) frameScene;
		if (sceneSwapFailed || importedBase != null || probe == null || liveLoadPending)
		{
			return;
		}
		if (clientScene == null)
		{
			clientScene = probe.liveScene();
		}
		if (sceneInUse == null)
		{
			sceneInUse = clientScene;
		}
		if (scene == sceneInUse)
		{
			return;
		}
		if (probe.liveScene() != clientScene)
		{
			return; // the client changed scenes without this wrapper seeing it
		}
		if (!(clientScene instanceof Scene) || KEEPER.get(scene) == null || ((Scene) clientScene).isInstance())
		{
			return; // no copy to load, or the live scene is an instance: draw over the live one
		}
		if (sceneInUse == clientScene)
		{
			// Leaving the live scene: copy it now, so the restore shows the world as it is.
			try
			{
				KEEPER.capture((Scene) clientScene);
			}
			catch (RuntimeException e)
			{
				return;
			}
		}
		else if (KEEPER.get((Scene) clientScene) == null)
		{
			return; // no way back to the live scene
		}
		switchScene(scene);
	}

	// Held while a swap of ours runs.
	private final java.util.concurrent.locks.ReentrantLock switchLock = new java.util.concurrent.locks.ReentrantLock();

	private void switchScene(Scene target)
	{
		switchScene(target, false);
	}

	/** forLoadGuard: the map-loading thread is waiting for exactly this swap, so a pending load does not stop it. */
	private void switchScene(Scene target, boolean forLoadGuard)
	{
		switchLock.lock();
		try
		{
			if (liveLoadPending && !forLoadGuard)
			{
				return; // a live load started meanwhile: the renderer is the client's until its swapScene
			}
			switchSceneNow(target);
		}
		finally
		{
			switchLock.unlock();
		}
	}

	private void switchSceneNow(Scene target)
	{
		try
		{
			Object wv = probe.liveWorldView();
			Scene copy = KEEPER.get(target);
			if (copy == null)
			{
				return;
			}
			Object live = clientScene;
			Scene load = SceneKeeper.withoutZoneReuse((StandIns.StandInScene) copy, live instanceof Scene && ((Scene) live).isInstance());
			Call.LOAD_SCENE.invoke(delegate, new Object[]{load});
			if (wv instanceof net.runelite.api.WorldView)
			{
				Call.LOAD_SCENE_WV.invoke(delegate, new Object[]{wv, load});
			}
			Call.SWAP_SCENE.invoke(delegate, new Object[]{load});
			sceneInUse = target;
		}
		catch (RuntimeException | Error e)
		{
			sceneSwapFailed = true; // never retry a failing swap: fall back to drawing over the live scene
			log.warn("scene swap failed", e);
		}
	}

	/** Puts the client's own scene back into the GPU plugin if playback swapped another one in. */
	private void restoreLiveScene()
	{
		if (probe == null || sceneInUse == null || importedBase != null || liveLoadPending)
		{
			return;
		}
		putBackClientScene(false);
	}

	private void putBackClientScene(boolean forLoadGuard)
	{
		Object live = clientScene;
		if (live instanceof Scene && live != sceneInUse)
		{
			boolean was = sceneSwapFailed;
			sceneSwapFailed = false;
			switchScene((Scene) live, forLoadGuard);
			sceneSwapFailed = was || sceneSwapFailed;
		}
	}

	/** True when this recording can be played in another map area: recorded in this session and no swap has failed. */
	static boolean canSwapScenes(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return !r.sceneSwapFailed && r.importedBase == null;
	}

	// Stands for "the scene loaded now" in frames rebuilt from a file.
	private static final Object LIVE_SCENE = new Object();
	private volatile int[] importedBase; // the recorded scene base {x, y} when this recording came from a file

	// The client's camera projection, from its own calls (kept while recording and while playing).
	private volatile Object liveProjection;
	// the camera of the frame being replayed, as the projection the client would have passed with it
	private volatile CameraProjection replayCamera;

	private void noteProjection(Object[] args)
	{
		if (args != null)
		{
			for (Object a : args)
			{
				if (a instanceof net.runelite.api.Projection && !(a instanceof net.runelite.api.FloatProjection))
				{
					liveProjection = a;
					return;
				}
			}
		}
	}

	private Object[] resolveLive(Object[] args)
	{
		if (args == null || (importedBase == null && store == null))
		{
			return args;
		}
		Object live = null;
		Object[] out = null;
		for (int i = 0; i < args.length; i++)
		{
			Object a = args[i];
			if (a == LIVE_SCENE || a instanceof FileReplay.LiveProjection)
			{
				if (out == null)
				{
					out = args.clone();
				}
				if (a == LIVE_SCENE)
				{
					live = live != null ? live : probe == null ? null : probe.liveScene();
					out[i] = live;
				}
				else
				{
					Object p = replayCamera != null ? replayCamera : liveProjection;
					out[i] = p != null ? p : ((FileReplay.LiveProjection) a).fallback;
				}
			}
		}
		return out == null ? args : out;
	}

	private void endPlayback()
	{
		restoreLiveScene();
		playing = false;
		Runnable r = onPlaybackEnd;
		if (r != null)
		{
			r.run();
		}
	}

	private static DrawRecorder handler(DrawCallbacks cb)
	{
		return (DrawRecorder) cb;
	}

	/** {recorded base x, y, the recorded scene's base now x, y, live base x, y, 1 if the recorded scene is the live one}. */
	static int[] sceneInfo(DrawCallbacks cb, Scene live)
	{
		DrawRecorder r = handler(cb);
		int[] ib = r.importedBase;
		if (ib != null)
		{
			return live == null ? null : new int[]{ib[0], ib[1], ib[0], ib[1], live.getBaseX(), live.getBaseY(), 0};
		}
		synchronized (r.sceneIds)
		{
			if (r.sceneBase.isEmpty() || live == null)
			{
				return null;
			}
			int id = Collections.min(r.sceneBase.keySet());
			int[] rb = r.sceneBase.get(id);
			Scene o = r.sceneObjs.get(id);
			return new int[]{rb[0], rb[1], o.getBaseX(), o.getBaseY(), live.getBaseX(), live.getBaseY(), o == live ? 1 : 0};
		}
	}

	/** Local position {x, z} of the player in the first retained frame, or null. */
	static float[] firstPlayer(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		synchronized (r.lock)
		{
			if (r.nFrames() == 0 || Float.isNaN(r.pxAt(0)))
			{
				return null;
			}
			return new float[]{r.pxAt(0), r.pzAt(0)};
		}
	}

	/** {positionMs, spanMs} of the retained recording for the panel's timeline slider; position is 0 unless playing. */
	static long[] timeline(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		long base, span, holdWall = -1;
		synchronized (r.lock)
		{
			if (r.nFrames() < 2)
			{
				return null;
			}
			base = r.wallAt(0);
			span = r.wallAt(r.nFrames() - 1) - base;
			if (r.playing && r.holdIndex >= 0)
			{
				holdWall = r.wallAt(Math.min(r.holdIndex, r.nFrames() - 1)) - base;
			}
		}
		long pos = 0;
		if (r.playing)
		{
			pos = holdWall >= 0 ? holdWall : Math.min(span, Math.max(0, System.currentTimeMillis() - r.playStartMs));
		}
		return new long[]{pos, span};
	}

	/** True in "paused mode": frozen on a frame (pause, hold) or animating one tick step that will freeze by itself. */
	static boolean isPaused(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return r.playing && (r.holdIndex >= 0 || r.pauseAtIdx >= 0);
	}

	/** Index of the recorded frame currently shown (the paused frame, else the last replayed one). */
	static int shownIndex(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return r.holdIndex >= 0 ? r.holdIndex : r.lastReplayIndex;
	}

	/** Freezes playback on the frame currently shown (also stops an animating tick step where it is). */
	static boolean pause(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		if (!r.playing)
		{
			return false;
		}
		if (r.holdIndex < 0)
		{
			r.holdIndex = Math.max(0, r.lastReplayIndex);
		}
		r.pauseAtIdx = -1;
		return true;
	}

	/** Continues real-time playback: from the frozen frame, or, mid tick step, just without the freeze at its end. */
	static boolean resume(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		if (!r.playing || (r.holdIndex < 0 && r.pauseAtIdx < 0))
		{
			return false;
		}
		if (r.holdIndex >= 0)
		{
			synchronized (r.lock)
			{
				if (r.nFrames() == 0)
				{
					return false;
				}
				int idx = Math.min(r.holdIndex, r.nFrames() - 1);
				r.playStartMs = System.currentTimeMillis() - (r.wallAt(idx) - r.wallAt(0));
			}
			r.alignPending = true;
			r.holdIndex = -1;
		}
		r.pauseAtIdx = -1;
		return true;
	}

	/** Auto-repeat only extends a running step when the playhead is within this many ms of the step's end. */
	static volatile long repeatExtendWithinMs = 250;
	/** A discrete step press may queue at most this many ticks ahead of the one being shown. */
	static volatile int maxQueuedTicks = 4;

	/** Discrete step (a tap or a click). */
	static int stepTick(DrawCallbacks cb, int dir)
	{
		return stepTick(cb, dir, false);
	}

	/**
	 * Steps by game ticks. Forward (dir > 0) PLAYS the frames up to the first frame of the next tick at recorded speed,
	 * then freezes. A discrete press while a step is animating queues one more tick (up to maxQueuedTicks); a key
	 * auto-repeat (repeat = true) only extends the run once the playhead is within repeatExtendWithinMs of its end, so
	 * holding the key plays on continuously and stops within a tick of letting go, never running ahead.
	 * Backward (dir < 0) freezes and jumps to the START of the current tick, or of the previous tick if already at a start.
	 * Returns the frame the step is heading to / now shows, or -1 if not in paused mode.
	 */
	static int stepTick(DrawCallbacks cb, int dir, boolean repeat)
	{
		DrawRecorder r = handler(cb);
		if (!r.playing || (r.holdIndex < 0 && r.pauseAtIdx < 0))
		{
			return -1;
		}
		synchronized (r.lock)
		{
			int n = r.nFrames();
			if (n == 0)
			{
				return -1;
			}
			int shown = Math.max(0, Math.min(r.holdIndex >= 0 ? r.holdIndex : r.lastReplayIndex, n - 1));
			long base = r.wallAt(0);
			if (dir > 0)
			{
				boolean running = r.pauseAtIdx >= 0;
				int from = running ? Math.min(r.pauseAtIdx, n - 1) : shown;   // a running step is extended from its end
				if (running)
				{
					long ahead = r.wallAt(from) - r.wallAt(shown);
					if (repeat && ahead > repeatExtendWithinMs)
					{
						return from;   // key auto-repeat while the current tick is still playing: ignore it
					}
					if (r.tickAt(from) - r.tickAt(shown) >= maxQueuedTicks)
					{
						return from;   // queue is full
					}
				}
				int tick = r.tickAt(from), target = from, next = Integer.MAX_VALUE;
				for (int i = from; i < n; i++)
				{
					int t = r.tickAt(i);
					if (t > tick && t < next)
					{
						next = t;
						target = i;
					}
					if (t > tick && t == next)
					{
						break; // first frame of the nearest later tick
					}
				}
				if (target == from)
				{
					return from; // already at the last tick
				}
				if (r.holdIndex >= 0)
				{
					// frozen: start real-time from the frozen frame
					r.playStartMs = System.currentTimeMillis() - (r.wallAt(shown) - base);
					r.holdIndex = -1;
				}
				r.pauseAtIdx = target;
				return target;
			}
			// backward: stop any animating step first
			r.holdIndex = shown;
			r.pauseAtIdx = -1;
			int tick = r.tickAt(shown);
			int start = shown;
			while (start > 0 && r.tickAt(start - 1) == tick)
			{
				start--;                       // first frame of the tick being shown
			}
			int target = start;
			if (start == shown)
			{
				// already at the start of this tick: go to the start of the previous tick
				int prev = Integer.MIN_VALUE, at = shown;
				for (int i = shown; i >= 0; i--)
				{
					int t = r.tickAt(i);
					if (t < tick && t > prev)
					{
						prev = t;
						at = i;
					}
				}
				if (prev != Integer.MIN_VALUE)
				{
					while (at > 0 && r.tickAt(at - 1) == prev)
					{
						at--;
					}
					target = at;
				}
			}
			r.holdIndex = target;
			return target;
		}
	}

	/** Game tick of the frame being shown (paused frame, else the last replayed one), or -1. */
	static int replayTick(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		synchronized (r.lock)
		{
			int i = r.holdIndex >= 0 ? r.holdIndex : r.lastReplayIndex;
			return i >= 0 && i < r.nFrames() ? r.tickAt(i) : -1;
		}
	}

	/**
	 * Writes the retained frames as a binary table: int magic, int count, then per frame long wallMs, int tick, int scale,
	 * byte keyframe, 16 unused bytes, float playerX, float playerZ, int length, the 2D-layer delta. Returns the frame count.
	 */
	static int exportFrames(DrawCallbacks cb, java.io.OutputStream os) throws java.io.IOException
	{
		DrawRecorder r = handler(cb);
		java.io.DataOutputStream d = new java.io.DataOutputStream(os);
		if (r.store != null)
		{
			// the 2D layer as playback shows it, in the file's format: changes, and the whole layer every 60th frame
			FrameStore st = r.store;
			int n = st.size();
			d.writeInt(RecordingFile.FRAMES_MAGIC);
			d.writeInt(n);
			int[] prev = null;
			for (int i = 0; i < n; i++)
			{
				int[] ui = st.ui(i);
				boolean key = i % UI_KEYFRAME_EVERY == 0 || ui == null || prev == null || prev.length != ui.length;
				byte[] u = ui == null ? new byte[0] : UiFrames.encode(key ? null : prev, ui);
				if (ui != null)
				{
					prev = prev != null && prev.length == ui.length ? prev : new int[ui.length];
					System.arraycopy(ui, 0, prev, 0, ui.length);
				}
				d.writeLong(st.wallMs(i));
				d.writeInt(st.tick(i));
				d.writeInt(st.scale(i));
				d.writeByte(key ? 1 : 0);
				d.writeLong(0); // unused
				d.writeLong(0);
				d.writeFloat(st.playerX(i));
				d.writeFloat(st.playerZ(i));
				d.writeInt(u.length);
				d.write(u);
			}
			d.flush();
			return n;
		}
		List<RawFrame> frames;
		synchronized (r.lock)
		{
			frames = new ArrayList<>(r.retained);
		}
		d.writeInt(RecordingFile.FRAMES_MAGIC);
		d.writeInt(frames.size());
		for (RawFrame f : frames)
		{
			d.writeLong(f.wallMs);
			d.writeInt(f.tick);
			d.writeInt(f.scale);
			d.writeByte(f.keyframe ? 1 : 0);
			d.writeLong(0); // unused
			d.writeLong(0);
			d.writeFloat(f.playerX);
			d.writeFloat(f.playerZ);
			byte[] u = f.uiDelta == null ? new byte[0] : f.uiDelta;
			d.writeInt(u.length);
			d.write(u);
		}
		d.flush();
		return frames.size();
	}

	/** Jumps a running playback to offsetMs (real-time mode) or to the frame at that time (hold mode). */
	static void seek(DrawCallbacks cb, long offsetMs)
	{
		DrawRecorder r = handler(cb);
		if (r.holdIndex >= 0)
		{
			synchronized (r.lock)
			{
				if (r.nFrames() == 0)
				{
					return;
				}
				r.holdIndex = r.indexAtTime(r.wallAt(0) + offsetMs);
			}
		}
		else
		{
			r.playStartMs = System.currentTimeMillis() - Math.max(0, offsetMs);
			r.alignPending = true;
		}
	}

	/** Ends capture: from now on this wrapper only forwards and, when asked, replays. */
	// Saving after a recording stops: how many queued frames were left to code, and whether the last step has begun.
	private volatile int saveFrames = -1;
	private volatile boolean saveFinishing;

	/**
	 * Stops capturing at once and saves without blocking the caller: the writer codes the frames still queued, finishes
	 * the last batch, runs done (on the writer thread) and shuts down. False (and nothing queued yet) when the writer's
	 * queue is full: call again later.
	 */
	static boolean finishCapture(DrawCallbacks cb, Runnable done)
	{
		DrawRecorder r = handler(cb);
		r.capturing = false;
		java.util.concurrent.ThreadPoolExecutor w = r.writer;
		if (w.isShutdown())
		{
			if (r.store != null)
			{
				r.store.finish();
				r.logKept();
			}
			r.saveFrames = 0;
			r.saveFinishing = true;
			done.run();
			return true;
		}
		// only the writer takes from the queue now, so room seen here is still there for the execute below
		if (w.getQueue().remainingCapacity() == 0)
		{
			return false;
		}
		r.saveFrames = w.getQueue().size();
		w.execute(() ->
		{
			r.saveFinishing = true;
			try
			{
				if (r.store != null)
				{
					r.store.finish();
					r.logKept();
				}
			}
			catch (RuntimeException e)
			{
				log.debug("could not finish the recording", e);
			}
			try
			{
				done.run();
			}
			finally
			{
				w.shutdown();
			}
		});
		return true;
	}

	/** While saving: the share of queued frames coded so far, 1 once only the last step is left; -1 when not saving. */
	static double savingProgress(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		int total = r.saveFrames;
		if (total < 0)
		{
			return -1;
		}
		if (r.saveFinishing || total == 0)
		{
			return 1;
		}
		int left = Math.max(0, r.writer.getQueue().size() - 1); // the last step waits behind the frames
		return Math.max(0, Math.min(1, (total - left) / (double) total));
	}

	private void logKept()
	{
		log.debug("kept {} frames in about {} KB at \"{}\", {} KB of that the 2D layer, {} models; the writer fell behind on {} frames "
				+ "(2D layer not kept) and {} more (frame not kept)", store.size(), store.bytes() >> 10, store.preset.name,
			store.uiBytes() >> 10, store.modelCount(), uiSkipped, framesSkipped);
	}

	static void stopCapture(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		r.capturing = false;
		if (r.store != null)
		{
			// wait for the writer to code the frames still queued, then finish the last batch
			try
			{
				if (r.writer.isShutdown())
				{
					r.store.finish();
				}
				else
				{
					Uninterruptibles.getUninterruptibly(r.writer.submit(r.store::finish), 30, TimeUnit.SECONDS);
				}
			}
			catch (java.util.concurrent.ExecutionException | java.util.concurrent.TimeoutException | java.util.concurrent.RejectedExecutionException e)
			{
				log.debug("could not finish the recording", e);
			}
			r.logKept();
			return;
		}
		synchronized (r.lock)
		{
			long ui = 0;
			for (RawFrame f : r.retained)
			{
				ui += f.uiDelta == null ? 0 : f.uiDelta.length;
			}
			log.debug("kept {} frames in about {} KB, {} KB of that the 2D layer", r.nFrames(), r.retainedBytes >> 10, ui >> 10);
		}
	}

	/** Estimated bytes held by retained frames. */
	static long retainedBytes(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		if (r.store != null)
		{
			return r.store.bytes();
		}
		synchronized (r.lock)
		{
			return r.retainedBytes;
		}
	}

	/** Wall time (ms) at which the recording filled its memory and stopped recording, or -1 while there is room. */
	static long fullSince(DrawCallbacks cb)
	{
		return handler(cb).fullAt;
	}

	/** Frames a recording has dropped from its start to stay within its memory (0 until it is full). */
	static int droppedFrames(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return r.store == null ? 0 : r.store.dropped();
	}

	/** The preset a recording is kept at, or null (a recording read from a file). */
	static Presets.Preset preset(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return r.store == null ? null : r.store.preset;
	}

	/** Bytes per second the recording grows at in the long run, or 0 while that is not known yet. */
	static double steadyRate(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return r.store == null ? 0 : r.store.steadyRate();
	}

	static int retainedFrames(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		synchronized (r.lock)
		{
			return r.nFrames();
		}
	}

	static boolean hasRetained(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		synchronized (r.lock)
		{
			return r.nFrames() > 0;
		}
	}

	static void startPlayback(DrawCallbacks cb, Runnable onEnd)
	{
		startPlayback(cb, onEnd, -1, 0);
	}

	/** Waits (up to 30 s) until the writer thread has kept every frame handed to it so far. */
	static void awaitWriter(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		if (r.store == null || r.writer.isShutdown())
		{
			return; // nothing can be queued on a writer that has stopped
		}
		try
		{
			Uninterruptibles.getUninterruptibly(r.writer.submit(() ->
			{
			}), 30, TimeUnit.SECONDS);
		}
		catch (java.util.concurrent.ExecutionException | java.util.concurrent.TimeoutException | java.util.concurrent.RejectedExecutionException e)
		{
			log.debug("writer did not finish", e);
		}
	}

	/** Starts offsetMs into the recording. holdIndex >= 0 starts frozen on that frame. */
	static void startPlayback(DrawCallbacks cb, Runnable onEnd, int holdIndex, long offsetMs)
	{
		awaitWriter(cb);
		DrawRecorder r = handler(cb);
		r.holdIndex = holdIndex;
		r.pauseAtIdx = -1;
		r.uiBuf = null;
		r.uiAppliedIdx = -1;
		r.onPlaybackEnd = onEnd;
		r.playStartMs = System.currentTimeMillis() - Math.max(0, offsetMs);
		r.alignPending = holdIndex < 0;
		r.lastReplayIndex = -1;
		r.clientScene = r.probe == null ? null : r.probe.liveScene();
		r.sceneInUse = r.clientScene;
		r.liveLoadPending = false;
		r.endRequested = false;
		r.playing = true;
	}

	/** Zoom scale recorded for the frame being replayed, or 0. */
	static int replayScale(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		int i = r.lastReplayIndex;
		return i >= 0 && i < r.nFrames() ? r.scaleAt(i) : 0;
	}

	static void stopPlayback(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		r.restoreLiveScene();
		r.playing = false;
	}

	// FloatProjection -> its frozen copy for the frame being recorded; guarded by lock, cleared at every frame end.
	private final Map<Object, Object> projCache = new IdentityHashMap<>();

	/**
	 * The frozen copy of the geometry with this id: the one an earlier call made if a retained frame still draws it,
	 * else a new copy of the live model, which holds that geometry now. Null when no copy can be made; playback then
	 * falls back to the live object.
	 */
	private Model snapshot(Integer id, Model live)
	{
		Model snap = snapshots.get(id);
		if (snap == null && snapshotter != null)
		{
			try
			{
				snap = snapshotter.apply(live, arrays);
				arrays.added(160);
				snapshots.put(id, snap);
			}
			catch (RuntimeException e)
			{
				return null;
			}
		}
		return snap;
	}

	/** Copy of the call's args with everything the client rewrites after the frame replaced by a frozen copy. */
	private Object[] frozen(Call m, Object[] args, Object[] row)
	{
		if (args == null)
		{
			return null;
		}
		Object[] out = args.clone();
		for (int i = 0; i < out.length; i++)
		{
			if (out[i] instanceof Model && row[i + 1] instanceof Map)
			{
				Object id = ((Map<?, ?>) row[i + 1]).get("model");
				Model snap = id instanceof Integer ? snapshot((Integer) id, (Model) out[i]) : null;
				if (snap != null)
				{
					out[i] = snap;
				}
			}
		}
		if (m == Call.DRAW_DYNAMIC_WORKER && out[0] instanceof Integer && (Integer) out[0] > 0)
		{
			out[0] = 0; // replay deals the worker index itself (dynIndex), so equal calls of different workers can be shared
		}
		for (int i = 0; i < out.length; i++)
		{
			if (out[i] instanceof Set)
			{
				// preSceneDraw's roof-removal set is one object the client keeps mutating
				out[i] = new HashSet<Object>((Set<?>) out[i]);
			}
			else if (out[i] instanceof net.runelite.api.FloatProjection && !(out[i] instanceof FrozenProjection))
			{
				// A boat's transform: the client changes and recycles the object after the frame.
				out[i] = projCache.computeIfAbsent(out[i], k -> FrozenProjection.of((net.runelite.api.FloatProjection) k));
			}
		}
		if (m.methodName.equals("drawTemp"))
		{
			for (int i = 0; i < out.length; i++)
			{
				if (out[i] instanceof net.runelite.api.GameObject)
				{
					out[i] = snapshotGameObject((net.runelite.api.GameObject) out[i]);
				}
			}
		}
		return out;
	}

	private byte[] captureUi(boolean key)
	{
		if (probe == null)
		{
			return null;
		}
		int[] px = probe.uiPixels();
		if (px == null)
		{
			return null;
		}
		byte[] enc = UiFrames.encode(key ? null : prevUi, px);
		if (prevUi == null || prevUi.length != px.length)
		{
			prevUi = new int[px.length];
		}
		System.arraycopy(px, 0, prevUi, 0, px.length);
		return enc;
	}

	/** Overwrites the live 2D layer with the recorded one for the frame currently being replayed. */
	private void applyUi()
	{
		int idx = lastReplayIndex;
		if (store != null)
		{
			if (probe == null || idx < 0 || idx >= store.size())
			{
				return;
			}
			int[] shown = store.ui(idx);
			int[] live = probe.uiPixels();
			uiSizeMismatch = live != null && shown != null && live.length != shown.length;
			if (live != null && shown != null && live.length == shown.length)
			{
				System.arraycopy(shown, 0, live, 0, live.length);
			}
			return;
		}
		List<RawFrame> frames = playFrames;
		if (probe == null || idx < 0 || idx >= frames.size())
		{
			return;
		}
		// Decode from the nearest keyframe, or on from the last applied frame when that is already past it.
		int from = idx;
		while (from > 0 && !frames.get(from).keyframe)
		{
			from--;
		}
		if (uiAppliedIdx >= from && uiAppliedIdx <= idx)
		{
			from = uiAppliedIdx + 1;
		}
		else
		{
			uiBuf = null;
		}
		for (int i = from; i <= idx; i++)
		{
			byte[] e = frames.get(i).uiDelta;
			if (e == null)
			{
				continue;
			}
			int len = UiFrames.length(e);
			if (uiBuf == null || uiBuf.length != len)
			{
				uiBuf = new int[len];
			}
			UiFrames.applyFrame(e, uiBuf, frames.get(i).keyframe);
		}
		uiAppliedIdx = idx;
		int[] live = probe.uiPixels();
		uiSizeMismatch = live != null && uiBuf != null && live.length != uiBuf.length;
		if (live != null && uiBuf != null && live.length == uiBuf.length)
		{
			System.arraycopy(uiBuf, 0, live, 0, live.length);
		}
	}

	private volatile boolean uiSizeMismatch;

	/** True while playing when the recorded 2D layer has a different pixel count than the live canvas (window resized). */
	static boolean uiSizeMismatch(DrawCallbacks cb)
	{
		DrawRecorder r = handler(cb);
		return r.playing && r.uiSizeMismatch;
	}

	/**
	 * The renderer projects with the live zoom, while the recorded 2D layer was drawn at the recorded zoom. Screen size
	 * goes as scale / depth, so the camera's offset from its focus (the point above the player it orbits) is scaled by
	 * liveScale / recordedScale. Exact at the focus depth, approximate away from it. Only the args handed to the
	 * renderer change.
	 */
	private static Object[] compensateZoom(Call m, Object[] args, int fScale, float fpx, float fpz, int liveScale)
	{
		if (args == null || liveScale <= 0 || fScale <= 0 || liveScale == fScale || Float.isNaN(fpx))
		{
			return args;
		}
		int ix;
		switch (m.methodName)
		{
			case "drawScene":
				ix = 0;
				break;
			case "preSceneDraw":
				ix = args.length > 1 && args[1] instanceof Number ? 1 : 2;
				break;
			default:
				return args;
		}
		if (args.length < ix + 4 || !(args[ix] instanceof Number))
		{
			return args;
		}
		double cx = ((Number) args[ix]).doubleValue(), cy = ((Number) args[ix + 1]).doubleValue();
		double cz = ((Number) args[ix + 2]).doubleValue(), pitch = ((Number) args[ix + 3]).doubleValue();
		double h = Math.hypot(cx - fpx, cz - fpz);
		double fy = cy + h * Math.tan(pitch);
		double k = (double) liveScale / fScale;
		Object[] out = args.clone();
		out[ix] = like(args[ix], fpx + k * (cx - fpx));
		out[ix + 1] = like(args[ix + 1], fy + k * (cy - fy));
		out[ix + 2] = like(args[ix + 2], fpz + k * (cz - fpz));
		return out;
	}

	private static Object like(Object original, double v)
	{
		return original instanceof Float ? (Object) (float) v : (Object) v;
	}

	/** drawDynamic's worker index is dealt round-robin, as the client's dispatcher does; -1 (not a worker) stays. */
	private Object[] dynIndex(Call m, Object[] args)
	{
		if (m != Call.DRAW_DYNAMIC_WORKER || args == null || !(args[0] instanceof Integer) || (Integer) args[0] < 0)
		{
			return args;
		}
		Object[] out = args.clone();
		out[0] = (int) (dynCounter++ % Math.max(1, dynWorkers));
		return out;
	}

	/**
	 * drawTemp, which draws actors, is handed a temporary GameObject wrapper that the client reuses for every actor. By
	 * replay time it no longer holds the actor, so what the GPU plugin reads from it is captured at record time.
	 */
	static net.runelite.api.GameObject snapshotGameObject(net.runelite.api.GameObject go)
	{
		StandIns.StandInGameObject g = new StandIns.StandInGameObject();
		try
		{
			g.renderable = snapshotRenderable(go.getRenderable());
			g.hash = go.getHash();
			g.id = go.getId();
			g.x = go.getX();
			g.y = go.getY();
			g.z = go.getZ();
			g.plane = go.getPlane();
			g.orientation = go.getOrientation();
			g.modelOrientation = go.getModelOrientation();
			g.config = go.getConfig();
			g.sizeX = go.sizeX();
			g.sizeY = go.sizeY();
			g.min = go.getSceneMinLocation();
			g.max = go.getSceneMaxLocation();
			g.wv = go.getWorldView();
		}
		catch (RuntimeException e)
		{
			return go; // cannot snapshot: fall back to the live object
		}
		return g;
	}

	/** drawTemp also reads the actor's model height and render mode, which can fail once the actor has despawned. */
	static net.runelite.api.Renderable snapshotRenderable(net.runelite.api.Renderable r)
	{
		if (r == null)
		{
			return null;
		}
		StandIns.StandInRenderable s = new StandIns.StandInRenderable();
		try
		{
			s.height = r.getModelHeight();
			s.mode = r.getRenderMode();
		}
		catch (RuntimeException e)
		{
			return r;
		}
		return s;
	}
}

package com.renderreplay;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.Arrays;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.TileObject;

/**
 * Stand-in objects rebuilt from a recording file, so a saved recording can be replayed without the live objects it was
 * captured from. The GPU plugin only reads these through the API interfaces, so an object that answers the same getters
 * from the saved values is enough; anything not saved answers a neutral default.
 */
final class FileReplay
{
	private FileReplay()
	{
	}

	static Object convert(Object v, Class<?> t)
	{
		if (v instanceof Number)
		{
			Number n = (Number) v;
			if (t == int.class || t == Integer.class) return n.intValue();
			if (t == long.class || t == Long.class) return n.longValue();
			if (t == float.class || t == Float.class) return n.floatValue();
			if (t == double.class || t == Double.class) return n.doubleValue();
			if (t == short.class || t == Short.class) return n.shortValue();
			if (t == byte.class || t == Byte.class) return n.byteValue();
		}
		return v;
	}

	// ---- JSON helpers (null-safe, typed arrays) ----

	static int[] ints(JsonObject o, String k)
	{
		if (!o.has(k) || o.get(k).isJsonNull())
		{
			return null;
		}
		JsonArray a = o.getAsJsonArray(k);
		int[] r = new int[a.size()];
		for (int i = 0; i < r.length; i++) r[i] = a.get(i).getAsInt();
		return r;
	}

	static float[] floats(JsonObject o, String k)
	{
		if (!o.has(k) || o.get(k).isJsonNull())
		{
			return null;
		}
		JsonArray a = o.getAsJsonArray(k);
		float[] r = new float[a.size()];
		for (int i = 0; i < r.length; i++) r[i] = a.get(i).getAsFloat();
		return r;
	}

	static byte[] bytes(JsonObject o, String k)
	{
		if (!o.has(k) || o.get(k).isJsonNull())
		{
			return null;
		}
		JsonArray a = o.getAsJsonArray(k);
		byte[] r = new byte[a.size()];
		for (int i = 0; i < r.length; i++) r[i] = (byte) a.get(i).getAsInt();
		return r;
	}

	static short[] shorts(JsonObject o, String k)
	{
		if (!o.has(k) || o.get(k).isJsonNull())
		{
			return null;
		}
		JsonArray a = o.getAsJsonArray(k);
		short[] r = new short[a.size()];
		for (int i = 0; i < r.length; i++) r[i] = (short) a.get(i).getAsInt();
		return r;
	}

	private static int intOr(JsonObject o, String k, int d)
	{
		return o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsInt() : d;
	}

	// ---- stand-ins ----

	/** From a models.jsonl "model" entry. Equal arrays are shared through the pool. */
	static Model model(JsonObject b, ArrayPool pool)
	{
		StandIns.StandInModel m = new StandIns.StandInModel();
		m.vn = intOr(b, "vn", 0);
		m.fn = intOr(b, "fn", 0);
		m.vx = pool.share(floats(b, "vx"));
		m.vy = pool.share(floats(b, "vy"));
		m.vz = pool.share(floats(b, "vz"));
		m.f1 = pool.share(ints(b, "f1"));
		m.f2 = pool.share(ints(b, "f2"));
		m.f3 = pool.share(ints(b, "f3"));
		m.c1 = pool.share(ints(b, "c1"));
		m.c2 = pool.share(ints(b, "c2"));
		m.c3 = pool.share(ints(b, "c3"));
		m.tr = pool.share(bytes(b, "tr"));
		m.pri = pool.share(bytes(b, "pri"));
		m.ft = pool.share(shorts(b, "ft"));
		m.fb = pool.share(bytes(b, "fb"));
		m.tf = pool.share(bytes(b, "tf"));
		m.t1 = pool.share(ints(b, "t1"));
		m.t2 = pool.share(ints(b, "t2"));
		m.t3 = pool.share(ints(b, "t3"));
		int[] ov = ints(b, "ov");
		if (ov != null && ov.length == 4)
		{
			m.ov0 = (byte) ov[0];
			m.ov1 = (byte) ov[1];
			m.ov2 = (byte) ov[2];
			m.ov3 = (byte) ov[3];
		}
		m.tp = (byte) intOr(b, "tp", 0);
		boundsCylinder(m);
		return m;
	}

	/**
	 * A frozen copy of a live model, holding the same fields a models.jsonl "model" entry carries. The client reuses and
	 * rewrites its Model objects, so playback draws these copies instead. Arrays are copied, never shared with the live
	 * model; equal arrays of different copies are shared through the pool.
	 */
	static Model copyOf(Model src, ArrayPool pool)
	{
		StandIns.StandInModel m = new StandIns.StandInModel();
		m.vn = src.getVerticesCount();
		m.fn = src.getFaceCount();
		m.vx = pool.share(copy(src.getVerticesX(), m.vn));
		m.vy = pool.share(copy(src.getVerticesY(), m.vn));
		m.vz = pool.share(copy(src.getVerticesZ(), m.vn));
		m.f1 = pool.share(copy(src.getFaceIndices1(), m.fn));
		m.f2 = pool.share(copy(src.getFaceIndices2(), m.fn));
		m.f3 = pool.share(copy(src.getFaceIndices3(), m.fn));
		m.c1 = pool.share(copy(src.getFaceColors1(), m.fn));
		m.c2 = pool.share(copy(src.getFaceColors2(), m.fn));
		m.c3 = pool.share(copy(src.getFaceColors3(), m.fn));
		m.tr = pool.share(copy(src.getFaceTransparencies(), m.fn));
		m.pri = pool.share(copy(src.getFaceRenderPriorities(), m.fn));
		m.ft = pool.share(copy(src.getFaceTextures(), m.fn));
		m.fb = pool.share(copy(src.getFaceBias(), m.fn));
		// the texture arrays are indexed by texture face, not by face: keep their full length
		byte[] tf = src.getTextureFaces();
		m.tf = pool.share(tf == null ? null : tf.clone());
		int[] t1 = src.getTexIndices1(), t2 = src.getTexIndices2(), t3 = src.getTexIndices3();
		m.t1 = pool.share(t1 == null ? null : t1.clone());
		m.t2 = pool.share(t2 == null ? null : t2.clone());
		m.t3 = pool.share(t3 == null ? null : t3.clone());
		m.ov0 = src.getOverrideAmount();
		m.ov1 = src.getOverrideHue();
		m.ov2 = src.getOverrideSaturation();
		m.ov3 = src.getOverrideLuminance();
		m.tp = src.getTransparency();
		boundsCylinder(m);
		return m;
	}

	/**
	 * Radius and diameter as the client's calculateBoundsCylinder() computes them. The client fills them in lazily, and
	 * the GPU plugin asks for that just before it sorts a model's faces by depth; a stand-in cannot compute them later.
	 */
	private static void boundsCylinder(StandIns.StandInModel m)
	{
		float top = 0, bottom = 0, xz2 = 0;
		for (int i = 0; m.vx != null && i < m.vn && i < m.vx.length; i++)
		{
			float x = m.vx[i], y = m.vy[i], z = m.vz[i];
			top = Math.max(top, -y);
			bottom = Math.max(bottom, y);
			xz2 = Math.max(xz2, x * x + z * z);
		}
		int xz = (int) (Math.sqrt(xz2) + 0.99);
		m.rad = (int) (Math.sqrt(xz * xz + top * top) + 0.99);
		m.dia = m.rad + (int) (Math.sqrt(xz * xz + bottom * bottom) + 0.99);
	}

	// The API hands back oversized backing arrays; only the first n entries are real.

	private static int[] copy(int[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	private static float[] copy(float[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	private static short[] copy(short[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	private static byte[] copy(byte[] a, int n)
	{
		return a == null ? null : Arrays.copyOf(a, Math.min(n, a.length));
	}

	/** From a models.jsonl "tilemodel" entry. */
	static SceneTileModel tileModel(JsonObject b)
	{
		StandIns.StandInTileModel t = new StandIns.StandInTileModel();
		t.vx = ints(b, "vx");
		t.vy = ints(b, "vy");
		t.vz = ints(b, "vz");
		t.f1 = ints(b, "f1");
		t.f2 = ints(b, "f2");
		t.f3 = ints(b, "f3");
		t.c1 = ints(b, "c1");
		t.c2 = ints(b, "c2");
		t.c3 = ints(b, "c3");
		t.tex = ints(b, "tex");
		t.flat = b.has("flat") && b.get("flat").getAsBoolean();
		return t;
	}

	/** From a drawScenePaint row cell: [rbg, sw, se, nw, ne, texture, flat]. */
	static SceneTilePaint paint(JsonArray c)
	{
		StandIns.StandInPaint p = new StandIns.StandInPaint();
		p.rbg = c.get(0).getAsInt();
		p.sw = c.get(1).getAsInt();
		p.se = c.get(2).getAsInt();
		p.nw = c.get(3).getAsInt();
		p.ne = c.get(4).getAsInt();
		p.texture = c.get(5).getAsInt();
		p.flat = c.get(6).getAsInt() != 0;
		return p;
	}

	/** From a {"proj":..,"s":[[o],[x128],[y128],[z128]]} cell: an affine map rebuilt from four sample points. */
	/**
	 * Stands for the camera projection in rebuilt frames. The four points the recorder samples give the renderer wrong
	 * depths for this projection, so playback hands the renderer the client's own camera projection instead, and this
	 * rebuilt one only until it has seen one.
	 */
	static final class LiveProjection
	{
		final Projection fallback;

		LiveProjection(Projection fallback)
		{
			this.fallback = fallback;
		}
	}

	static Projection projection(JsonObject o)
	{
		JsonArray s = o.getAsJsonArray("s");
		final float[][] p = new float[4][3];
		for (int i = 0; i < 4; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				p[i][j] = s.get(i).getAsJsonArray().get(j).getAsFloat();
			}
		}
		return new Projection()
		{
			@Override
			public float[] project(float x, float y, float z)
			{
				return project(x, y, z, new float[3]);
			}

			@Override
			public float[] project(float x, float y, float z, float[] out)
			{
				for (int j = 0; j < 3; j++)
				{
					out[j] = p[0][j] + (p[1][j] - p[0][j]) * x / 128f + (p[2][j] - p[0][j]) * y / 128f + (p[3][j] - p[0][j]) * z / 128f;
				}
				return out;
			}
		};
	}

	/** From a {"rend":..,"h":..,"m":..} cell. */
	static Renderable renderable(JsonObject o)
	{
		StandIns.StandInRenderable r = new StandIns.StandInRenderable();
		r.height = intOr(o, "h", 0);
		r.mode = intOr(o, "m", 0);
		return r;
	}

	/** From a {"tobj":id,"plane":..,"hash":..} cell. */
	static TileObject tileObject(JsonObject o)
	{
		StandIns.StandInTileObject t = new StandIns.StandInTileObject();
		t.id = intOr(o, "tobj", 0);
		t.plane = intOr(o, "plane", 0);
		t.hash = o.has("hash") ? o.get("hash").getAsLong() : 0L;
		return t;
	}

	/** From a {"go":id,"hash":..,"xyz":[..],...} cell (drawTemp's actor wrapper). */
	static GameObject gameObject(JsonObject o)
	{
		StandIns.StandInGameObject g = new StandIns.StandInGameObject();
		g.id = intOr(o, "go", 0);
		g.hash = o.has("hash") ? o.get("hash").getAsLong() : 0L;
		int[] xyz = ints(o, "xyz");
		if (xyz != null)
		{
			g.x = xyz[0];
			g.y = xyz[1];
			g.z = xyz[2];
		}
		g.plane = intOr(o, "plane", 0);
		int[] ori = ints(o, "ori");
		if (ori != null)
		{
			g.orientation = ori[0];
			g.modelOrientation = ori[1];
			g.config = ori[2];
		}
		int[] size = ints(o, "size");
		if (size != null)
		{
			g.sizeX = size[0];
			g.sizeY = size[1];
		}
		int[] box = ints(o, "box");
		if (box != null)
		{
			g.min = new net.runelite.api.Point(box[0], box[1]);
			g.max = new net.runelite.api.Point(box[2], box[3]);
		}
		if (o.has("h"))
		{
			g.renderable = renderable(o);
		}
		return g;
	}
}

package com.renderreplay;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.api.SceneTilePaint;

/**
 * A recording held compressed in memory, at one of the presets. Frames come in from the recorder's writer thread and
 * are kept in batches of 60: the frames' times and positions, their world calls (WorldCodec, every n-th frame for the
 * lower presets) and their 2D layer (UiCodec), deflated once the batch is complete. Model geometry is kept once
 * (ModelStore). When the budget is exceeded, the oldest frames go, a 2D-layer anchor span at a time.
 * Playback reads frames back through the accessors: calls are rebuilt the way an imported recording's are.
 */
@lombok.extern.slf4j.Slf4j
final class FrameStore
{
	static final int GROUP = 60;
	private static final int PENDING_FRAMES = 240;

	interface Scenes
	{
		/** The scene object recorded under this id, or null. */
		Object scene(int id);
	}

	final Presets.Preset preset;
	private final UiCodec.Opts uiOpts;
	private final ModelStore models;
	private final WorldCodec.Encoder wenc = new WorldCodec.Encoder();
	private final UiCodec.Encoder uenc;
	private final Gson gson;
	private final Scenes scenes;

	private static final class Group
	{
		final int first;
		int count;
		// while open
		long[] wall = new long[GROUP];
		int[] tick = new int[GROUP], scale = new int[GROUP], cycle = new int[GROUP], scene = new int[GROUP];
		int[] uiWidth = new int[GROUP], uiN = new int[GROUP], uiFlags = new int[GROUP];
		float[] px = new float[GROUP], pz = new float[GROUP], yaw = new float[GROUP];
		byte[][] ui = new byte[GROUP][];
		Bytes.Out world = new Bytes.Out(2048);
		final Set<Integer> modelIds = new HashSet<>();
		// once closed
		byte[] meta, uiAll, worldZ;
		int[] ids;
		long bytes;

		Group(int first)
		{
			this.first = first;
		}

		boolean closed()
		{
			return meta != null;
		}
	}

	/** A batch's per-frame data, unpacked. */
	private static final class Meta
	{
		long[] wall;
		int[] tick, scale, cycle, scene, uiWidth, uiN, uiFlags, uiOff;
		float[] px, pz, yaw;
	}

	private final List<Group> groups = new ArrayList<>();
	private final List<Object> sceneList = new ArrayList<>();
	private final Map<Object, Integer> sceneIndex = new java.util.IdentityHashMap<>();
	private int base, next;
	private long closedBytes, closedEver;
	private long rateWall0 = -1, rateBytes0, lastWall, firstWall = -1;
	private final Map<Integer, Object> pending = new ConcurrentHashMap<>();
	// geometry ids stored or waiting to be: anything else the recorder should offer again when it is drawn
	private final Set<Integer> known = ConcurrentHashMap.newKeySet();
	private final Map<Integer, Integer> pendingAt = new HashMap<>();
	private final Map<String, JsonArray> firstSeen = new HashMap<>();

	FrameStore(Presets.Preset preset, Gson gson, Scenes scenes)
	{
		this.preset = preset;
		this.uiOpts = preset.uiOpts();
		this.uenc = new UiCodec.Encoder(uiOpts);
		this.models = new ModelStore(preset.vq, preset.poseTol);
		this.models.onFree = known::remove;
		this.gson = gson;
		this.scenes = scenes;
	}

	/** New model geometry seen by the recorder (any thread); kept until a stored frame draws it. */
	void offerBody(int id, Object body)
	{
		pending.put(id, body);
		known.add(id);
	}

	/** True when the geometry with this id is neither stored nor waiting: the recorder should offer it again. */
	boolean lost(int id)
	{
		return !known.contains(id);
	}

	// ---- recording (writer thread) ----

	/**
	 * Adds one frame. rows are the frame's calls as the recorder describes them ([method, args...]); pixels the 2D
	 * layer (or null), width its width; mm the minimap {cx, cy, r} in layer pixels (or null).
	 */
	synchronized void append(long wallMs, int tick, int scale, int cycle, float[] player, float yaw, Object scene,
		List<Object[]> rows, int[] pixels, int width, int[] mm)
	{
		int f = next++;
		if (firstWall < 0)
		{
			firstWall = wallMs;
		}
		lastWall = wallMs;
		groupLastWall = wallMs;
		Group g = groups.isEmpty() ? null : groups.get(groups.size() - 1);
		if (g == null || g.closed() || g.count == GROUP)
		{
			if (g != null && !g.closed())
			{
				close(g);
			}
			g = new Group(f);
			groups.add(g);
			wenc.reset();
		}
		int k = g.count++;
		g.wall[k] = wallMs;
		g.tick[k] = tick;
		g.scale[k] = scale;
		g.cycle[k] = cycle;
		g.px[k] = player == null ? Float.NaN : player[0];
		g.pz[k] = player == null ? Float.NaN : player[1];
		g.yaw[k] = yaw;
		g.scene[k] = sceneId(scene);
		if (pixels != null && width > 0)
		{
			g.ui[k] = uenc.encode(pixels, width, f, yaw, mm);
			g.uiWidth[k] = width;
			g.uiN[k] = pixels.length;
			g.uiFlags[k] = 4 | (uenc.wasKey ? 1 : 0) | (uenc.wasStandalone ? 2 : 0);
		}
		else
		{
			g.ui[k] = new byte[0];
		}
		if (f % preset.every == 0)
		{
			List<JsonArray> world = worldRows(rows);
			for (JsonArray r : world)
			{
				for (JsonElement a : r)
				{
					if (a.isJsonObject() && a.getAsJsonObject().size() == 1 && a.getAsJsonObject().has("model"))
					{
						int id = a.getAsJsonObject().get("model").getAsInt();
						if (!models.has(id))
						{
							Object body = pending.remove(id);
							pendingAt.remove(id);
							if (body != null)
							{
								models.add(id, body instanceof JsonObject ? (JsonObject) body : gson.toJsonTree(body).getAsJsonObject());
							}
						}
						if (models.has(id) && g.modelIds.add(id))
						{
							models.ref(id);
						}
					}
				}
			}
			byte[] b = wenc.encode(world);
			g.world.varint(b.length);
			g.world.bytes(b);
		}
		// geometry no stored frame drew soon after it appeared is dropped
		for (Integer id : pending.keySet())
		{
			pendingAt.putIfAbsent(id, f);
		}
		pendingAt.entrySet().removeIf(e ->
		{
			if (f - e.getValue() > PENDING_FRAMES + 2 * preset.every)
			{
				pending.remove(e.getKey());
				if (!models.has(e.getKey()))
				{
					known.remove(e.getKey());
				}
				return true;
			}
			return false;
		});
		if (g.count == GROUP)
		{
			close(g);
		}
	}

	/** Finishes the batch being filled (when recording stops). */
	synchronized void finish()
	{
		if (!groups.isEmpty() && !groups.get(groups.size() - 1).closed())
		{
			close(groups.get(groups.size() - 1));
		}
		for (Integer id : pending.keySet())
		{
			if (!models.has(id))
			{
				known.remove(id);
			}
		}
		pending.clear();
		pendingAt.clear();
	}

	private int sceneId(Object scene)
	{
		if (scene == null)
		{
			return -1;
		}
		Integer i = sceneIndex.get(scene);
		if (i == null)
		{
			i = sceneList.size();
			sceneList.add(scene);
			sceneIndex.put(scene, i);
		}
		return i;
	}

	private static final java.util.Set<String> WORLD = new java.util.HashSet<>(Arrays.asList("drawScene", "preSceneDraw", "postSceneDraw",
		"postDrawScene", "drawScenePaint", "drawSceneTileModel", "drawDynamic", "drawTemp", "drawPass", "drawZoneOpaque", "drawZoneAlpha", "draw"));

	/** The calls playback replays, as JSON rows: worker numbers as the plugin keeps them, poses frozen if asked. */
	private List<JsonArray> worldRows(List<Object[]> rows)
	{
		List<JsonArray> out = new ArrayList<>(rows.size());
		for (Object[] r : rows)
		{
			if (r.length == 0 || !(r[0] instanceof String) || !WORLD.contains(r[0]))
			{
				continue;
			}
			Call m = Call.find((String) r[0], r.length - 1);
			if (m == null || m.isFrameEnd())
			{
				continue;
			}
			JsonArray row = gson.toJsonTree(r).getAsJsonArray();
			if (m == Call.DRAW_DYNAMIC_WORKER && row.get(1).getAsInt() > 0)
			{
				row.set(1, new com.google.gson.JsonPrimitive(0));
			}
			if (preset.freeze && (m == Call.DRAW_DYNAMIC || m == Call.DRAW_DYNAMIC_WORKER || m == Call.DRAW_TEMP))
			{
				String id = WorldCodec.identity(row);
				JsonArray first = firstSeen.get(id);
				if (first == null)
				{
					firstSeen.put(id, row);
				}
				else if (first.size() == row.size())
				{
					for (int i = 1; i < row.size(); i++)
					{
						JsonElement a = row.get(i), b = first.get(i);
						if (a.isJsonObject() && b.isJsonObject())
						{
							if (a.getAsJsonObject().has("model"))
							{
								row.set(i, b);
							}
							else if (a.getAsJsonObject().has("h") && b.getAsJsonObject().has("h"))
							{
								JsonObject o = a.getAsJsonObject().deepCopy();
								o.add("h", b.getAsJsonObject().get("h"));
								row.set(i, o);
							}
						}
					}
				}
			}
			out.add(row);
		}
		return out;
	}

	private void close(Group g)
	{
		Bytes.Out m = new Bytes.Out(g.count * 16);
		long pw = 0;
		int pt = 0, ps = 0, pc = 0, puw = 0, pun = 0;
		int[] pf = {0, 0, 0};
		int total = 0;
		for (int k = 0; k < g.count; k++)
		{
			m.zz(g.wall[k] - pw);
			m.zz(g.tick[k] - pt);
			m.zz(g.scale[k] - ps);
			m.zz(g.cycle[k] - pc);
			m.zz(g.scene[k]);
			m.zz(g.uiWidth[k] - puw);
			m.zz(g.uiN[k] - pun);
			m.varint(g.uiFlags[k]);
			m.varint(g.ui[k].length);
			int[] fl = {Float.floatToIntBits(g.px[k]), Float.floatToIntBits(g.pz[k]), Float.floatToIntBits(g.yaw[k])};
			for (int i = 0; i < 3; i++)
			{
				m.varint((fl[i] ^ pf[i]) & 0xFFFFFFFFL);
				pf[i] = fl[i];
			}
			pw = g.wall[k];
			pt = g.tick[k];
			ps = g.scale[k];
			pc = g.cycle[k];
			puw = g.uiWidth[k];
			pun = g.uiN[k];
			total += g.ui[k].length;
		}
		g.meta = ModelStore.deflate(m.toArray());
		g.uiAll = new byte[total];
		int p = 0;
		for (int k = 0; k < g.count; k++)
		{
			System.arraycopy(g.ui[k], 0, g.uiAll, p, g.ui[k].length);
			p += g.ui[k].length;
		}
		g.worldZ = ModelStore.deflate(g.world.toArray());
		g.ids = new int[g.modelIds.size()];
		int i = 0;
		for (int id : g.modelIds)
		{
			g.ids[i++] = id;
		}
		g.wall = null;
		g.tick = g.scale = g.cycle = g.scene = g.uiWidth = g.uiN = g.uiFlags = null;
		g.px = g.pz = g.yaw = null;
		g.ui = null;
		g.world = null;
		g.bytes = 160 + g.meta.length + g.uiAll.length + g.worldZ.length + 4L * g.ids.length;
		closedBytes += g.bytes;
		closedEver += g.bytes;
		// the steady rate is measured from 10 seconds in, past the burst of everything seen for the first time
		long w = groupLastWall;
		if (rateWall0 < 0 && firstWall >= 0 && w - firstWall >= 10_000)
		{
			rateWall0 = w;
			rateBytes0 = closedEver + models.added();
		}
	}

	/** Drops the oldest anchor spans while over budget, keeping at least minFrames and the span being filled. */
	synchronized void trim(long budget, int minFrames, int maxFrames)
	{
		int span = uiOpts.key * uiOpts.anchorEvery;
		while ((bytes() > budget || size() > maxFrames) && groups.size() > 1)
		{
			int end = (base / span + 1) * span;
			if (end >= next - GROUP || size() - (end - base) < minFrames)
			{
				return;
			}
			while (!groups.isEmpty() && groups.get(0).first < end && groups.get(0).closed())
			{
				Group g = groups.remove(0);
				closedBytes -= g.bytes;
				for (int id : g.ids)
				{
					models.unref(id);
				}
			}
			base = end;
			decodedGroups.clear();
			metaCache.clear();
			udec = null;
		}
	}

	private long groupLastWall;

	/** Frames dropped from the start of the recording to stay within its memory. */
	synchronized int dropped()
	{
		return base;
	}

	/** Bytes per second this recording grows at in the long run, or 0 until it has run long enough to tell. */
	synchronized double steadyRate()
	{
		if (rateWall0 < 0 || lastWall - rateWall0 < 10_000)
		{
			return 0;
		}
		return (closedEver + models.added() - rateBytes0) * 1000.0 / (lastWall - rateWall0);
	}

	/** Estimated bytes held: batches, models and the batch being filled. */
	synchronized long bytes()
	{
		long open = 0;
		Group g = groups.isEmpty() ? null : groups.get(groups.size() - 1);
		if (g != null && !g.closed())
		{
			open = 3000 + g.world.n;
			for (int k = 0; k < g.count; k++)
			{
				open += g.ui[k].length;
			}
		}
		return closedBytes + models.bytes() + open;
	}

	synchronized long uiBytes()
	{
		long b = 0;
		for (Group g : groups)
		{
			if (g.closed())
			{
				b += g.uiAll.length;
			}
			else
			{
				for (int k = 0; k < g.count; k++)
				{
					b += g.ui[k].length;
				}
			}
		}
		return b;
	}

	synchronized int size()
	{
		return next - base;
	}

	// ---- frame data ----

	private final LinkedHashMap<Group, Meta> metaCache = new LinkedHashMap<Group, Meta>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Group, Meta> e)
		{
			return size() > 64;
		}
	};

	private Group groupOf(int f)
	{
		int i = (f - groups.get(0).first) / GROUP;
		return groups.get(Math.max(0, Math.min(groups.size() - 1, i)));
	}

	private Meta meta(Group g)
	{
		if (!g.closed())
		{
			Meta m = new Meta();
			m.wall = g.wall;
			m.tick = g.tick;
			m.scale = g.scale;
			m.cycle = g.cycle;
			m.scene = g.scene;
			m.uiWidth = g.uiWidth;
			m.uiN = g.uiN;
			m.uiFlags = g.uiFlags;
			m.px = g.px;
			m.pz = g.pz;
			m.yaw = g.yaw;
			return m;
		}
		Meta m = metaCache.get(g);
		if (m != null)
		{
			return m;
		}
		m = new Meta();
		int n = g.count;
		m.wall = new long[n];
		m.tick = new int[n];
		m.scale = new int[n];
		m.cycle = new int[n];
		m.scene = new int[n];
		m.uiWidth = new int[n];
		m.uiN = new int[n];
		m.uiFlags = new int[n];
		m.uiOff = new int[n + 1];
		m.px = new float[n];
		m.pz = new float[n];
		m.yaw = new float[n];
		Bytes.In r = new Bytes.In(ModelStore.inflate(g.meta));
		long pw = 0;
		int pt = 0, ps = 0, pc = 0, puw = 0, pun = 0;
		int[] pf = {0, 0, 0};
		for (int k = 0; k < n; k++)
		{
			m.wall[k] = pw += r.zz();
			m.tick[k] = pt += (int) r.zz();
			m.scale[k] = ps += (int) r.zz();
			m.cycle[k] = pc += (int) r.zz();
			m.scene[k] = (int) r.zz();
			m.uiWidth[k] = puw += (int) r.zz();
			m.uiN[k] = pun += (int) r.zz();
			m.uiFlags[k] = r.varint32();
			m.uiOff[k + 1] = m.uiOff[k] + r.varint32();
			for (int i = 0; i < 3; i++)
			{
				pf[i] ^= (int) r.varint();
			}
			m.px[k] = Float.intBitsToFloat(pf[0]);
			m.pz[k] = Float.intBitsToFloat(pf[1]);
			m.yaw[k] = Float.intBitsToFloat(pf[2]);
		}
		metaCache.put(g, m);
		return m;
	}

	/** Frame data of the i-th kept frame (0 = oldest): {wallMs} etc. through the small accessors below. */
	synchronized long wallMs(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).wall[f - g.first];
	}

	synchronized int tick(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).tick[f - g.first];
	}

	synchronized int scale(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).scale[f - g.first];
	}

	synchronized int cycle(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).cycle[f - g.first];
	}

	synchronized float playerX(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).px[f - g.first];
	}

	synchronized float playerZ(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).pz[f - g.first];
	}

	synchronized Object scene(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		int s = meta(g).scene[f - g.first];
		return s >= 0 && s < sceneList.size() ? sceneList.get(s) : null;
	}

	/** Index of the last kept frame at or before wall time t (binary search), or 0. */
	synchronized int indexAt(long t)
	{
		int lo = 0, hi = size() - 1;
		while (lo < hi)
		{
			int mid = (lo + hi + 1) >>> 1;
			if (wallMs(mid) <= t)
			{
				lo = mid;
			}
			else
			{
				hi = mid - 1;
			}
		}
		return lo;
	}

	// ---- world calls for playback ----

	private static final class Decoded
	{
		final Map<Integer, List<Object[]>> calls = new HashMap<>();
		final Map<Integer, String[]> ids = new HashMap<>();
	}

	private final LinkedHashMap<Group, Decoded> decodedGroups = new LinkedHashMap<Group, Decoded>(4, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Group, Decoded> e)
		{
			return size() > 3;
		}
	};
	private final ArrayPool arrays = new ArrayPool();
	private final LinkedHashMap<Integer, Object> modelCache = new LinkedHashMap<Integer, Object>(256, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Integer, Object> e)
		{
			return size() > 3000;
		}
	};

	private Decoded decoded(Group g)
	{
		Decoded d = decodedGroups.get(g);
		if (d != null)
		{
			return d;
		}
		d = new Decoded();
		byte[] raw = g.closed() ? ModelStore.inflate(g.worldZ) : g.world.toArray();
		Bytes.In r = new Bytes.In(raw);
		WorldCodec.Decoder dec = new WorldCodec.Decoder();
		Map<String, Object> cache = new HashMap<>();
		for (int f = g.first; f < g.first + g.count; f++)
		{
			if (f % preset.every != 0)
			{
				continue;
			}
			if (r.done())
			{
				break;
			}
			int len = r.varint32();
			byte[] b = Arrays.copyOfRange(r.b, r.p, r.p + len);
			r.p += len;
			List<JsonArray> rows = dec.decode(b);
			List<Object[]> calls = new ArrayList<>(rows.size());
			String[] ids = new String[rows.size()];
			for (JsonArray row : rows)
			{
				Call m = Call.find(row.get(0).getAsString(), row.size() - 1);
				if (m == null)
				{
					continue;
				}
				Object[] args = new Object[m.types.length];
				boolean missing = false;
				for (int i = 0; i < args.length; i++)
				{
					args[i] = arg(row.get(i + 1), m.types[i], cache);
					JsonElement cell = row.get(i + 1);
					if (args[i] == null && m.types[i] == net.runelite.api.Model.class && cell != null && cell.isJsonObject() && cell.getAsJsonObject().has("model"))
					{
						missing = true;
					}
				}
				if (missing)
				{
					continue; // geometry that was never kept: drawing it would only fail in the renderer
				}
				ids[calls.size()] = WorldCodec.identity(row);
				calls.add(new Object[]{m, args});
			}
			d.calls.put(f, calls);
			d.ids.put(f, ids);
		}
		decodedGroups.put(g, d);
		return d;
	}

	/** One recorded argument back as the object the renderer is handed (as an import builds it). */
	private Object arg(JsonElement cell, Class<?> type, Map<String, Object> cache)
	{
		if (cell == null || cell.isJsonNull())
		{
			return null;
		}
		if (cell.isJsonPrimitive())
		{
			com.google.gson.JsonPrimitive p = cell.getAsJsonPrimitive();
			if (p.isBoolean())
			{
				return p.getAsBoolean();
			}
			if (p.isNumber())
			{
				return FileReplay.convert(p.getAsNumber(), type);
			}
			return type == String.class ? p.getAsString() : null;
		}
		String key = cell.toString();
		Object hit = cache.get(key);
		if (hit != null)
		{
			return hit;
		}
		Object made = null;
		if (cell.isJsonArray())
		{
			if (type == SceneTilePaint.class)
			{
				made = FileReplay.paint(cell.getAsJsonArray());
			}
		}
		else
		{
			JsonObject o = cell.getAsJsonObject();
			if (o.has("scene"))
			{
				made = scenes.scene(o.get("scene").getAsInt());
			}
			else if (o.has("model"))
			{
				int id = o.get("model").getAsInt();
				made = modelCache.get(id);
				if (made == null)
				{
					JsonObject b = models.body(id);
					made = b == null ? null : FileReplay.model(b, arrays);
					if (made != null)
					{
						modelCache.put(id, made);
					}
				}
			}
			else if (o.has("tilemodel"))
			{
				JsonObject b = models.body(o.get("tilemodel").getAsInt());
				made = b == null ? null : FileReplay.tileModel(b);
			}
			else if (o.has("go"))
			{
				made = FileReplay.gameObject(o);
			}
			else if (o.has("tobj"))
			{
				made = FileReplay.tileObject(o);
			}
			else if (o.has("rend"))
			{
				made = FileReplay.renderable(o);
			}
			else if (o.has("proj"))
			{
				// a boat's transform: the renderer reads its matrix, so it gets a frozen copy of that matrix
				if (o.has("m") && o.get("m").isJsonArray() && o.getAsJsonArray("m").size() == 16)
				{
					float[] mat = new float[16];
					for (int i = 0; i < 16; i++)
					{
						mat[i] = o.getAsJsonArray("m").get(i).getAsFloat();
					}
					made = FrozenProjection.ofMatrix(mat);
				}
				else
				{
					made = o.has("s") ? new FileReplay.LiveProjection(FileReplay.projection(o)) : null;
				}
			}
			else if (o.has("set"))
			{
				Set<Integer> set = new HashSet<>();
				for (JsonElement x : o.getAsJsonArray("set"))
				{
					set.add(x.getAsInt());
				}
				made = set;
			}
		}
		if (made != null)
		{
			cache.put(key, made);
		}
		return made;
	}

	/** The world calls playback replays for the i-th kept frame: {Call, args} each. */
	synchronized List<Object[]> calls(int i)
	{
		int f = base + i, k = preset.every;
		int a = f - Math.floorMod(f, k);
		if (a < base)
		{
			a += k;
		}
		if (a >= next)
		{
			return java.util.Collections.emptyList();
		}
		Decoded da = decoded(groupOf(a));
		List<Object[]> ca = da.calls.get(a);
		if (ca == null)
		{
			return java.util.Collections.emptyList();
		}
		if (k == 1 || !preset.interp || f <= a || a + k >= next)
		{
			return ca;
		}
		Decoded db = decoded(groupOf(a + k));
		List<Object[]> cb = db.calls.get(a + k);
		if (cb == null)
		{
			return ca;
		}
		return Interp.between(ca, da.ids.get(a), cb, db.ids.get(a + k), (f - a) / (double) k);
	}

	// ---- 2D layer for playback ----

	private UiCodec.Decoder udec;
	private int udecF = -1;

	/** The 2D layer playback shows at the i-th kept frame, full size (reused between calls), or null. */
	synchronized int[] ui(int i)
	{
		int f = base + i;
		if (f < base || f >= next)
		{
			return null;
		}
		if (udec != null && udecF == f)
		{
			return lastUi;
		}
		if (udec != null && f > udecF && f - udecF <= 2 * uiOpts.key)
		{
			// playback skipped a few frames: decode on through them
			for (int c = udecF + 1; c <= f; c++)
			{
				decodeUi(c);
			}
			return lastUi;
		}
		if (udec == null || udecF != f - 1)
		{
			// a seek: from the last frame standing alone, through the checkpoints, to f
			int start = f;
			while (start > base && (uiFlags(start) & 2) == 0)
			{
				start--;
			}
			if ((uiFlags(start) & 2) == 0)
			{
				return null;
			}
			udec = new UiCodec.Decoder(uiOpts);
			int lastKey = start;
			for (int c = start + 1; c <= f; c++)
			{
				if ((uiFlags(c) & 1) != 0)
				{
					lastKey = c;
				}
			}
			decodeUi(start);
			for (int c = start + 1; c <= lastKey; c++)
			{
				if ((uiFlags(c) & 1) != 0)
				{
					decodeUi(c);
				}
			}
			for (int c = lastKey + 1; c <= f; c++)
			{
				decodeUi(c);
			}
			return lastUi;
		}
		decodeUi(f);
		return lastUi;
	}

	private int[] lastUi, uiOut;

	private int uiFlags(int f)
	{
		Group g = groupOf(f);
		return meta(g).uiFlags[f - g.first];
	}

	private void decodeUi(int f)
	{
		Group g = groupOf(f);
		Meta m = meta(g);
		int k = f - g.first;
		byte[] rec = g.closed() ? Arrays.copyOfRange(g.uiAll, m.uiOff[k], m.uiOff[k + 1]) : g.ui[k];
		if ((m.uiFlags[k] & 4) == 0)
		{
			udecF = f;
			return;
		}
		int[] layer = udec.decode(rec, f, m.yaw[k], m.uiN[k], m.uiWidth[k]);
		if (layer != null && layer.length != m.uiN[k])
		{
			// hand back an array as long as the client's, which can have a pixel past the last row
			if (uiOut == null || uiOut.length != m.uiN[k])
			{
				uiOut = new int[m.uiN[k]];
			}
			System.arraycopy(layer, 0, uiOut, 0, Math.min(layer.length, uiOut.length));
			layer = uiOut;
		}
		lastUi = layer;
		udecF = f;
	}

	/** Width of the i-th kept frame's 2D layer, or 0. */
	synchronized int uiWidth(int i)
	{
		int f = base + i;
		Group g = groupOf(f);
		return meta(g).uiWidth[f - g.first];
	}

	synchronized int modelCount()
	{
		return models.size();
	}
}

package com.renderreplay;

import java.util.Arrays;
import net.runelite.api.FloatProjection;

/**
 * A FloatProjection (the transform of a boat or other sub world view) copied when a frame is recorded. The client hands the
 * renderer a projection object per world entity and changes or recycles it afterwards, so replaying the live object draws the
 * boat with whatever it holds by then. GpuPlugin reads getProjection() (preSceneDraw uploads it as the entity matrix) and may call
 * project(). The matrix is column-major and affine: project(v) = M * (v, 1).
 */
final class FrozenProjection implements FloatProjection
{
	private final float[] m;

	private FrozenProjection(float[] m)
	{
		this.m = m;
	}

	/** A projection from a recorded column-major 4x4 matrix (as DrawRecorder.describe records a FloatProjection). */
	static FrozenProjection ofMatrix(float[] m)
	{
		return m == null || m.length != 16 ? null : new FrozenProjection(m.clone());
	}

	/**
	 * A frozen copy of p, or p itself when its project() is not the affine map of its matrix (then copying would change what the
	 * renderer computes). Checked on four points, the same ones DrawRecorder.describe records.
	 */
	static FloatProjection of(FloatProjection p)
	{
		try
		{
			float[] src = p.getProjection();
			if (src == null || src.length != 16)
			{
				return p;
			}
			FrozenProjection f = new FrozenProjection(src.clone());
			float[][] pts = {{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {0, 0, 128}};
			for (float[] v : pts)
			{
				float[] a = p.project(v[0], v[1], v[2]);
				float[] b = f.project(v[0], v[1], v[2]);
				for (int i = 0; i < 3; i++)
				{
					if (a == null || a.length < 3 || Math.abs(a[i] - b[i]) > 1e-3f * Math.max(1f, Math.abs(a[i])))
					{
						return p;
					}
				}
			}
			return f;
		}
		catch (RuntimeException e)
		{
			return p;
		}
	}

	@Override
	public boolean equals(Object o)
	{
		return o instanceof FrozenProjection && Arrays.equals(m, ((FrozenProjection) o).m);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(m);
	}

	@Override
	public float[] getProjection()
	{
		return m.clone();
	}

	@Override
	public float[] project(float x, float y, float z)
	{
		return project(x, y, z, new float[3]);
	}

	@Override
	public float[] project(float x, float y, float z, float[] out)
	{
		float[] o = out != null && out.length >= 3 ? out : new float[3];
		float px = m[0] * x + m[4] * y + m[8] * z + m[12];
		float py = m[1] * x + m[5] * y + m[9] * z + m[13];
		float pz = m[2] * x + m[6] * y + m[10] * z + m[14];
		o[0] = px;
		o[1] = py;
		o[2] = pz;
		return o;
	}
}

package com.renderreplay;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Calls between two kept frames, for presets that keep only every n-th frame: the camera and every object's position
 * and facing move smoothly from one kept frame to the next; poses and everything else stay as in the earlier one.
 */
final class Interp
{
	private Interp()
	{
	}

	private static double lerp(double a, double b, double t)
	{
		return a + (b - a) * t;
	}

	private static double lerpRad(double a, double b, double t)
	{
		double d = (b - a) % (2 * Math.PI);
		if (d > Math.PI)
		{
			d -= 2 * Math.PI;
		}
		if (d < -Math.PI)
		{
			d += 2 * Math.PI;
		}
		return a + d * t;
	}

	private static int lerpJau(int a, int b, double t)
	{
		int d = Math.floorMod(b - a + 1024, 2048) - 1024;
		return (int) Math.round(a + d * t) & 2047;
	}

	/** Calls a (with identities ida) moved a fraction t of the way to calls b (with identities idb). */
	static List<Object[]> between(List<Object[]> a, String[] ida, List<Object[]> b, String[] idb, double t)
	{
		Map<String, Object[]> byId = new HashMap<>();
		Object[] sceneB = null, preB = null;
		for (int j = 0; j < b.size(); j++)
		{
			Object[] c = b.get(j);
			Call m = (Call) c[0];
			if (m == Call.DRAW_SCENE)
			{
				sceneB = c;
			}
			else if (m == Call.PRE_SCENE_DRAW || m == Call.PRE_SCENE_DRAW_PROJ)
			{
				preB = c;
			}
			else if (idb[j] != null && idb[j].indexOf('#') > 0)
			{
				byId.put(idb[j], c);
			}
		}
		List<Object[]> out = new ArrayList<>(a.size());
		for (int j = 0; j < a.size(); j++)
		{
			Object[] c = a.get(j);
			Call m = (Call) c[0];
			Object[] args = (Object[]) c[1];
			try
			{
				if (m == Call.DRAW_SCENE && sceneB != null)
				{
					Object[] q = (Object[]) sceneB[1], o = args.clone();
					for (int i = 0; i < 4; i++)
					{
						o[i] = lerp((Double) args[i], (Double) q[i], t);
					}
					o[4] = lerpRad((Double) args[4], (Double) q[4], t);
					out.add(new Object[]{m, o});
					continue;
				}
				if ((m == Call.PRE_SCENE_DRAW || m == Call.PRE_SCENE_DRAW_PROJ) && preB != null && preB[0] == m)
				{
					Object[] q = (Object[]) preB[1], o = args.clone();
					int f0 = m == Call.PRE_SCENE_DRAW_PROJ ? 2 : 1;
					for (int i = f0; i < f0 + 4; i++)
					{
						o[i] = (float) lerp((Float) args[i], (Float) q[i], t);
					}
					o[f0 + 4] = (float) lerpRad((Float) args[f0 + 4], (Float) q[f0 + 4], t);
					out.add(new Object[]{m, o});
					continue;
				}
				if ((m == Call.DRAW_DYNAMIC || m == Call.DRAW_DYNAMIC_WORKER || m == Call.DRAW_TEMP) && ida[j] != null)
				{
					Object[] qc = byId.get(ida[j]);
					if (qc != null && qc[0] == m)
					{
						Object[] q = (Object[]) qc[1], o = args.clone();
						int l4 = args.length - 4;
						o[l4] = lerpJau((Integer) args[l4], (Integer) q[l4], t);
						for (int i = l4 + 1; i < args.length; i++)
						{
							o[i] = (int) Math.round(lerp((Integer) args[i], (Integer) q[i], t));
						}
						out.add(new Object[]{m, o});
						continue;
					}
				}
			}
			catch (RuntimeException e)
			{
				// an argument of another type than expected: leave the call as it was
			}
			out.add(c);
		}
		return out;
	}
}

package com.renderreplay;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.ByteArrayOutputStream;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;

/**
 * The model geometry of a recording, compressed. Faces, colours and the other per-face arrays are stored once each and
 * shared. A new pose is stored as the bit difference from the closest recent pose of the same model, so an animation's
 * poses cost little. Options trade exactness for size: vertices rounded to 1/vq units, and poses within poseTol units
 * of an earlier one replaced by it. Models live while a kept frame or a model built on them uses them.
 * Thread-safe: the writer thread adds, playback reads.
 */
final class ModelStore
{
	private static final String[] TOPO = {"f1", "f2", "f3", "c1", "c2", "c3", "tr", "pri", "ft", "fb", "tf", "t1", "t2", "t3"};
	private static final int MAX_DEPTH = 16, RECENT = 8, DECODED = 512;

	private final double vq, poseTol;

	private static final class Arr
	{
		byte[] data;  // deflated zigzag deltas
		char type;    // i int, b byte, s short
		int refs;
		String key;
	}

	private static final class Mod
	{
		byte[] blob;          // deflated, or null for an alias or a tile model kept as JSON
		String json;          // tile models and anything else kept as text
		int base = -1, alias = -1, depth;
		int[] arrays = new int[0];
		int refs, dependents;
		String topo;
	}

	private final Map<Integer, Mod> mods = new HashMap<>();
	private final Map<Integer, Arr> arrays = new HashMap<>();
	private final Map<String, Integer> arrayIds = new HashMap<>();
	private int nextArray;
	private long bytes, added;
	// recent poses per topology, for choosing a base: id and vertices
	private final Map<String, Deque<Object[]>> recent = new HashMap<>();
	private final LinkedHashMap<Integer, float[]> decodedVerts = new LinkedHashMap<Integer, float[]>(64, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Integer, float[]> e)
		{
			return size() > DECODED;
		}
	};

	ModelStore(double vq, double poseTol)
	{
		this.vq = vq;
		this.poseTol = poseTol;
	}

	/** Told the id of every model freed, so its geometry can be offered again if it is drawn again. */
	java.util.function.IntConsumer onFree = id ->
	{
	};

	synchronized boolean has(int id)
	{
		return mods.containsKey(id);
	}

	/** Estimated bytes held. */
	synchronized long bytes()
	{
		return bytes;
	}

	/** Bytes ever added, freed or not (for measuring the rate a recording grows at). */
	synchronized long added()
	{
		return added + bytes;
	}

	synchronized int size()
	{
		return mods.size();
	}

	/** Stores a geometry body (as the recorder writes it). Does nothing if the id is already stored. */
	synchronized void add(int id, JsonObject body)
	{
		if (mods.containsKey(id))
		{
			return;
		}
		Mod m = new Mod();
		mods.put(id, m);
		String kind = body.has("kind") ? body.get("kind").getAsString() : "model";
		if (!"model".equals(kind) || !body.has("vx") || body.get("vx").isJsonNull())
		{
			m.json = body.toString();
			bytes += cost(m);
			return;
		}
		float[] v = verts(body);
		int[] arr = new int[TOPO.length];
		StringBuilder topo = new StringBuilder().append(v.length / 3);
		for (int i = 0; i < TOPO.length; i++)
		{
			arr[i] = addArray(TOPO[i], body.get(TOPO[i]));
			topo.append(',').append(arr[i]);
		}
		m.topo = topo.toString();
		Deque<Object[]> rec = recent.computeIfAbsent(m.topo, k -> new ArrayDeque<>());
		if (poseTol > 0)
		{
			for (Object[] p : rec)
			{
				if (maxDiff((float[]) p[1], v) <= poseTol)
				{
					// close enough to an earlier pose: use that one
					for (int a : arr)
					{
						releaseArray(a);
					}
					m.alias = (Integer) p[0];
					m.topo = null;
					mods.get(m.alias).dependents++;
					bytes += cost(m);
					return;
				}
			}
		}
		m.arrays = arr;
		// the base: the closest recent pose of this topology whose chain is short enough
		Object[] best = null;
		double bestErr = Double.MAX_VALUE;
		for (Object[] p : rec)
		{
			Mod b = mods.get((Integer) p[0]);
			if (b == null || b.depth >= MAX_DEPTH)
			{
				continue;
			}
			double e = sumDiff((float[]) p[1], v, bestErr);
			if (e < bestErr)
			{
				bestErr = e;
				best = p;
			}
		}
		float[] base = best == null ? null : (float[]) best[1];
		if (best != null)
		{
			m.base = (Integer) best[0];
			Mod b = mods.get(m.base);
			b.dependents++;
			m.depth = b.depth + 1;
		}
		Bytes.Out w = new Bytes.Out(64 + v.length * 3);
		w.varint(v.length / 3);
		w.varint(body.has("fn") ? body.get("fn").getAsInt() : 0);
		int[] ov = ints(body.get("ov"));
		for (int i = 0; i < 4; i++)
		{
			w.zz(ov != null && i < ov.length ? ov[i] : 0);
		}
		w.zz(body.has("tp") ? body.get("tp").getAsInt() : 0);
		float[] stored = new float[v.length];
		if (vq > 0)
		{
			for (int i = 0; i < v.length; i++)
			{
				long q = Math.round(v[i] * vq);
				stored[i] = (float) (q / vq);
				long p = base != null ? Math.round(base[i] * vq) : i >= 3 ? Math.round(stored[i - 3] * vq) : 0;
				w.zz(q - p);
			}
		}
		else
		{
			for (int i = 0; i < v.length; i++)
			{
				stored[i] = v[i];
				int p = base != null ? Float.floatToIntBits(base[i]) : i >= 3 ? Float.floatToIntBits(v[i - 3]) : 0;
				w.varint((Float.floatToIntBits(v[i]) ^ p) & 0xFFFFFFFFL);
			}
		}
		m.blob = deflate(w.toArray());
		bytes += cost(m);
		rec.addFirst(new Object[]{id, stored});
		while (rec.size() > RECENT)
		{
			rec.removeLast();
		}
		decodedVerts.put(id, stored);
	}

	/** A kept frame uses this model. */
	synchronized void ref(int id)
	{
		Mod m = mods.get(id);
		if (m != null)
		{
			m.refs++;
		}
	}

	/** A kept frame that used this model was dropped. */
	synchronized void unref(int id)
	{
		Mod m = mods.get(id);
		if (m != null)
		{
			m.refs--;
			maybeFree(id, m);
		}
	}

	private static long cost(Mod m)
	{
		return m.blob != null ? 64 + m.blob.length : m.json != null ? 64 + m.json.length() : 48;
	}

	/** Frees the model if nothing uses it, then its base (or the pose it stands for) if that is now unused too. */
	private void maybeFree(int id, Mod first)
	{
		int cur = id;
		Mod m = first;
		while (m != null && m.refs <= 0 && m.dependents <= 0)
		{
			mods.remove(cur);
			onFree.accept(cur);
			decodedVerts.remove(cur);
			bytes -= cost(m);
			added += cost(m);
			for (int a : m.arrays)
			{
				releaseArray(a);
			}
			if (m.topo != null)
			{
				Deque<Object[]> rec = recent.get(m.topo);
				final int gone = cur;
				if (rec != null)
				{
					rec.removeIf(p -> (Integer) p[0] == gone);
				}
			}
			int next = m.alias >= 0 ? m.alias : m.base;
			if (next < 0)
			{
				return;
			}
			m = mods.get(next);
			if (m != null)
			{
				m.dependents--;
			}
			cur = next;
		}
	}

	/** The geometry body for playback (the shape FileReplay.model reads), or null if it is not stored. */
	synchronized JsonObject body(int id)
	{
		Mod m = mods.get(id);
		if (m == null)
		{
			return null;
		}
		if (m.alias >= 0)
		{
			return body(m.alias);
		}
		if (m.json != null)
		{
			return new com.google.gson.JsonParser().parse(m.json).getAsJsonObject();
		}
		Bytes.In r = new Bytes.In(inflate(m.blob));
		int vn = r.varint32(), fn = r.varint32();
		int[] ov = {(int) r.zz(), (int) r.zz(), (int) r.zz(), (int) r.zz()};
		int tp = (int) r.zz();
		float[] v = decodeVerts(id, m, r, vn);
		JsonObject b = new JsonObject();
		b.add("vx", floats(v, 0, vn));
		b.add("vy", floats(v, 1, vn));
		b.add("vz", floats(v, 2, vn));
		for (int i = 0; i < TOPO.length; i++)
		{
			if (m.arrays[i] >= 0)
			{
				b.add(TOPO[i], arrayJson(arrays.get(m.arrays[i])));
			}
		}
		b.addProperty("vn", vn);
		b.addProperty("fn", fn);
		JsonArray o = new JsonArray();
		for (int x : ov)
		{
			o.add(x);
		}
		b.add("ov", o);
		b.addProperty("tp", tp);
		b.addProperty("kind", "model");
		return b;
	}

	private float[] decodeVerts(int id, Mod m, Bytes.In r, int vn)
	{
		float[] cached = decodedVerts.get(id);
		if (cached != null)
		{
			return cached;
		}
		float[] base = null;
		if (m.base >= 0)
		{
			Mod b = mods.get(m.base);
			base = decodedVerts.get(m.base);
			if (base == null)
			{
				Bytes.In br = new Bytes.In(inflate(b.blob));
				int bvn = br.varint32();
				br.varint32();
				for (int i = 0; i < 5; i++)
				{
					br.zz();
				}
				base = decodeVerts(m.base, b, br, bvn);
			}
		}
		float[] v = new float[vn * 3];
		for (int i = 0; i < v.length; i++)
		{
			if (vq > 0)
			{
				long p = base != null ? Math.round(base[i] * vq) : i >= 3 ? Math.round(v[i - 3] * vq) : 0;
				v[i] = (float) ((r.zz() + p) / vq);
			}
			else
			{
				int p = base != null ? Float.floatToIntBits(base[i]) : i >= 3 ? Float.floatToIntBits(v[i - 3]) : 0;
				v[i] = Float.intBitsToFloat((int) r.varint() ^ p);
			}
		}
		decodedVerts.put(id, v);
		return v;
	}

	// ---- shared arrays ----

	private int addArray(String name, JsonElement e)
	{
		if (e == null || e.isJsonNull() || !e.isJsonArray())
		{
			return -1;
		}
		JsonArray a = e.getAsJsonArray();
		char type = name.equals("ft") ? 's' : (name.equals("tr") || name.equals("pri") || name.equals("fb") || name.equals("tf")) ? 'b' : 'i';
		long[] vals = new long[a.size()];
		for (int i = 0; i < vals.length; i++)
		{
			vals[i] = a.get(i).getAsLong();
		}
		String key = type + ":" + vals.length + ":" + Arrays.hashCode(vals) + ":" + hash2(vals);
		Integer id = arrayIds.get(key);
		if (id != null)
		{
			arrays.get(id).refs++;
			return id;
		}
		Bytes.Out w = new Bytes.Out(vals.length * 2 + 8);
		w.varint(vals.length);
		long prev = 0;
		for (long x : vals)
		{
			w.zz(x - prev);
			prev = x;
		}
		Arr r = new Arr();
		r.data = deflate(w.toArray());
		r.type = type;
		r.refs = 1;
		r.key = key;
		id = nextArray++;
		arrays.put(id, r);
		arrayIds.put(key, id);
		bytes += 48 + r.data.length;
		return id;
	}

	private void releaseArray(int id)
	{
		if (id < 0)
		{
			return;
		}
		Arr a = arrays.get(id);
		if (a != null && --a.refs <= 0)
		{
			arrays.remove(id);
			arrayIds.remove(a.key);
			bytes -= 48 + a.data.length;
			added += 48 + a.data.length;
		}
	}

	private static JsonArray arrayJson(Arr a)
	{
		Bytes.In r = new Bytes.In(inflate(a.data));
		int n = r.varint32();
		JsonArray out = new JsonArray();
		long prev = 0;
		for (int i = 0; i < n; i++)
		{
			prev += r.zz();
			out.add(prev);
		}
		return out;
	}

	// ---- helpers ----

	private static float[] verts(JsonObject b)
	{
		JsonArray x = b.getAsJsonArray("vx"), y = b.getAsJsonArray("vy"), z = b.getAsJsonArray("vz");
		int n = x.size();
		float[] v = new float[n * 3];
		for (int i = 0; i < n; i++)
		{
			v[i * 3] = x.get(i).getAsFloat();
			v[i * 3 + 1] = y.get(i).getAsFloat();
			v[i * 3 + 2] = z.get(i).getAsFloat();
		}
		return v;
	}

	private static int[] ints(JsonElement e)
	{
		if (e == null || !e.isJsonArray())
		{
			return null;
		}
		JsonArray a = e.getAsJsonArray();
		int[] out = new int[a.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = a.get(i).getAsInt();
		}
		return out;
	}

	private static JsonArray floats(float[] v, int c, int n)
	{
		JsonArray a = new JsonArray();
		for (int i = 0; i < n; i++)
		{
			a.add(v[i * 3 + c]);
		}
		return a;
	}

	private static double maxDiff(float[] a, float[] b)
	{
		if (a.length != b.length)
		{
			return Double.MAX_VALUE;
		}
		double m = 0;
		for (int i = 0; i < a.length; i++)
		{
			m = Math.max(m, Math.abs(a[i] - b[i]));
		}
		return m;
	}

	private static double sumDiff(float[] a, float[] b, double stop)
	{
		if (a.length != b.length)
		{
			return Double.MAX_VALUE;
		}
		double s = 0;
		for (int i = 0; i < a.length && s < stop; i++)
		{
			s += Math.abs(a[i] - b[i]);
		}
		return s;
	}

	private static long hash2(long[] v)
	{
		long h = 1125899906842597L;
		for (long x : v)
		{
			h = 31 * h + x * 0x9E3779B97F4A7C15L;
		}
		return h;
	}

	static byte[] deflate(byte[] in)
	{
		Deflater d = new Deflater(6, true);
		d.setInput(in);
		d.finish();
		ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(16, in.length / 2));
		byte[] buf = new byte[8192];
		while (!d.finished())
		{
			out.write(buf, 0, d.deflate(buf));
		}
		d.end();
		return out.toByteArray();
	}

	static byte[] inflate(byte[] in)
	{
		Inflater i = new Inflater(true);
		i.setInput(in);
		ByteArrayOutputStream out = new ByteArrayOutputStream(in.length * 3);
		byte[] buf = new byte[8192];
		try
		{
			while (!i.finished())
			{
				int n = i.inflate(buf);
				if (n == 0 && (i.needsInput() || i.needsDictionary()))
				{
					break;
				}
				out.write(buf, 0, n);
			}
		}
		catch (DataFormatException e)
		{
			throw new IllegalArgumentException("damaged data", e);
		}
		finally
		{
			i.end();
		}
		return out.toByteArray();
	}

	/** Ids stored (for tests). */
	synchronized List<Integer> ids()
	{
		return new ArrayList<>(mods.keySet());
	}
}

package com.renderreplay;

import java.awt.event.KeyEvent;
import net.runelite.client.input.KeyListener;

/**
 * Playback transport keys: Left / Right = one tick back / forward, Space = pause / resume, only while a playback is running.
 * Only those three keys are consumed. The mouse, the mouse wheel and every other key always reach the game. This never
 * creates or injects any event.
 */
final class PlaybackKeys implements KeyListener
{
	private volatile boolean active;
	/** Holding Left rewinds at most one tick per this many ms (auto-repeat fires ~30 times a second). */
	static final long LEFT_REPEAT_MS = 200;

	/** dir: -1 back, +1 forward. repeat: this is a key auto-repeat, not a fresh press. */
	interface StepAction
	{
		void step(int dir, boolean repeat);
	}

	private final Runnable onToggle;
	private final StepAction onStep;
	private boolean spaceDown;  // ignore key auto-repeat for Space
	private boolean leftDown;
	private boolean rightDown;
	long lastLeftMs;

	PlaybackKeys(Runnable onToggle, StepAction onStep)
	{
		this.onToggle = onToggle;
		this.onStep = onStep;
	}

	void setActive(boolean active)
	{
		this.active = active;
	}

	private static boolean transportKey(int code)
	{
		return code == KeyEvent.VK_LEFT || code == KeyEvent.VK_RIGHT || code == KeyEvent.VK_SPACE;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		if (active && e.getKeyChar() == ' ')
		{
			e.consume(); // the typed character of Space
		}
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (!active || !transportKey(e.getKeyCode()))
		{
			return;
		}
		e.consume();
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_LEFT:
			{
				boolean repeat = leftDown;
				leftDown = true;
				long now = System.currentTimeMillis();
				if (!repeat || now - lastLeftMs >= LEFT_REPEAT_MS)
				{
					lastLeftMs = now;
					onStep.step(-1, repeat);
				}
				break;
			}
			case KeyEvent.VK_RIGHT:
			{
				boolean repeat = rightDown;
				rightDown = true;
				onStep.step(1, repeat); // holding Right keeps the animated step going (the recorder rate-limits repeats)
				break;
			}
			default: // VK_SPACE
				if (!spaceDown)
				{
					spaceDown = true;
					onToggle.run();
				}
				break;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_SPACE:
				spaceDown = false;
				break;
			case KeyEvent.VK_LEFT:
				leftDown = false;
				break;
			case KeyEvent.VK_RIGHT:
				rightDown = false;
				break;
			default:
				break;
		}
		if (active && transportKey(e.getKeyCode()))
		{
			e.consume();
		}
	}
}

package com.renderreplay;

/**
 * The recording qualities the panel's slider offers: the Pareto-optimal pairings of a world option and a 2D-layer
 * option, from exact to smallest, with what each measured on a sample recording (bytes per frame in the long run, and
 * PSNR against exact playback, 0 meaning exact).
 */
final class Presets
{
	static final class Preset
	{
		final String name;
		final double vq, poseTol;          // vertex rounding (1/vq units, 0 exact), pose reuse within poseTol units
		final int every;                   // world calls kept every n-th frame
		final boolean interp, freeze;      // smooth between kept frames; keep each object's first pose
		final int uiEvery, uiKey, quant, thresh, mmThresh, mmEvery;
		final boolean half, mmFree;
		final int labBytesPerFrame;
		final double labPsnr;

		Preset(String name, double vq, double poseTol, int every, boolean interp, boolean freeze, int uiEvery, int uiKey, int quant,
			int thresh, int mmThresh, int mmEvery, boolean half, boolean mmFree, int labBytesPerFrame, double labPsnr)
		{
			this.name = name;
			this.vq = vq;
			this.poseTol = poseTol;
			this.every = every;
			this.interp = interp;
			this.freeze = freeze;
			this.uiEvery = uiEvery;
			this.uiKey = uiKey;
			this.quant = quant;
			this.thresh = thresh;
			this.mmThresh = mmThresh;
			this.mmEvery = mmEvery;
			this.half = half;
			this.mmFree = mmFree;
			this.labBytesPerFrame = labBytesPerFrame;
			this.labPsnr = labPsnr;
		}

		UiCodec.Opts uiOpts()
		{
			UiCodec.Opts o = new UiCodec.Opts();
			o.every = uiEvery;
			o.key = uiKey;
			o.anchorEvery = Math.max(1, anchorFrames / uiKey);
			o.quant = quant;
			o.thresh = thresh;
			o.mmThresh = mmThresh;
			o.mmEvery = mmEvery;
			o.half = half;
			o.mmFree = mmFree;
			return o;
		}

		boolean exact()
		{
			return labPsnr == 0;
		}
	}

