package com.renderreplay;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Codec for the 2D layer (interface and overlays), frame by frame, with an encoder and a decoder that keep the same
 * state. A frame is predicted from the one before; the minimap is predicted by turning it by the recorded change in
 * camera yaw (plus a small shift); sprites drawn before (labels, XP drops, hitsplats) are stored as a reference and a
 * position; what is left is stored as runs of changed pixels, packed QOI-style and deflated.
 * Every key-th frame is a checkpoint, stored as changes since the previous checkpoint, and every anchor-th checkpoint
 * stands alone, so playback can start at any anchor. Options make it lossy: fewer colour bits, small changes ignored,
 * only every n-th frame stored (the minimap still turns in between), half resolution.
 */
final class UiCodec
{
	private static final int MAX_GAP = 2, MAX_SPRITES = 4096;

	static final class Opts
	{
		int every = 1, key = 60, anchorEvery = 180, quant = 8, thresh = 0, mmThresh = 0, mmEvery = 0;
		boolean ckDelta = true, mc = true, sprites = true, half, mmFree;
	}

	private UiCodec()
	{
	}

	/** Whether frame f is a checkpoint, and whether that checkpoint stands alone. */
	static boolean isKey(Opts o, int f)
	{
		return f % o.key == 0;
	}

	static boolean isAnchor(Opts o, int f)
	{
		return f % o.key == 0 && (f / o.key) % o.anchorEvery == 0;
	}

	// ---- shared state and steps ----

	private abstract static class State
	{
		final Opts o;
		int w, h, n;              // working size (half of the layer at half resolution)
		int fullW, fullH;
		int[] recon, cur, pred, painted, ck, mmBase;
		int lastF = -1, ckF = -1, mmBaseF = -1;
		float lastYaw, ckYaw, mmBaseYaw;
		int mmSign = 1;
		int[] mm;                 // cx, cy, r in working pixels
		int[] pts;                // minimap pixel indexes
		int[] ptsSearch;          // every third of them: enough to choose the minimap's turn and shift, at a third of the cost
		byte[] inMm;
		byte[] seen;
		int[] stack;
		final List<int[]> sprites = new ArrayList<>(); // id -> {w, h, data...}
		final Map<String, Integer> spriteIds = new HashMap<>();

		State(Opts o)
		{
			this.o = o;
		}

		void size(int fullN, int fullWidth)
		{
			fullW = fullWidth;
			fullH = fullN / fullWidth;
			w = o.half ? fullW >> 1 : fullW;
			h = o.half ? fullH >> 1 : fullH;
			n = w * h;
			recon = cur = pred = painted = ck = mmBase = null;
			mm = null;
			lastF = ckF = mmBaseF = -1;
		}

		void setMinimap(int[] m)
		{
			if (m == null)
			{
				mm = null;
				pts = null;
				ptsSearch = null;
				inMm = null;
				return;
			}
			mm = m;
			List<Integer> a = new ArrayList<>();
			for (int y = Math.max(0, m[1] - m[2]); y <= Math.min(h - 1, m[1] + m[2]); y++)
			{
				for (int x = Math.max(0, m[0] - m[2]); x <= Math.min(w - 1, m[0] + m[2]); x++)
				{
					if ((x - m[0]) * (x - m[0]) + (y - m[1]) * (y - m[1]) <= (m[2] - 1) * (m[2] - 1))
					{
						a.add(y * w + x);
					}
				}
			}
			pts = new int[a.size()];
			ptsSearch = new int[(a.size() + 2) / 3];
			for (int i = 0; i < ptsSearch.length; i++)
			{
				ptsSearch[i] = a.get(i * 3);
			}
			inMm = new byte[n];
			for (int i = 0; i < pts.length; i++)
			{
				pts[i] = a.get(i);
				inMm[pts[i]] = 1;
			}
		}

		int[] buf(int[] b)
		{
			return b != null && b.length == n ? b : new int[n];
		}
	}

	private static void predictMinimap(int[] src, int w, int[] mm, double ang, int sx, int sy, int[] out, int[] pts)
	{
		double c = Math.cos(ang), s = Math.sin(ang);
		int r2 = (mm[2] - 1) * (mm[2] - 1);
		for (int k = 0; k < pts.length; k++)
		{
			int i = pts[k], x = i % w - mm[0], y = i / w - mm[1];
			int u = (int) Math.round(mm[0] + x * c - y * s + sx), v = (int) Math.round(mm[1] + x * s + y * c + sy);
			int du = u - mm[0], dv = v - mm[1];
			out[i] = du * du + dv * dv <= r2 ? src[v * w + u] : src[i];
		}
	}

	private static int misses(int[] cand, int[] cur, int[] pts)
	{
		int m = 0;
		for (int i : pts)
		{
			if (cand[i] != cur[i])
			{
				m++;
			}
		}
		return m;
	}

	/** Runs of cur differing from base (base null: from zero), {start, count} pairs. */
	private static int[] runs(int[] base, int[] cur, int n)
	{
		int[] out = new int[64];
		int k = 0;
		for (int i = 0; i < n; )
		{
			if (cur[i] == (base == null ? 0 : base[i]))
			{
				i++;
				continue;
			}
			int end = i + 1;
			for (int j = end; j < n && j - end <= MAX_GAP; j++)
			{
				if (cur[j] != (base == null ? 0 : base[j]))
				{
					end = j + 1;
				}
			}
			if (k + 2 > out.length)
			{
				out = Arrays.copyOf(out, out.length * 2);
			}
			out[k++] = i;
			out[k++] = end - i;
			i = end;
		}
		return Arrays.copyOf(out, k);
	}

	/** Objects over transparent pixels that changed: connected non-transparent regions outside the minimap. */
	private static List<int[]> changedObjects(State s, int[] cur, int[] ref)
	{
		List<int[]> out = new ArrayList<>();
		if (s.seen == null || s.seen.length != s.n)
		{
			s.seen = new byte[s.n];
			s.stack = new int[s.n];
		}
		byte[] seen = s.seen;
		Arrays.fill(seen, (byte) 0);
		int w = s.w, n = s.n;
		List<Integer> pix = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			if (seen[i] != 0 || (s.inMm != null && s.inMm[i] != 0) || cur[i] == 0 || cur[i] == ref[i])
			{
				continue;
			}
			int sp = 0, cnt = 0, x0 = Integer.MAX_VALUE, y0 = Integer.MAX_VALUE, x1 = -1, y1 = -1;
			boolean big = false;
			pix.clear();
			s.stack[sp++] = i;
			seen[i] = 1;
			while (sp > 0)
			{
				int j = s.stack[--sp];
				pix.add(j);
				cnt++;
				int x = j % w, y = j / w;
				x0 = Math.min(x0, x);
				x1 = Math.max(x1, x);
				y0 = Math.min(y0, y);
				y1 = Math.max(y1, y);
				if (cnt > 4096)
				{
					big = true;
				}
				int[] nb = {x > 0 ? j - 1 : -1, x < w - 1 ? j + 1 : -1, j - w, j + w};
				for (int k : nb)
				{
					if (k >= 0 && k < n && seen[k] == 0 && (s.inMm == null || s.inMm[k] == 0) && cur[k] != 0)
					{
						seen[k] = 1;
						if (!big)
						{
							s.stack[sp++] = k;
						}
					}
				}
			}
			if (big)
			{
				continue;
			}
			int bw = x1 - x0 + 1, bh = y1 - y0 + 1;
			int[] ob = new int[4 + bw * bh];
			ob[0] = x0;
			ob[1] = y0;
			ob[2] = bw;
			ob[3] = bh;
			for (int j : pix)
			{
				ob[4 + (j / w - y0) * bw + (j % w - x0)] = cur[j];
			}
			out.add(ob);
		}
		return out;
	}

	private static String spriteKey(int[] ob)
	{
		return ob[2] + "x" + ob[3] + ":" + Arrays.hashCode(Arrays.copyOfRange(ob, 4, ob.length)) + ":" + ob.length;
	}

	private static void paint(int[] dst, int w, int[] sprite, int x, int y)
	{
		int bw = sprite[0], bh = sprite[1];
		for (int yy = 0; yy < bh; yy++)
		{
			for (int xx = 0; xx < bw; xx++)
			{
				int v = sprite[2 + yy * bw + xx];
				if (v != 0)
				{
					dst[(y + yy) * w + x + xx] = v;
				}
			}
		}
	}

	/** After a frame is known: sprites seen for the first time join the cache (same order on both sides). */
	private static void learnSprites(State s, int[] cur, int[] ref)
	{
		for (int[] ob : changedObjects(s, cur, ref))
		{
			String k = spriteKey(ob);
			if (!s.spriteIds.containsKey(k) && s.sprites.size() < MAX_SPRITES)
			{
				int[] sp = new int[2 + ob.length - 4];
				sp[0] = ob[2];
				sp[1] = ob[3];
				System.arraycopy(ob, 4, sp, 2, ob.length - 4);
				s.spriteIds.put(k, s.sprites.size());
				s.sprites.add(sp);
			}
		}
	}

	/** End of a frame on either side: what playback shows becomes the reference, checkpoints and minimap kept. */
	private static void finish(State s, int f, float yaw, boolean key, boolean store, int[] cur)
	{
		int[] old = s.recon;
		s.recon = cur;
		s.cur = old != null && old.length == s.n && old != s.ck && old != s.mmBase ? old : null;
		s.lastF = f;
		s.lastYaw = yaw;
		if (key)
		{
			s.ck = s.ck != null && s.ck.length == s.n ? s.ck : new int[s.n];
			System.arraycopy(cur, 0, s.ck, 0, s.n);
			s.ckF = f;
			s.ckYaw = yaw;
		}
		if (store && s.mm != null)
		{
			s.mmBase = s.mmBase != null && s.mmBase.length == s.n ? s.mmBase : new int[s.n];
			for (int i : s.pts)
			{
				s.mmBase[i] = cur[i];
			}
			s.mmBaseF = f;
			s.mmBaseYaw = yaw;
		}
	}

	private static int[] down(int[] full, int fw, int w, int h, int[] out)
	{
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				int i = 2 * y * fw + 2 * x;
				int[] p = {full[i], full[i + 1], full[i + fw], full[i + fw + 1]};
				int a = 0, r = 0, g = 0, b = 0;
				for (int v : p)
				{
					a += v >>> 24;
					r += v >>> 16 & 255;
					g += v >>> 8 & 255;
					b += v & 255;
				}
				out[y * w + x] = ((a + 2) >> 2) << 24 | ((r + 2) >> 2) << 16 | ((g + 2) >> 2) << 8 | ((b + 2) >> 2);
			}
		}
		return out;
	}

	private static void up(int[] small, int w, int h, int[] full, int fw, int fh)
	{
		for (int y = 0; y < fh; y++)
		{
			int sy = Math.min(h - 1, y >> 1);
			for (int x = 0; x < fw; x++)
			{
				full[y * fw + x] = small[sy * w + Math.min(w - 1, x >> 1)];
			}
		}
	}

	private static int[] scaleMm(Opts o, int[] mm)
	{
		return mm == null ? null : o.half ? new int[]{mm[0] >> 1, mm[1] >> 1, mm[2] >> 1} : mm;
	}

	// ---- encoder ----

	static final class Encoder extends State
	{
		private int[] lastMmSent;
		private int[] small, cand;
		/** After encode: whether that frame was a checkpoint, and whether it stands alone (no reference). */
		boolean wasKey, wasStandalone;

		Encoder(Opts o)
		{
			super(o);
		}

		/** What playback shows after the last frame encoded, full size. */
		int[] shown()
		{
			if (!o.half)
			{
				return recon;
			}
			int[] out = new int[fullW * fullH];
			up(recon, w, h, out, fullW, fullH);
			return out;
		}

		/**
		 * Codes one frame of the layer (full size, ARGB) as frame number f of the recording, with the camera yaw and
		 * the minimap {cx, cy, r} in layer pixels (or null). Returns the frame's bytes (empty when nothing is stored).
		 */
		byte[] encode(int[] full, int fullWidth, int f, float yaw, int[] mmFull)
		{
			// the client's pixel array can be longer than width x height (by one pixel): only whole rows are the layer
			int fullN = full.length - full.length % fullWidth;
			if (recon == null || fullW != fullWidth || fullW * fullH != fullN)
			{
				size(fullN, fullWidth);
				lastMmSent = null;
			}
			int[] src = full;
			if (o.half)
			{
				small = buf(small);
				src = down(full, fullW, w, h, small);
			}
			int[] mmW = scaleMm(o, mmFull);
			boolean key = isKey(o, f) || recon == null;
			boolean anchor = isAnchor(o, f) || recon == null;
			boolean store = key || f % o.every == 0;
			if (key)
			{
				// a checkpoint starts afresh: sprites, the turn direction and the minimap's place are sent again
				sprites.clear();
				spriteIds.clear();
				mmSign = 1;
			}
			boolean mmChanged = !Arrays.equals(mmW, lastMmSent) || key;
			if (mmChanged)
			{
				setMinimap(mmW);
			}
			int[] ref = key ? (o.ckDelta && !anchor && ck != null ? ck : null) : recon;
			int refF = key ? ckF : lastF;
			float refYaw = key ? ckYaw : lastYaw;
			pred = buf(pred);
			if (ref != null)
			{
				System.arraycopy(ref, 0, pred, 0, n);
			}
			else
			{
				Arrays.fill(pred, 0);
			}
			Bytes.Out out = new Bytes.Out(256);
			// 1 stored, 2 minimap place follows, 4 minimap motion follows, 8 no minimap, 16 stands alone, 32 checkpoint
			int flags = (store ? 1 : 0) | (mmChanged ? (mm != null ? 2 : 8) : 0) | (ref == null ? 16 : 0) | (key ? 32 : 0);
			wasKey = key;
			wasStandalone = ref == null;
			int motionMode = -1, sx = 0, sy = 0;
			if (o.mc && mm != null && ref != null)
			{
				boolean useBase = !key && mmBase != null;
				int[] base = useBase ? mmBase : ref;
				float dyaw = yaw - (useBase ? mmBaseYaw : refYaw);
				if (o.mmFree && !store)
				{
					predictMinimap(base, w, mm, mmSign * (double) dyaw, 0, 0, pred, pts);
				}
				else
				{
					// the turn direction and shift that the fewest minimap pixels disagree with
					int bestMode = 2, bestMiss = Integer.MAX_VALUE;
					cand = buf(cand);
					int[] modes = Math.abs(dyaw) > 1e-6 ? new int[]{0, 1, 2} : new int[]{2};
					for (int md : modes)
					{
						predictMinimap(base, w, mm, angle(md, dyaw), 0, 0, cand, ptsSearch);
						int m = misses(cand, src, ptsSearch);
						if (m < bestMiss)
						{
							bestMiss = m;
							bestMode = md;
						}
					}
					double ang = angle(bestMode, dyaw);
					for (int r = 1; r <= 4 && bestMiss > 0; r++)
					{
						boolean improved = false;
						for (int dy = -r; dy <= r; dy++)
						{
							for (int dx = -r; dx <= r; dx++)
							{
								if (Math.max(Math.abs(dx), Math.abs(dy)) != r)
								{
									continue;
								}
								predictMinimap(base, w, mm, ang, dx, dy, cand, ptsSearch);
								int m = misses(cand, src, ptsSearch);
								if (m < bestMiss)
								{
									bestMiss = m;
									sx = dx;
									sy = dy;
									improved = true;
								}
							}
						}
						if (!improved && r >= 2)
						{
							break;
						}
					}
					motionMode = bestMode;
					predictMinimap(base, w, mm, ang, sx, sy, pred, pts);
					if (bestMode != 2 && Math.abs(dyaw) > 1e-6)
					{
						mmSign = bestMode == 0 ? 1 : -1;
					}
					flags |= 4;
				}
			}
			// what this frame stores: the source, except where options say the prediction is close enough
			cur = buf(cur);
			int keep = o.quant >= 8 ? 0xFFFFFFFF : 0xFF000000 | ((0xFF << (8 - o.quant)) & 0xFF) * 0x010101;
			boolean mmSkip = !key && o.mmEvery > 1 && f % o.mmEvery != 0;
			for (int i = 0; i < n; i++)
			{
				int v = src[i];
				if (o.quant < 8)
				{
					int m = v & keep;
					v = m | ((m & 0x00FFFFFF) >>> o.quant & ~keep & 0x00FFFFFF);
				}
				int p = pred[i];
				if (ref != null && v != p)
				{
					boolean inm = inMm != null && inMm[i] != 0;
					if (!store || (mmSkip && inm) || (o.mmThresh > 0 && inm && close(v, p, o.mmThresh)) || (o.thresh > 0 && !inm && close(v, p, o.thresh)))
					{
						v = p;
					}
				}
				cur[i] = v;
			}
			if (!store && (flags & (2 | 4 | 8)) == 0)
			{
				finish(this, f, yaw, key, false, cur);
				return new byte[0];
			}
			out.u8(flags);
			if ((flags & 2) != 0)
			{
				out.varint(mm[0]);
				out.varint(mm[1]);
				out.varint(mm[2]);
			}
			if ((flags & (2 | 8)) != 0)
			{
				lastMmSent = mmW;
			}
			if ((flags & 4) != 0)
			{
				out.u8(motionMode);
				out.zz(sx);
				out.zz(sy);
			}
			if (store)
			{
				int[] base = ref == null ? null : pred;
				if (o.sprites && ref != null)
				{
					painted = buf(painted);
					System.arraycopy(pred, 0, painted, 0, n);
					Bytes.Out sw = new Bytes.Out(32);
					int hits = 0;
					for (int[] ob : changedObjects(this, cur, pred))
					{
						Integer id = spriteIds.get(spriteKey(ob));
						if (id != null)
						{
							hits++;
							sw.varint(id);
							sw.varint(ob[0]);
							sw.varint(ob[1]);
							paint(painted, w, sprites.get(id), ob[0], ob[1]);
						}
					}
					out.varint(hits);
					out.bytes(sw.b, 0, sw.n);
					base = painted;
				}
				int[] rs = runs(base, cur, n);
				out.varint(rs.length / 2);
				int last = 0, px = 0;
				for (int k = 0; k < rs.length; k += 2)
				{
					out.varint(rs[k] - last);
					out.varint(rs[k + 1]);
					last = rs[k] + rs[k + 1];
					px += rs[k + 1];
				}
				int[] all = new int[px];
				int q = 0;
				for (int k = 0; k < rs.length; k += 2)
				{
					System.arraycopy(cur, rs[k], all, q, rs[k + 1]);
					q += rs[k + 1];
				}
				out.bytes(Qoi.encode(all, px));
			}
			if (o.sprites && store && ref != null)
			{
				learnSprites(this, cur, pred);
			}
			else if (o.sprites && store)
			{
				learnSprites(this, cur, new int[n]);
			}
			finish(this, f, yaw, key, store, cur);
			byte[] payload = out.toArray();
			if (payload.length < 24)
			{
				byte[] r = new byte[payload.length + 1];
				r[0] = 1;
				System.arraycopy(payload, 0, r, 1, payload.length);
				return r;
			}
			byte[] z = ModelStore.deflate(payload);
			byte[] r = new byte[z.length + 1];
			r[0] = 2;
			System.arraycopy(z, 0, r, 1, z.length);
			return r;
		}
	}

	private static double angle(int mode, float dyaw)
	{
		return mode == 0 ? dyaw : mode == 1 ? -dyaw : 0;
	}

	private static boolean close(int a, int b, int t)
	{
		return (a >>> 24) == (b >>> 24) && Math.abs((a >>> 16 & 255) - (b >>> 16 & 255)) <= t
			&& Math.abs((a >>> 8 & 255) - (b >>> 8 & 255)) <= t && Math.abs((a & 255) - (b & 255)) <= t;
	}

	// ---- decoder ----

	static final class Decoder extends State
	{
		private int[] full;

		Decoder(Opts o)
		{
			super(o);
		}

		/** Forgets everything; the next frame decoded must be an anchor. */
		void reset()
		{
			recon = null;
			sprites.clear();
			spriteIds.clear();
		}

		/**
		 * Decodes frame f (frames must come in order from an anchor). fullN and fullWidth are the layer's size.
		 * Returns the full-size layer playback shows (reused between calls).
		 */
		int[] decode(byte[] rec, int f, float yaw, int fullN, int fullWidth)
		{
			fullN -= fullN % fullWidth;
			if (recon == null || fullW != fullWidth || fullW * fullH != fullN)
			{
				size(fullN, fullWidth);
			}
			Bytes.In r = null;
			int flags = 0;
			if (rec.length > 0)
			{
				byte[] payload = rec[0] == 2 ? ModelStore.inflate(Arrays.copyOfRange(rec, 1, rec.length)) : Arrays.copyOfRange(rec, 1, rec.length);
				r = new Bytes.In(payload);
				flags = r.u8();
			}
			else if (recon == null)
			{
				return null; // nothing to show yet
			}
			boolean key = (flags & 32) != 0, standalone = (flags & 16) != 0;
			if (key)
			{
				sprites.clear();
				spriteIds.clear();
				mmSign = 1;
			}
			int[] ref = standalone ? null : key ? ck : recon;
			if (ref == null && !standalone)
			{
				throw new IllegalStateException("2D layer frame " + f + " needs a reference");
			}
			float refYaw = key ? ckYaw : lastYaw;
			boolean store = (flags & 1) != 0;
			pred = buf(pred);
			if (ref != null)
			{
				System.arraycopy(ref, 0, pred, 0, n);
			}
			else
			{
				Arrays.fill(pred, 0);
			}
			if (r != null)
			{
				if ((flags & 2) != 0)
				{
					setMinimap(new int[]{r.varint32(), r.varint32(), r.varint32()});
				}
				else if ((flags & 8) != 0)
				{
					setMinimap(null);
				}
			}
			if (o.mc && mm != null && ref != null)
			{
				boolean useBase = !key && mmBase != null;
				int[] base = useBase ? mmBase : ref;
				float dyaw = yaw - (useBase ? mmBaseYaw : refYaw);
				if ((flags & 4) != 0)
				{
					int mode = r.u8();
					int sx = (int) r.zz(), sy = (int) r.zz();
					predictMinimap(base, w, mm, angle(mode, dyaw), sx, sy, pred, pts);
					if (mode != 2 && Math.abs(dyaw) > 1e-6)
					{
						mmSign = mode == 0 ? 1 : -1;
					}
				}
				else if (o.mmFree && !store)
				{
					predictMinimap(base, w, mm, mmSign * (double) dyaw, 0, 0, pred, pts);
				}
			}
			cur = buf(cur);
			if (standalone && !store)
			{
				throw new IllegalStateException("bad 2D layer frame " + f);
			}
			System.arraycopy(pred, 0, cur, 0, n);
			if (store)
			{
				int[] base = ref == null ? null : pred;
				if (o.sprites && ref != null)
				{
					painted = buf(painted);
					System.arraycopy(pred, 0, painted, 0, n);
					int hits = r.varint32();
					for (int k = 0; k < hits; k++)
					{
						int id = r.varint32(), x = r.varint32(), y = r.varint32();
						paint(painted, w, sprites.get(id), x, y);
					}
					base = painted;
				}
				if (base == null)
				{
					Arrays.fill(cur, 0);
				}
				else
				{
					System.arraycopy(base, 0, cur, 0, n);
				}
				int runs = r.varint32();
				int[] rs = new int[runs * 2];
				int last = 0, px = 0;
				for (int k = 0; k < runs; k++)
				{
					rs[2 * k] = last + r.varint32();
					rs[2 * k + 1] = r.varint32();
					last = rs[2 * k] + rs[2 * k + 1];
					px += rs[2 * k + 1];
				}
				int[] all = Qoi.decode(r.b, r.p, px);
				int q = 0;
				for (int k = 0; k < rs.length; k += 2)
				{
					if (rs[k] < 0 || rs[k] + rs[k + 1] > n)
					{
						throw new IllegalArgumentException("bad run");
					}
					System.arraycopy(all, q, cur, rs[k], rs[k + 1]);
					q += rs[k + 1];
				}
				if (o.sprites)
				{
					learnSprites(this, cur, ref != null ? pred : new int[n]);
				}
			}
			finish(this, f, yaw, key, store, cur);
			if (!o.half)
			{
				return recon;
			}
			full = full != null && full.length == fullN ? full : new int[fullN];
			up(recon, w, h, full, fullW, fullH);
			return full;
		}
	}

	// ---- QOI-style pixel packing ----

	static final class Qoi
	{
		private Qoi()
		{
		}

		private static int hash(int p)
		{
			return ((p >>> 16 & 255) * 3 + (p >>> 8 & 255) * 5 + (p & 255) * 7 + (p >>> 24) * 11) & 63;
		}

		static byte[] encode(int[] px, int n)
		{
			Bytes.Out out = new Bytes.Out(n * 2 + 8);
			int prev = 0xFF000000, run = 0;
			int[] idx = new int[64];
			for (int i = 0; i < n; i++)
			{
				int p = px[i];
				if (p == prev)
				{
					run++;
					if (run == 62 || i == n - 1)
					{
						out.u8(0xC0 | (run - 1));
						run = 0;
					}
					continue;
				}
				if (run > 0)
				{
					out.u8(0xC0 | (run - 1));
					run = 0;
				}
				int h = hash(p);
				if (idx[h] == p)
				{
					out.u8(h);
				}
				else
				{
					idx[h] = p;
					if ((p >>> 24) == (prev >>> 24))
					{
						int dr = (byte) ((p >>> 16 & 255) - (prev >>> 16 & 255)), dg = (byte) ((p >>> 8 & 255) - (prev >>> 8 & 255)), db = (byte) ((p & 255) - (prev & 255));
						int drg = dr - dg, dbg = db - dg;
						if (dr >= -2 && dr <= 1 && dg >= -2 && dg <= 1 && db >= -2 && db <= 1)
						{
							out.u8(0x40 | (dr + 2) << 4 | (dg + 2) << 2 | (db + 2));
						}
						else if (dg >= -32 && dg <= 31 && drg >= -8 && drg <= 7 && dbg >= -8 && dbg <= 7)
						{
							out.u8(0x80 | (dg + 32));
							out.u8((drg + 8) << 4 | (dbg + 8));
						}
						else
						{
							out.u8(0xFE);
							out.u8(p >>> 16 & 255);
							out.u8(p >>> 8 & 255);
							out.u8(p & 255);
						}
					}
					else
					{
						out.u8(0xFF);
						out.u8(p >>> 16 & 255);
						out.u8(p >>> 8 & 255);
						out.u8(p & 255);
						out.u8(p >>> 24);
					}
				}
				prev = p;
			}
			if (run > 0)
			{
				out.u8(0xC0 | (run - 1));
			}
			return out.toArray();
		}

		static int[] decode(byte[] b, int off, int n)
		{
			int[] px = new int[n], idx = new int[64];
			int p = off, prev = 0xFF000000, i = 0;
			while (i < n)
			{
				int op = b[p++] & 0xFF, v;
				if (op == 0xFE)
				{
					v = (prev & 0xFF000000) | (b[p] & 255) << 16 | (b[p + 1] & 255) << 8 | (b[p + 2] & 255);
					p += 3;
				}
				else if (op == 0xFF)
				{
					v = (b[p + 3] & 255) << 24 | (b[p] & 255) << 16 | (b[p + 1] & 255) << 8 | (b[p + 2] & 255);
					p += 4;
				}
				else if ((op & 0xC0) == 0x00)
				{
					v = idx[op];
					prev = v;
					px[i++] = v;
					continue;
				}
				else if ((op & 0xC0) == 0x40)
				{
					int r = ((prev >>> 16) + ((op >> 4 & 3) - 2)) & 255, g = ((prev >>> 8) + ((op >> 2 & 3) - 2)) & 255, bl = (prev + ((op & 3) - 2)) & 255;
					v = (prev & 0xFF000000) | r << 16 | g << 8 | bl;
				}
				else if ((op & 0xC0) == 0x80)
				{
					int dg = (op & 63) - 32, x = b[p++] & 255, dr = dg + (x >> 4) - 8, db = dg + (x & 15) - 8;
					v = (prev & 0xFF000000) | (((prev >>> 16) + dr) & 255) << 16 | (((prev >>> 8) + dg) & 255) << 8 | ((prev + db) & 255);
				}
				else
				{
					int run = (op & 63) + 1;
					for (int k = 0; k < run && i < n; k++)
					{
						px[i++] = prev;
					}
					continue;
				}
				idx[hash(v)] = v;
				prev = v;
				px[i++] = v;
			}
			return px;
		}
	}
}

package com.renderreplay;

import java.io.ByteArrayOutputStream;
import java.nio.ByteBuffer;
import java.nio.IntBuffer;
import java.util.Arrays;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;

/**
 * Delta codec for the client's 2D layer (interface + plugin overlays), one snapshot per frame.
 * A frame is stored as the runs of pixels that changed since the previous frame, deflated:
 * {len, (start, count, argb * count)*}.
 */
final class UiFrames
{
	// A run continues over this many unchanged pixels: storing them costs less than the header of a new run.
	private static final int MAX_GAP = 2;

	private UiFrames()
	{
	}

	/** Encodes cur relative to prev (prev == null or a different length means "against all zeros"). */
	static byte[] encode(int[] prev, int[] cur)
	{
		boolean same = prev != null && prev.length == cur.length;
		int len = cur.length;
		int[] runs = new int[1024];
		int n = 0;
		for (int i = 0; i < len; )
		{
			if (cur[i] == (same ? prev[i] : 0))
			{
				i++;
				continue;
			}
			int end = i + 1; // one past the last changed pixel of this run
			for (int j = end; j < len && j - end <= MAX_GAP; j++)
			{
				if (cur[j] != (same ? prev[j] : 0))
				{
					end = j + 1;
				}
			}
			int count = end - i;
			if (n + 2 + count > runs.length)
			{
				runs = Arrays.copyOf(runs, Math.max(runs.length * 2, n + 2 + count));
			}
			runs[n++] = i;
			runs[n++] = count;
			System.arraycopy(cur, i, runs, n, count);
			n += count;
			i = end;
		}
		ByteBuffer b = ByteBuffer.allocate(4 + n * 4);
		b.putInt(len);
		b.asIntBuffer().put(runs, 0, n);
		Deflater d = new Deflater(Deflater.BEST_SPEED);
		d.setInput(b.array());
		d.finish();
		ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(64, n));
		byte[] buf = new byte[8192];
		while (!d.finished())
		{
			out.write(buf, 0, d.deflate(buf));
		}
		d.end();
		return out.toByteArray();
	}

	/** Length of the full buffer an encoded frame belongs to. */
	static int length(byte[] enc)
	{
		return ByteBuffer.wrap(inflate(enc, 4)).getInt();
	}

	/** Applies an encoded delta on top of target, which must already hold the previous frame. */
	static void apply(byte[] enc, int[] target)
	{
		IntBuffer b = ByteBuffer.wrap(inflate(enc, -1)).asIntBuffer();
		int len = b.get();
		if (len != target.length)
		{
			throw new IllegalArgumentException("buffer length " + target.length + " != frame length " + len);
		}
		while (b.remaining() >= 2)
		{
			int start = b.get(), count = b.get();
			if (start < 0 || count < 0 || count > len - start || count > b.remaining())
			{
				throw new IllegalArgumentException("bad run " + start + "+" + count);
			}
			b.get(target, start, count);
		}
	}

	/**
	 * Applies one recorded frame to target. A keyframe is encoded against an all-zero screen, so it must start from
	 * a cleared buffer: otherwise pixels that are transparent in the keyframe but non-zero in target (e.g. an overlay
	 * that has since moved) would linger as ghosts. Delta frames are applied on top of the previous frame as-is.
	 */
	static void applyFrame(byte[] enc, int[] target, boolean keyframe)
	{
		if (keyframe)
		{
			Arrays.fill(target, 0);
		}
		apply(enc, target);
	}

	private static byte[] inflate(byte[] enc, int max)
	{
		Inflater in = new Inflater();
		in.setInput(enc);
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] buf = new byte[8192];
		try
		{
			while (!in.finished() && (max < 0 || out.size() < max))
			{
				int r = in.inflate(buf);
				if (r == 0 && (in.needsInput() || in.needsDictionary()))
				{
					break;
				}
				out.write(buf, 0, r);
			}
		}
		catch (DataFormatException e)
		{
			throw new IllegalArgumentException(e);
		}
		finally
		{
			in.end();
		}
		return out.toByteArray();
	}
}

package com.renderreplay;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.TileObject;

/**
 * Lossless codec for a frame's world calls, as the rows the recorder writes ([method, args...], JSON). Each frame is
 * coded against the one before: unchanged calls and calls that came out as predicted cost a run count; the rest store
 * only the fields that missed. Fields are predicted from the same call one frame earlier: by their previous value, by
 * continuing their last step, or, for a model, by the model that followed it last time. Projections are stored once per
 * frame. Encoder and decoder keep identical state; both start over with reset().
 */
final class WorldCodec
{
	static final byte INT = 0, F32 = 1, F64 = 2, STR = 3, BOOL = 4, PROJ = 5, MODEL = 6;
	private static final Map<String, String> SIGS = new HashMap<>();

	static
	{
		for (Call c : Call.values())
		{
			StringBuilder s = new StringBuilder();
			for (Class<?> t : c.types)
			{
				s.append(t == Projection.class ? 'P' : t == Scene.class ? 'S' : t == Renderable.class ? 'R' : t == TileObject.class ? 'T'
					: t == GameObject.class ? 'G' : t == Model.class ? 'M' : t == SceneTilePaint.class ? 'Q' : t == SceneTileModel.class ? 'Z'
					: t == Set.class ? 'X' : t == int.class ? 'i' : t == long.class ? 'l' : t == float.class ? 'f' : t == double.class ? 'd' : '?');
			}
			SIGS.put(c.methodName + "/" + c.types.length, s.toString());
		}
	}

	private WorldCodec()
	{
	}

	static String sigOf(JsonArray row)
	{
		return SIGS.get(row.get(0).getAsString() + "/" + (row.size() - 1));
	}

	// ---- leaves ----

	private static final class Entry
	{
		JsonArray tpl;      // a row of this shape, whose values are replaced by the leaves
		Object[] leaves;    // Long, Double or String
		byte[] types;
		int shape;
		Object[] pl;        // the leaves one frame earlier, or null
		JsonArray row;      // encoder only
		String shapeKey;    // encoder only
		String id;          // encoder only
	}

	interface ProjRef
	{
		long ref(JsonObject proj);
	}

	// A nested number is an integer leaf when it is one: by its type when the recorder made it, by its value when it was
	// read from a file (then its type is unknown).
	private static boolean integral(JsonPrimitive p)
	{
		Number n = p.getAsNumber();
		if (n instanceof Integer || n instanceof Long || n instanceof Short || n instanceof Byte)
		{
			return true;
		}
		if (n instanceof Float || n instanceof Double)
		{
			return false;
		}
		double d = n.doubleValue();
		return d == Math.rint(d) && Math.abs(d) < 1e15;
	}

	private static void flattenValue(JsonElement v, List<Object> leaves, List<Byte> types)
	{
		if (v == null || v.isJsonNull())
		{
			return;
		}
		if (v.isJsonPrimitive())
		{
			JsonPrimitive p = v.getAsJsonPrimitive();
			if (p.isBoolean())
			{
				leaves.add(p.getAsBoolean() ? 1L : 0L);
				types.add(BOOL);
			}
			else if (p.isString())
			{
				leaves.add(p.getAsString());
				types.add(STR);
			}
			else if (integral(p))
			{
				leaves.add(p.getAsLong());
				types.add(INT);
			}
			else
			{
				leaves.add(p.getAsDouble());
				types.add(F64);
			}
		}
		else if (v.isJsonArray())
		{
			for (JsonElement e : v.getAsJsonArray())
			{
				flattenValue(e, leaves, types);
			}
		}
		else
		{
			for (Map.Entry<String, JsonElement> e : v.getAsJsonObject().entrySet())
			{
				flattenValue(e.getValue(), leaves, types);
			}
		}
	}

	private static void shapeOfValue(JsonElement v, StringBuilder out)
	{
		if (v == null || v.isJsonNull())
		{
			out.append('n');
		}
		else if (v.isJsonPrimitive())
		{
			JsonPrimitive p = v.getAsJsonPrimitive();
			out.append(p.isBoolean() ? 'B' : p.isString() ? 'S' : integral(p) ? 'I' : 'D');
		}
		else if (v.isJsonArray())
		{
			out.append('[');
			for (JsonElement e : v.getAsJsonArray())
			{
				shapeOfValue(e, out);
			}
			out.append(']');
		}
		else
		{
			out.append('{');
			for (Map.Entry<String, JsonElement> e : v.getAsJsonObject().entrySet())
			{
				out.append(e.getKey()).append(':');
				shapeOfValue(e.getValue(), out);
			}
			out.append('}');
		}
	}

	static String rowShape(JsonArray row, String sig)
	{
		StringBuilder out = new StringBuilder(64);
		out.append(row.get(0).getAsString()).append('/').append(row.size() - 1).append('|');
		for (int i = 0; i < sig.length(); i++)
		{
			char t = sig.charAt(i);
			JsonElement a = row.get(i + 1);
			boolean nul = a == null || a.isJsonNull();
			if (t == 'P')
			{
				out.append(nul ? "Pn" : "P");
			}
			else if (t == 'f' || t == 'd' || t == 'i' || t == 'l')
			{
				out.append(nul ? 'n' : t == 'f' ? 'F' : t == 'd' ? 'D' : 'I');
			}
			else
			{
				shapeOfValue(a, out);
			}
			out.append('|');
		}
		return out.toString();
	}

	private static boolean isModelRef(JsonElement a)
	{
		if (!a.isJsonObject())
		{
			return false;
		}
		JsonObject o = a.getAsJsonObject();
		return o.size() == 1 && o.has("model") && o.get("model").isJsonPrimitive() && o.get("model").getAsJsonPrimitive().isNumber();
	}

	private static void flatten(JsonArray row, String sig, ProjRef projRef, Entry e)
	{
		List<Object> leaves = new ArrayList<>(16);
		List<Byte> types = new ArrayList<>(16);
		for (int i = 0; i < sig.length(); i++)
		{
			char t = sig.charAt(i);
			JsonElement a = row.get(i + 1);
			if (a == null || a.isJsonNull())
			{
				continue;
			}
			if (t == 'P')
			{
				leaves.add(projRef.ref(a.getAsJsonObject()));
				types.add(PROJ);
			}
			else if (t == 'f')
			{
				leaves.add((double) a.getAsFloat());
				types.add(F32);
			}
			else if (t == 'd')
			{
				leaves.add(a.getAsDouble());
				types.add(F64);
			}
			else if (t == 'i' || t == 'l')
			{
				leaves.add(a.getAsLong());
				types.add(INT);
			}
			else if (t == 'M' && isModelRef(a))
			{
				leaves.add(a.getAsJsonObject().get("model").getAsLong());
				types.add(MODEL);
			}
			else
			{
				flattenValue(a, leaves, types);
			}
		}
		e.leaves = leaves.toArray();
		e.types = new byte[types.size()];
		for (int i = 0; i < e.types.length; i++)
		{
			e.types[i] = types.get(i);
		}
	}

	interface ProjOf
	{
		JsonElement proj(long ref);
	}

	private static JsonElement leafValue(Object v, byte t)
	{
		if (t == BOOL)
		{
			return new JsonPrimitive(((Long) v) != 0);
		}
		if (t == STR)
		{
			return new JsonPrimitive((String) v);
		}
		if (t == F32)
		{
			return new JsonPrimitive((float) (double) (Double) v);
		}
		if (t == F64)
		{
			return new JsonPrimitive((Double) v);
		}
		return new JsonPrimitive((Long) v);
	}

	private static JsonElement unflattenValue(JsonElement tpl, Object[] leaves, byte[] types, int[] pos)
	{
		if (tpl == null || tpl.isJsonNull())
		{
			return JsonNull.INSTANCE;
		}
		if (tpl.isJsonPrimitive())
		{
			int i = pos[0]++;
			return leafValue(leaves[i], types[i]);
		}
		if (tpl.isJsonArray())
		{
			JsonArray out = new JsonArray();
			for (JsonElement e : tpl.getAsJsonArray())
			{
				out.add(unflattenValue(e, leaves, types, pos));
			}
			return out;
		}
		JsonObject out = new JsonObject();
		for (Map.Entry<String, JsonElement> e : tpl.getAsJsonObject().entrySet())
		{
			out.add(e.getKey(), unflattenValue(e.getValue(), leaves, types, pos));
		}
		return out;
	}

	private static JsonArray unflatten(JsonArray tpl, Object[] leaves, byte[] types, ProjOf projOf)
	{
		String sig = sigOf(tpl);
		JsonArray row = new JsonArray();
		row.add(tpl.get(0));
		int[] pos = {0};
		for (int i = 0; i < sig.length(); i++)
		{
			char t = sig.charAt(i);
			JsonElement a = tpl.get(i + 1);
			if (a == null || a.isJsonNull())
			{
				row.add(JsonNull.INSTANCE);
			}
			else if (t == 'P')
			{
				row.add(projOf.proj((Long) leaves[pos[0]++]));
			}
			else if (t == 'f' || t == 'd' || t == 'i' || t == 'l')
			{
				int k = pos[0]++;
				row.add(leafValue(leaves[k], types[k]));
			}
			else if (t == 'M' && isModelRef(a))
			{
				JsonObject o = new JsonObject();
				o.addProperty("model", (Long) leaves[pos[0]++]);
				row.add(o);
			}
			else
			{
				row.add(unflattenValue(a, leaves, types, pos));
			}
		}
		return row;
	}

	/** Which call in the previous frame this one continues: the object it draws, or its zone or tile. */
	static String identity(JsonArray row)
	{
		String name = row.get(0).getAsString();
		for (int i = 1; i < row.size(); i++)
		{
			JsonElement a = row.get(i);
			if (a != null && a.isJsonObject() && a.getAsJsonObject().has("hash"))
			{
				return name + '#' + a.getAsJsonObject().get("hash").getAsString();
			}
		}
		switch (name)
		{
			case "drawZoneOpaque":
				return "zo#" + row.get(3) + ',' + row.get(4);
			case "drawZoneAlpha":
				return "za#" + row.get(3) + ',' + row.get(4) + ',' + row.get(5);
			case "drawScenePaint":
				return "sp#" + row.get(3) + ',' + row.get(4) + ',' + row.get(5);
			case "drawSceneTileModel":
				return "tm#" + row.get(3) + ',' + row.get(4);
			default:
				return name;
		}
	}

	private static boolean leafEq(Object a, Object b, byte t)
	{
		if (t == F32)
		{
			return Float.floatToIntBits((float) (double) (Double) a) == Float.floatToIntBits((float) (double) (Double) b);
		}
		if (t == F64)
		{
			return Double.doubleToLongBits((Double) a) == Double.doubleToLongBits((Double) b);
		}
		return a.equals(b);
	}

	/** Prediction state, updated the same way by encoder and decoder after every row. */
	private static final class Predictor
	{
		final Map<Long, Long> succ = new HashMap<>();
		final Map<Long, int[]> score = new HashMap<>();

		Object[] predict(Entry base)
		{
			Object[] out = base.leaves.clone();
			for (int i = 0; i < out.length; i++)
			{
				byte t = base.types[i];
				if (t == MODEL)
				{
					Long s = succ.get((Long) base.leaves[i]);
					if (s != null)
					{
						out[i] = s;
					}
				}
				else if (t == INT && base.pl != null && base.pl != base.leaves && base.pl[i] instanceof Long)
				{
					int[] sc = score.get(base.shape * 4096L + i);
					if (sc != null && sc[1] > sc[0])
					{
						long v = (Long) base.leaves[i];
						out[i] = v + (v - (Long) base.pl[i]);
					}
				}
			}
			return out;
		}

		void learn(Entry base, Object[] leaves)
		{
			for (int i = 0; i < leaves.length; i++)
			{
				byte t = base.types[i];
				if (t == MODEL)
				{
					if (!leaves[i].equals(base.leaves[i]))
					{
						succ.put((Long) base.leaves[i], (Long) leaves[i]);
					}
				}
				else if (t == INT && base.pl != null && base.pl != base.leaves && base.pl[i] instanceof Long)
				{
					int[] sc = score.computeIfAbsent(base.shape * 4096L + i, k -> new int[2]);
					long v = (Long) base.leaves[i];
					if (leaves[i].equals(v))
					{
						sc[0]++;
					}
					if (leaves[i].equals(v + (v - (Long) base.pl[i])))
					{
						sc[1]++;
					}
				}
			}
		}
	}

	private static float[] projFloats(JsonObject p)
	{
		List<Float> out = new ArrayList<>(28);
		if (p.has("s"))
		{
			for (JsonElement v : p.getAsJsonArray("s"))
			{
				for (JsonElement x : v.getAsJsonArray())
				{
					out.add(x.getAsFloat());
				}
			}
		}
		if (p.has("m"))
		{
			for (JsonElement x : p.getAsJsonArray("m"))
			{
				out.add(x.getAsFloat());
			}
		}
		float[] a = new float[out.size()];
		for (int i = 0; i < a.length; i++)
		{
			a[i] = out.get(i);
		}
		return a;
	}

	// ops: 0 end, 1 copy n, 2 seek, 3 edit, 4 new row of a known shape, 5 new shape, 6 n rows exactly as predicted

	static final class Encoder
	{
		private final Map<String, Entry> shapes = new HashMap<>(); // shape key -> last entry of that shape (its id in .shape)
		private final Map<String, Integer> strings = new HashMap<>();
		private final List<JsonObject> projTable = new ArrayList<>();
		private final Map<String, Integer> projIds = new HashMap<>();
		private final float[][] lastProj = new float[2][];
		private Predictor pred = new Predictor();
		private List<Entry> prev = new ArrayList<>();

		void reset()
		{
			shapes.clear();
			strings.clear();
			projTable.clear();
			projIds.clear();
			lastProj[0] = lastProj[1] = null;
			pred = new Predictor();
			prev = new ArrayList<>();
		}

		byte[] encode(List<JsonArray> rows)
		{
			Bytes.Out w = new Bytes.Out(1024);
			List<JsonObject> newProjs = new ArrayList<>();
			ProjRef ref = p ->
			{
				String k = p.toString();
				Integer id = projIds.get(k);
				if (id == null)
				{
					id = projTable.size();
					projTable.add(p);
					projIds.put(k, id);
					newProjs.add(p);
				}
				return id;
			};
			List<Entry> ents = new ArrayList<>(rows.size());
			for (JsonArray row : rows)
			{
				String sig = sigOf(row);
				Entry e = new Entry();
				e.row = row;
				e.shapeKey = rowShape(row, sig);
				e.id = identity(row);
				flatten(row, sig, ref, e);
				ents.add(e);
			}
			// projection references relative to this frame's table: 0 is the newest
			for (Entry e : ents)
			{
				for (int i = 0; i < e.types.length; i++)
				{
					if (e.types[i] == PROJ)
					{
						e.leaves[i] = (long) (projTable.size() - 1) - (Long) e.leaves[i];
					}
				}
			}
			Map<String, List<Integer>> byId = new HashMap<>();
			for (int j = 0; j < prev.size(); j++)
			{
				byId.computeIfAbsent(prev.get(j).id, k -> new ArrayList<>()).add(j);
			}
			boolean[] used = new boolean[prev.size()];
			int cursor = 0;
			int[] run = {0, 0}; // count, op
			for (Entry e : ents)
			{
				int q = -1;
				if (cursor < prev.size() && !used[cursor] && prev.get(cursor).id.equals(e.id))
				{
					q = cursor;
				}
				else
				{
					List<Integer> c = byId.get(e.id);
					if (c != null)
					{
						for (int x : c)
						{
							if (!used[x])
							{
								q = x;
								break;
							}
						}
					}
				}
				if (q >= 0 && prev.get(q).shapeKey.equals(e.shapeKey))
				{
					Entry base = prev.get(q);
					e.shape = base.shape;
					e.tpl = base.tpl;
					if (q != cursor)
					{
						flushRun(w, run);
						w.varint(2);
						w.zz(q - cursor);
						cursor = q;
					}
					used[q] = true;
					cursor = q + 1;
					e.pl = base.leaves;
					if (allEq(e.leaves, base.leaves, e.types))
					{
						e.leaves = base.leaves;
						pred.learn(base, e.leaves);
						addRun(w, run, 1);
						continue;
					}
					Object[] p = pred.predict(base);
					boolean asPred = allEq(e.leaves, p, e.types);
					pred.learn(base, e.leaves);
					if (asPred)
					{
						e.leaves = p;
						addRun(w, run, 6);
						continue;
					}
					flushRun(w, run);
					w.varint(3);
					writeLeaves(w, p, e);
					shapes.put(e.shapeKey, e);
				}
				else
				{
					flushRun(w, run);
					Entry s = shapes.get(e.shapeKey);
					if (s != null)
					{
						e.shape = s.shape;
						e.tpl = s.tpl;
						w.varint(4);
						w.varint(s.shape);
						writeLeaves(w, s.leaves, e);
						shapes.put(e.shapeKey, e);
					}
					else
					{
						// a new shape: the row itself, projections blanked, then its leaves against the row's own
						e.shape = shapes.size();
						String sig = sigOf(e.row);
						JsonArray tpl = new JsonArray();
						tpl.add(e.row.get(0));
						for (int i = 0; i < sig.length(); i++)
						{
							JsonElement a = e.row.get(i + 1);
							tpl.add(sig.charAt(i) == 'P' && a != null && !a.isJsonNull() ? new JsonObject() : a);
						}
						e.tpl = tpl;
						w.varint(5);
						w.str(tpl.toString());
						Entry t = new Entry();
						flatten(tpl, sig, p -> 0, t);
						writeLeaves(w, t.leaves, e);
						shapes.put(e.shapeKey, e);
					}
				}
			}
			flushRun(w, run);
			w.varint(0);
			w.varint(newProjs.size());
			for (JsonObject p : newProjs)
			{
				if (!p.has("s"))
				{
					w.u8(2);
					w.str(p.toString());
					continue;
				}
				int kind = p.has("m") ? 1 : 0;
				float[] fl = projFloats(p), base = lastProj[kind];
				w.u8(kind);
				w.varint(fl.length);
				for (int i = 0; i < fl.length; i++)
				{
					int b = Float.floatToIntBits(fl[i]);
					w.varint((base != null && i < base.length ? b ^ Float.floatToIntBits(base[i]) : b) & 0xFFFFFFFFL);
				}
				lastProj[kind] = fl;
			}
			prev = ents;
			return w.toArray();
		}

		private static boolean allEq(Object[] a, Object[] b, byte[] t)
		{
			for (int i = 0; i < a.length; i++)
			{
				if (!leafEq(a[i], b[i], t[i]))
				{
					return false;
				}
			}
			return true;
		}

		private static void addRun(Bytes.Out w, int[] run, int op)
		{
			if (run[1] != op)
			{
				flushRun(w, run);
			}
			run[1] = op;
			run[0]++;
		}

		private static void flushRun(Bytes.Out w, int[] run)
		{
			if (run[0] > 0)
			{
				w.varint(run[1]);
				w.varint(run[0]);
				run[0] = 0;
			}
		}

		private void writeLeaves(Bytes.Out w, Object[] p, Entry e)
		{
			int miss = 0;
			for (int i = 0; i < e.leaves.length; i++)
			{
				if (!leafEq(e.leaves[i], p[i], e.types[i]))
				{
					miss++;
				}
			}
			w.varint(miss);
			int last = -1;
			for (int i = 0; i < e.leaves.length; i++)
			{
				if (leafEq(e.leaves[i], p[i], e.types[i]))
				{
					continue;
				}
				w.varint(i - last - 1);
				last = i;
				byte t = e.types[i];
				Object a = e.leaves[i], b = p[i];
				if (t == INT || t == BOOL || t == PROJ || t == MODEL)
				{
					w.zz((Long) a - (Long) b);
				}
				else if (t == F32)
				{
					w.varint((Float.floatToIntBits((float) (double) (Double) a) ^ Float.floatToIntBits((float) (double) (Double) b)) & 0xFFFFFFFFL);
				}
				else if (t == F64)
				{
					w.varint(Double.doubleToLongBits((Double) a) ^ Double.doubleToLongBits((Double) b));
				}
				else
				{
					Integer id = strings.get(a);
					if (id == null)
					{
						w.varint(0);
						w.str((String) a);
						strings.put((String) a, strings.size());
					}
					else
					{
						w.varint(id + 1);
					}
				}
			}
		}
	}

	static final class Decoder
	{
		private final List<Entry> shapes = new ArrayList<>();
		private final List<String> strings = new ArrayList<>();
		private final List<JsonElement> projTable = new ArrayList<>();
		private final float[][] lastProj = new float[2][];
		private Predictor pred = new Predictor();
		private List<Entry> prev = new ArrayList<>();

		void reset()
		{
			shapes.clear();
			strings.clear();
			projTable.clear();
			lastProj[0] = lastProj[1] = null;
			pred = new Predictor();
			prev = new ArrayList<>();
		}

		List<JsonArray> decode(byte[] bytes)
		{
			Bytes.In r = new Bytes.In(bytes);
			List<Entry> ents = new ArrayList<>(prev.size() + 8);
			int cursor = 0;
			for (; ; )
			{
				int op = r.varint32();
				if (op == 0)
				{
					break;
				}
				if (op == 1 || op == 6)
				{
					int n = r.varint32();
					for (int k = 0; k < n; k++)
					{
						Entry base = prev.get(cursor++);
						Object[] leaves = op == 1 ? base.leaves : pred.predict(base);
						pred.learn(base, leaves);
						ents.add(next(base, leaves));
					}
				}
				else if (op == 2)
				{
					cursor += (int) r.zz();
				}
				else if (op == 3)
				{
					Entry base = prev.get(cursor++);
					Object[] leaves = readLeaves(r, pred.predict(base), base.types);
					pred.learn(base, leaves);
					Entry e = next(base, leaves);
					ents.add(e);
					shapes.set(base.shape, e);
				}
				else if (op == 4)
				{
					Entry s = shapes.get(r.varint32());
					Entry e = new Entry();
					e.tpl = s.tpl;
					e.types = s.types;
					e.shape = s.shape;
					e.leaves = readLeaves(r, s.leaves, s.types);
					shapes.set(s.shape, e);
					ents.add(e);
				}
				else if (op == 5)
				{
					JsonArray tpl = new com.google.gson.JsonParser().parse(r.str()).getAsJsonArray();
					Entry t = new Entry();
					flatten(tpl, sigOf(tpl), p -> 0, t);
					Entry e = new Entry();
					e.tpl = tpl;
					e.types = t.types;
					e.shape = shapes.size();
					e.leaves = readLeaves(r, t.leaves, t.types);
					shapes.add(e);
					ents.add(e);
				}
				else
				{
					throw new IllegalArgumentException("bad op " + op);
				}
			}
			int np = r.varint32();
			for (int k = 0; k < np; k++)
			{
				int kind = r.u8();
				if (kind == 2)
				{
					projTable.add(new com.google.gson.JsonParser().parse(r.str()));
					continue;
				}
				int len = r.varint32();
				float[] base = lastProj[kind], fl = new float[len];
				for (int i = 0; i < len; i++)
				{
					int x = (int) r.varint();
					fl[i] = Float.intBitsToFloat(base != null && i < base.length ? x ^ Float.floatToIntBits(base[i]) : x);
				}
				lastProj[kind] = fl;
				JsonObject p = new JsonObject();
				p.addProperty("proj", kind == 1 ? "float" : "other");
				if (kind == 1)
				{
					JsonArray m = new JsonArray();
					for (int i = 12; i < len; i++)
					{
						m.add(fl[i]);
					}
					p.add("m", m);
				}
				JsonArray s = new JsonArray();
				for (int i = 0; i < 4; i++)
				{
					JsonArray v = new JsonArray();
					for (int j = 0; j < 3; j++)
					{
						v.add(fl[i * 3 + j]);
					}
					s.add(v);
				}
				p.add("s", s);
				projTable.add(p);
			}
			ProjOf projOf = rel -> projTable.get((int) (projTable.size() - 1 - rel));
			List<JsonArray> out = new ArrayList<>(ents.size());
			for (Entry e : ents)
			{
				out.add(unflatten(e.tpl, e.leaves, e.types, projOf));
			}
			prev = ents;
			return out;
		}

		private static Entry next(Entry base, Object[] leaves)
		{
			Entry e = new Entry();
			e.tpl = base.tpl;
			e.types = base.types;
			e.shape = base.shape;
			e.leaves = leaves;
			e.pl = base.leaves;
			return e;
		}

		private Object[] readLeaves(Bytes.In r, Object[] p, byte[] types)
		{
			Object[] leaves = p.clone();
			int n = r.varint32(), i = -1;
			for (int k = 0; k < n; k++)
			{
				i += r.varint32() + 1;
				byte t = types[i];
				Object b = p[i];
				if (t == INT || t == BOOL || t == PROJ || t == MODEL)
				{
					leaves[i] = (Long) b + r.zz();
				}
				else if (t == F32)
				{
					int x = (int) r.varint();
					leaves[i] = (double) Float.intBitsToFloat(x ^ Float.floatToIntBits((float) (double) (Double) b));
				}
				else if (t == F64)
				{
					leaves[i] = Double.longBitsToDouble(r.varint() ^ Double.doubleToLongBits((Double) b));
				}
				else
				{
					int id = r.varint32();
					if (id == 0)
					{
						String s = r.str();
						strings.add(s);
						leaves[i] = s;
					}
					else
					{
						leaves[i] = strings.get(id - 1);
					}
				}
			}
			return leaves;
		}
	}
}

package com.renderreplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

import org.junit.Test;

public class ArrayPoolTest
{
	@Test
	public void equalArraysBecomeOneAndAreCountedOnce()
	{
		ArrayPool pool = new ArrayPool();
		int[] a = pool.share(new int[]{1, 2, 3});
		assertEquals(16 + 12, pool.takeAdded());
		assertSame(a, pool.share(new int[]{1, 2, 3}));
		assertEquals(0, pool.takeAdded());

		assertNotSame(a, pool.share(new int[]{1, 2, 4}));
		assertNotSame(a, pool.share(new int[]{1, 2}));
		assertNull(pool.share((int[]) null));
	}

	@Test
	public void everyElementTypeIsShared()
	{
		ArrayPool pool = new ArrayPool();
		float[] f = pool.share(new float[]{1.5f, 2});
		short[] s = pool.share(new short[]{-1, 4});
		byte[] b = pool.share(new byte[]{9});
		assertSame(f, pool.share(new float[]{1.5f, 2}));
		assertSame(s, pool.share(new short[]{-1, 4}));
		assertSame(b, pool.share(new byte[]{9}));
		// same length and hash, another type: must not be handed out as the wrong kind of array
		int[] zeros = pool.share(new int[2]);
		float[] floatZeros = pool.share(new float[2]);
		assertSame(zeros, pool.share(new int[2]));
		assertSame(floatZeros, pool.share(new float[2]));
	}
}

package com.renderreplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import org.junit.Test;

public class CallPoolTest
{
	@Test
	public void equalCallsOfConsecutiveFramesAreOneObject()
	{
		CallPool pool = new CallPool();
		Object scene = new Object();
		Object[] first = pool.share(Call.DRAW_ZONE_OPAQUE, new Object[]{null, scene, 300, 7});
		assertTrue("a new call is counted", pool.endFrame() > 0);

		// boxed again by the next frame's call: equal values, different objects
		Object[] second = pool.share(Call.DRAW_ZONE_OPAQUE, new Object[]{null, scene, Integer.valueOf(300), 7});
		assertSame(first, second);
		assertEquals("a shared call adds nothing", 0, pool.endFrame());
	}

	@Test
	public void differentArgumentsOrMethodsAreNotShared()
	{
		CallPool pool = new CallPool();
		Object scene = new Object();
		Object[] a = pool.share(Call.DRAW_ZONE_OPAQUE, new Object[]{null, scene, 3, 7});
		assertNotSame(a, pool.share(Call.DRAW_ZONE_OPAQUE, new Object[]{null, scene, 3, 8}));
		assertNotSame(a, pool.share(Call.DRAW_ZONE_OPAQUE, new Object[]{null, new Object(), 3, 7}));
		assertNotSame(a, pool.share(Call.DRAW_PASS, new Object[]{null, scene, 3}));
		assertSame(a, pool.share(Call.DRAW_ZONE_OPAQUE, new Object[]{null, scene, 3, 7}));
	}

	@Test
	public void liveObjectsAreComparedByIdentityAndFrozenCopiesByContent()
	{
		CallPool pool = new CallPool();
		StandIns.StandInTileObject live = new StandIns.StandInTileObject(), other = new StandIns.StandInTileObject();
		Object[] a = pool.share(Call.DRAW_DYNAMIC, new Object[]{null, null, live, null, null, 0, 1, 2, 3});
		assertNotSame("two objects, even with equal fields", a,
			pool.share(Call.DRAW_DYNAMIC, new Object[]{null, null, other, null, null, 0, 1, 2, 3}));

		Object[] t = pool.share(Call.DRAW_TEMP, new Object[]{null, null, actor(5), null, 0, 1, 2, 3});
		Object[] s = pool.share(Call.PRE_SCENE_DRAW, new Object[]{null, 1f, 2f, 3f, 4f, 5f, 0, 0, 0, new HashSet<>(Arrays.asList(1, 2))});
		pool.endFrame();
		assertSame(t, pool.share(Call.DRAW_TEMP, new Object[]{null, null, actor(5), null, 0, 1, 2, 3}));
		assertNotSame(t, pool.share(Call.DRAW_TEMP, new Object[]{null, null, actor(6), null, 0, 1, 2, 3}));
		assertSame(s, pool.share(Call.PRE_SCENE_DRAW, new Object[]{null, 1f, 2f, 3f, 4f, 5f, 0, 0, 0, new HashSet<>(Arrays.asList(2, 1))}));
	}

	@Test
	public void aCallIsOnlySharedWithThePreviousFrame()
	{
		CallPool pool = new CallPool();
		Object[] a = pool.share(Call.DRAW_PASS, new Object[]{null, null, 1});
		pool.endFrame();
		pool.endFrame(); // a frame without the call
		assertNotSame(a, pool.share(Call.DRAW_PASS, new Object[]{null, null, 1}));
	}

	private static StandIns.StandInGameObject actor(int x)
	{
		StandIns.StandInGameObject g = new StandIns.StandInGameObject();
		g.hash = 77;
		g.x = x;
		g.min = new net.runelite.api.Point(1, 2);
		g.max = new net.runelite.api.Point(1, 2);
		StandIns.StandInRenderable r = new StandIns.StandInRenderable();
		r.height = 100;
		g.renderable = r;
		return g;
	}
}

