import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import org.junit.Test;

public class FileReplayTest
{
	private static JsonObject json(String s)
	{
		return new JsonParser().parse(s).getAsJsonObject();
	}

	@Test
	public void modelStandInAnswersEveryGetterTheGpuPluginReads()
	{
		Model m = FileReplay.model(json("{\"id\":5,\"kind\":\"model\",\"vn\":3,\"fn\":1,\"vx\":[1.5,2,3],\"vy\":[0,0,0],\"vz\":[4,5,6],"
			+ "\"f1\":[0],\"f2\":[1],\"f3\":[2],\"c1\":[100],\"c2\":[101],\"c3\":[102],\"tr\":[0],\"pri\":[3],\"ft\":[-1],\"fb\":[7],"
			+ "\"ov\":[1,2,3,4],\"tp\":9,\"tf\":[1],\"t1\":[0],\"t2\":[1],\"t3\":[2],\"rad\":50,\"dia\":100}"), new ArrayPool());
		assertEquals(3, m.getVerticesCount());
		assertEquals(1, m.getFaceCount());
		assertArrayEquals(new float[]{1.5f, 2, 3}, m.getVerticesX(), 0);
		assertArrayEquals(new int[]{102}, m.getFaceColors3());
		assertArrayEquals(new byte[]{3}, m.getFaceRenderPriorities());
		assertArrayEquals(new short[]{-1}, m.getFaceTextures());
		assertArrayEquals(new byte[]{7}, m.getFaceBias());
		assertEquals(2, m.getOverrideHue());
		assertEquals(4, m.getOverrideLuminance());
		assertEquals(9, m.getTransparency());
		assertEquals("computed from the vertices, not read from the file", 7, m.getRadius());
		assertEquals(14, m.getDiameter());
		m.setBufferOffset(77);                      // state the GPU plugin writes back
		assertEquals(77, m.getBufferOffset());
		m.calculateBoundsCylinder();                // not saved: harmless no-op
		assertEquals(0, m.getXYZMag());             // unknown getters answer 0 instead of throwing
	}

	@Test
	public void copyOfFreezesALiveModelWithoutSharingItsArrays()
	{
		StandIns.StandInModel live = new StandIns.StandInModel();
		live.vn = 2;
		live.fn = 1;
		live.vx = new float[]{1, 2, 99, 99};        // the client hands back oversized backing arrays
		live.vy = new float[]{3, 4, 99, 99};
		live.vz = new float[]{5, 6, 99, 99};
		live.f1 = new int[]{0, 99};
		live.f2 = new int[]{1, 99};
		live.f3 = new int[]{0, 99};
		live.c1 = new int[]{100, 99};
		live.c2 = new int[]{101, 99};
		live.c3 = new int[]{102, 99};
		live.pri = new byte[]{3, 9};
		live.ft = new short[]{-1, 9};
		live.tf = new byte[]{1, 2, 3};               // per texture face, not per face: kept whole
		live.t1 = new int[]{0, 1, 2};
		live.ov1 = 2;
		live.tp = 9;
		live.rad = 50;
		live.dia = 100;

		Model copy = FileReplay.copyOf(live, new ArrayPool());
		assertEquals(2, copy.getVerticesCount());
		assertEquals(1, copy.getFaceCount());
		assertArrayEquals(new float[]{1, 2}, copy.getVerticesX(), 0);
		assertArrayEquals(new int[]{102}, copy.getFaceColors3());
		assertArrayEquals(new byte[]{3}, copy.getFaceRenderPriorities());
		assertArrayEquals(new short[]{-1}, copy.getFaceTextures());
		assertArrayEquals(new byte[]{1, 2, 3}, copy.getTextureFaces());
		assertArrayEquals(new int[]{0, 1, 2}, copy.getTexIndices1());
		assertNull(copy.getFaceTransparencies());   // absent arrays stay absent
		assertNull(copy.getTexIndices2());
		assertEquals(2, copy.getOverrideHue());
		assertEquals(9, copy.getTransparency());
		// the live model's own values may not be computed yet: xz radius 7, nothing above the origin, 4 below it
		assertEquals(7, copy.getRadius());
		assertEquals(16, copy.getDiameter());

		live.c1[0] = 7;                              // the client rewrites its model after the frame
		live.vx[0] = 7;
		live.tf[0] = 7;
		assertArrayEquals(new int[]{100}, copy.getFaceColors1());
		assertArrayEquals(new float[]{1, 2}, copy.getVerticesX(), 0);
		assertArrayEquals(new byte[]{1, 2, 3}, copy.getTextureFaces());
	}

	@Test
	public void copiesOfAnAnimatedModelShareWhatDoesNotChange()
	{
		StandIns.StandInModel live = new StandIns.StandInModel();
		live.vn = 2;
		live.fn = 1;
		live.vx = new float[]{1, 2};
		live.vy = new float[]{3, 4};
		live.vz = new float[]{5, 6};
		live.f1 = new int[]{0};
		live.c1 = new int[]{100};
		live.pri = new byte[]{3};
		ArrayPool pool = new ArrayPool();
		Model first = FileReplay.copyOf(live, pool);
		live.vy[1] = 9;                              // the next pose moves a vertex
		Model second = FileReplay.copyOf(live, pool);

		assertSame(first.getFaceIndices1(), second.getFaceIndices1());
		assertSame(first.getFaceColors1(), second.getFaceColors1());
		assertSame(first.getFaceRenderPriorities(), second.getFaceRenderPriorities());
		assertSame(first.getVerticesX(), second.getVerticesX());
		assertArrayEquals(new float[]{3, 4}, first.getVerticesY(), 0);
		assertArrayEquals(new float[]{3, 9}, second.getVerticesY(), 0);
	}

	@Test
	public void gameObjectStandInCarriesWhatDrawTempReads()
	{
		GameObject g = FileReplay.gameObject(json("{\"go\":16608,\"hash\":17414815744,\"xyz\":[5504,6016,-160],\"plane\":1,\"ori\":[256,512,3],"
			+ "\"size\":[2,2],\"box\":[42,46,43,47],\"h\":371,\"m\":0}"));
		assertEquals(16608, g.getId());
		assertEquals(17414815744L, g.getHash());
		assertEquals(5504, g.getX());
		assertEquals(-160, g.getZ());
		assertEquals(1, g.getPlane());
		assertEquals(512, g.getModelOrientation());
		assertEquals(2, g.sizeX());
		assertEquals(46, g.getSceneMinLocation().getY());
		assertEquals(47, g.getSceneMaxLocation().getY());
		assertNotNull(g.getRenderable());
		assertEquals(371, g.getRenderable().getModelHeight());
		assertNull(g.getWorldView());
	}

	@Test
	public void projectionIsRebuiltFromFourSamplePoints()
	{
		// map: out = (x*2 + 10, y*1, z*-1)
		Projection p = FileReplay.projection(json("{\"proj\":\"eu\",\"s\":[[10,0,0],[266,0,0],[10,128,0],[10,0,-128]]}"));
		float[] r = p.project(64, 32, 16);
		assertArrayEquals(new float[]{138, 32, -16}, r, 0.001f);
	}

	@Test
	public void paintAndTileModel()
	{
		com.google.gson.JsonArray c = new JsonParser().parse("[7,1,2,3,4,-1,1]").getAsJsonArray();
		net.runelite.api.SceneTilePaint t = FileReplay.paint(c);
		assertEquals(7, t.getRBG());
		assertEquals(3, t.getNwColor());
		assertTrue(t.isFlat());
		net.runelite.api.SceneTileModel tm = FileReplay.tileModel(json("{\"id\":1,\"vx\":[0,128],\"vy\":[0,0],\"vz\":[0,128],\"f1\":[0],\"f2\":[1],\"f3\":[0],\"c1\":[1],\"c2\":[2],\"c3\":[3],\"tex\":[-1],\"flat\":true}"));
		assertArrayEquals(new int[]{0, 128}, tm.getVertexX());
		assertTrue(tm.isFlat());
	}
}

package com.renderreplay;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Random;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FrameStoreLayerTest
{
	// The client's pixel array is one longer than width x height; the layer must still be coded as changes and come
	// back exactly, at the client's length, so playback can paint it.
	@Test
	public void layerWithAPixelPastTheLastRowIsKeptAsChangesAndPlaysBack()
	{
		int w = 200, h = 150, n = w * h + 1, frames = 90;
		int[][] layers = new int[frames][];
		Random rnd = new Random(7);
		int[] layer = new int[n];
		for (int y = 100; y < 150; y++)
		{
			for (int x = 0; x < 120; x++)
			{
				layer[y * w + x] = 0xFF000000 | rnd.nextInt(1 << 24);
			}
		}
		FrameStore st = new FrameStore(Presets.ALL[0], new com.google.gson.Gson(), id -> null);
		for (int f = 0; f < frames; f++)
		{
			// a click cross moving about, and a chat line appearing
			int cx = 20 + f, cy = 30 + f % 40;
			for (int d = -3; d <= 3; d++)
			{
				layer[(cy + d) * w + cx + d] = 0xFFFF0000;
				layer[(cy - d) * w + cx + d] = 0xFFFF0000;
			}
			if (f % 30 == 10)
			{
				Arrays.fill(layer, 140 * w, 140 * w + 100, 0xFF0000FF);
			}
			layers[f] = layer.clone();
			st.append(f * 20L, f / 30, 512, f, null, 0f, null, new ArrayList<>(), layer.clone(), w, null);
		}
		st.finish();
		assertTrue("2D layer kept as changes, not a whole image every frame: " + st.uiBytes(), st.uiBytes() < frames * 2000L);
		for (int i = 0; i < frames; i++)
		{
			int[] got = st.ui(i);
			assertEquals("frame " + i + " length", n, got.length);
			assertArrayEquals("frame " + i, Arrays.copyOf(layers[i], w * h), Arrays.copyOf(got, w * h));
		}
		int[] seek = st.ui(frames / 2).clone();
		assertArrayEquals(Arrays.copyOf(layers[frames / 2], w * h), Arrays.copyOf(seek, w * h));
	}
}

package com.renderreplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Canvas;
import java.awt.event.KeyEvent;
import org.junit.Test;

public class PlaybackKeysTest
{
	private static final Canvas SRC = new Canvas();

	private static KeyEvent key(int id)
	{
		// KEY_TYPED events must carry VK_UNDEFINED; pressed/released carry the real key code
		return new KeyEvent(SRC, id, 0L, 0, id == KeyEvent.KEY_TYPED ? KeyEvent.VK_UNDEFINED : KeyEvent.VK_A, 'a');
	}

	@Test
	public void nothingIsConsumedWhenPlaybackIsNotActive()
	{
		PlaybackKeys b = new PlaybackKeys(() -> { }, (d, r) -> { });
		KeyEvent k = press(KeyEvent.VK_LEFT);
		b.keyPressed(k);
		assertFalse(k.isConsumed());
	}

	@Test
	public void onlyTheThreeTransportKeysAreConsumedWhilePlaying()
	{
		PlaybackKeys b = new PlaybackKeys(() -> { }, (d, r) -> { });
		b.setActive(true);
		KeyEvent a = key(KeyEvent.KEY_PRESSED), ar = key(KeyEvent.KEY_RELEASED), at = key(KeyEvent.KEY_TYPED);
		b.keyPressed(a);
		b.keyReleased(ar);
		b.keyTyped(at);
		assertFalse("other keys always reach the game", a.isConsumed() || ar.isConsumed() || at.isConsumed());
		KeyEvent l = press(KeyEvent.VK_LEFT), r = press(KeyEvent.VK_RIGHT), s = press(KeyEvent.VK_SPACE);
		b.keyPressed(l);
		b.keyPressed(r);
		b.keyPressed(s);
		assertTrue(l.isConsumed() && r.isConsumed() && s.isConsumed());
		b.setActive(false);
		KeyEvent l2 = press(KeyEvent.VK_LEFT);
		b.keyPressed(l2);
		assertFalse("playback over: keys flow to the game again", l2.isConsumed());
	}

	private static KeyEvent press(int code)
	{
		return new KeyEvent(SRC, KeyEvent.KEY_PRESSED, 0L, 0, code, code == KeyEvent.VK_SPACE ? ' ' : KeyEvent.CHAR_UNDEFINED);
	}

	private static KeyEvent release(int code)
	{
		return new KeyEvent(SRC, KeyEvent.KEY_RELEASED, 0L, 0, code, code == KeyEvent.VK_SPACE ? ' ' : KeyEvent.CHAR_UNDEFINED);
	}

	@Test
	public void arrowKeysStepAndSpaceTogglesOnlyWhilePlaying()
	{
		java.util.List<String> log = new java.util.ArrayList<>();
		PlaybackKeys b = new PlaybackKeys(() -> log.add("toggle"), (d, r) -> log.add("step" + d + (r ? "r" : "")));

		KeyEvent left = press(KeyEvent.VK_LEFT);
		b.keyPressed(left);
		assertFalse("not playing: key passes through", left.isConsumed());
		assertTrue(log.isEmpty());

		b.setActive(true);
		KeyEvent l2 = press(KeyEvent.VK_LEFT), r2 = press(KeyEvent.VK_RIGHT), r3 = press(KeyEvent.VK_RIGHT);
		b.keyPressed(l2);
		b.keyPressed(r2);
		b.keyPressed(r3);            // Right still down: this one is an auto-repeat
		assertTrue(l2.isConsumed() && r2.isConsumed());
		assertEquals("a fresh press, then an auto-repeat flagged as such", java.util.Arrays.asList("step-1", "step1", "step1r"), log);

		log.clear();
		b.keyPressed(press(KeyEvent.VK_SPACE));
		b.keyPressed(press(KeyEvent.VK_SPACE));   // auto-repeat
		assertEquals("space auto-repeat must not toggle repeatedly", java.util.Arrays.asList("toggle"), log);
		b.keyReleased(release(KeyEvent.VK_SPACE));
		b.keyPressed(press(KeyEvent.VK_SPACE));
		assertEquals("a fresh press after release toggles again", java.util.Arrays.asList("toggle", "toggle"), log);

		log.clear();
		KeyEvent a = new KeyEvent(SRC, KeyEvent.KEY_PRESSED, 0L, 0, KeyEvent.VK_A, 'a');
		b.keyPressed(a);
		assertFalse("any other key is left alone", a.isConsumed());
		assertTrue("and does nothing", log.isEmpty());
	}

	@Test
	public void holdingLeftRewindsSteadilyNotThirtyTicksASecond() throws Exception
	{
		java.util.List<String> log = new java.util.ArrayList<>();
		PlaybackKeys b = new PlaybackKeys(() -> { }, (d, r) -> log.add("step" + d + (r ? "r" : "")));
		b.setActive(true);
		b.keyPressed(press(KeyEvent.VK_LEFT));                    // fresh press: immediate
		for (int i = 0; i < 12; i++)
		{
			b.keyPressed(press(KeyEvent.VK_LEFT));                // a burst of auto-repeats within the throttle window
		}
		assertEquals("only the first press acts inside the window", java.util.Arrays.asList("step-1"), log);
		b.lastLeftMs -= PlaybackKeys.LEFT_REPEAT_MS + 40;         // as if the throttle window had passed
		b.keyPressed(press(KeyEvent.VK_LEFT));                    // still held: one more rewind step
		assertEquals(java.util.Arrays.asList("step-1", "step-1r"), log);
		b.keyReleased(release(KeyEvent.VK_LEFT));
		b.keyPressed(press(KeyEvent.VK_LEFT));                    // a new tap acts immediately again
		assertEquals("step-1", log.get(log.size() - 1));
		assertEquals(3, log.size());
	}
}

package com.renderreplay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.Component;
import java.awt.Container;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.SwingUtilities;
import org.junit.BeforeClass;
import org.junit.Test;

/** The panel layout must be static: nothing may move or resize when the status text or playback state changes. */
public class RenderReplayPanelTest
{
	@BeforeClass
	public static void headless()
	{
		System.setProperty("java.awt.headless", "true");
	}

	private static void layoutAll(Container c)
	{
		c.doLayout();
		for (Component k : c.getComponents())
		{
			if (k instanceof Container)
			{
				layoutAll((Container) k);
			}
		}
	}

	private static void collect(Component c, Component root, List<Component> out)
	{
		out.add(c);
		if (c instanceof Container)
		{
			for (Component k : ((Container) c).getComponents())
			{
				collect(k, root, out);
			}
		}
	}

	private static Rectangle abs(Component c, Component root)
	{
		Rectangle r = SwingUtilities.convertRectangle(c.getParent() == null ? c : c.getParent(), c.getBounds(), root);
		return r;
	}

	private static List<Rectangle> snapshot(RenderReplayPanel p) throws Exception
	{
		SwingUtilities.invokeAndWait(() -> { });   // flush queued panel updates
		List<Rectangle> out = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			layoutAll(p);
			List<Component> all = new ArrayList<>();
			collect(p, p, all);
			for (Component c : all)
			{
				out.add(abs(c, p));
			}
		});
		return out;
	}

	private static RenderReplayPanel panel()
	{
		RenderReplayPanel p = new RenderReplayPanel(() -> { }, () -> { }, ms -> { }, () -> { }, d -> { });
		p.setSize(225, 640);
		return p;
	}

	@Test
	public void layoutDoesNotMoveWhenStatusTextOrPlaybackStateChanges() throws Exception
	{
		RenderReplayPanel p = panel();
		p.update(RenderReplayPlugin.State.IDLE, false, "Idle");
		List<Rectangle> idle = snapshot(p);

		String longText = "Playing. Zoom differs: recorded 2218, yours 5254. Match your zoom for an exact picture. "
			+ "You are in a different area than the recording: terrain shown is your CURRENT area (recorded objects only).";
		p.update(RenderReplayPlugin.State.PLAYING, true, longText);
		p.updatePlayback(true, true, 852);
		p.updateTimeline(2300, 4800, true);
		List<Rectangle> busy = snapshot(p);

		p.updatePlayback(true, false, 853);   // Pause <-> Play label flip
		List<Rectangle> flipped = snapshot(p);

		assertEquals(idle.size(), busy.size());
		for (int i = 0; i < idle.size(); i++)
		{
			assertEquals("component " + i + " moved/resized between idle and playing with long status text", idle.get(i), busy.get(i));
			assertEquals("component " + i + " moved/resized when Pause flipped to Play", busy.get(i), flipped.get(i));
		}
	}

	@Test
	public void transportButtonsAreWideEnoughForTheirLabelsAndRendersToAnImage() throws Exception
	{
		RenderReplayPanel p = panel();
		p.update(RenderReplayPlugin.State.PLAYING, true, "Playing. Zoom differs: recorded 2218, yours 5254. Match your zoom for an exact picture.");
		p.updatePlayback(true, true, 852);
		p.updateTimeline(2300, 4800, true);
		snapshot(p);
		List<Component> all = new ArrayList<>();
		collect(p, p, all);
		for (Component c : all)
		{
			if (c instanceof JButton)
			{
				JButton b = (JButton) c;
				int need = b.getFontMetrics(b.getFont()).stringWidth(b.getText()) + b.getMargin().left + b.getMargin().right;
				assertTrue("button '" + b.getText() + "' is " + b.getWidth() + "px wide but needs " + need + " (would be truncated)", b.getWidth() >= need);
			}
		}
	}

	@Test
	public void timeLabelLeadsWithTicksAndAlwaysShowsSecondsWithOneDecimal()
	{
		assertEquals("<html>tick 852 · 4.0 / 8.0 ticks<br>2.4 s / 4.8 s</html>", RenderReplayPanel.timeText(2400, 4800, 852));
		assertEquals("whole seconds still get a decimal", "<html>0.0 / 10.0 ticks<br>0.0 s / 6.0 s</html>", RenderReplayPanel.timeText(0, 6000, -1));
		assertEquals("<html>1.0 / 1.0 ticks<br>0.6 s / 0.6 s</html>", RenderReplayPanel.timeText(600, 600, -1));
	}

	@org.junit.Test
	public void dragSeeksOncePerTick()
	{
		org.junit.Assert.assertEquals(0, RenderReplayPanel.dragTick(299));
		org.junit.Assert.assertEquals(1, RenderReplayPanel.dragTick(300));
		org.junit.Assert.assertEquals(1, RenderReplayPanel.dragTick(899));
		org.junit.Assert.assertEquals(2, RenderReplayPanel.dragTick(900));
	}

	@org.junit.Test
	public void slotChooserListsSlotsAndReportsSelection() throws Exception
	{
		RenderReplayPanel p = new RenderReplayPanel(() -> { }, () -> { }, ms -> { }, () -> { }, d -> { });
		java.util.List<Integer> picked = new java.util.ArrayList<>();
		p.setSlotHandlers(picked::add, () -> { }, () -> { });
		java.util.List<String> labels = java.util.Arrays.asList("Slot 1 · 20.0 ticks · 10:01", "Slot 2 · empty", "Slot 3 · empty", "Slot 4 · empty");
		p.updateSlots(labels, 0, true, true);
		javax.swing.SwingUtilities.invokeAndWait(() -> { });
		javax.swing.JComboBox<?> box = find(p, javax.swing.JComboBox.class);
		org.junit.Assert.assertEquals(4, box.getItemCount());
		org.junit.Assert.assertTrue(picked.isEmpty());   // programmatic selection must not fire the handler
		javax.swing.SwingUtilities.invokeAndWait(() -> box.setSelectedIndex(2));
		org.junit.Assert.assertEquals(java.util.Arrays.asList(2), picked);
	}

	private static <T> T find(java.awt.Container c, Class<T> type)
	{
		for (java.awt.Component k : c.getComponents())
		{
			if (type.isInstance(k))
			{
				return type.cast(k);
			}
			if (k instanceof java.awt.Container)
			{
				T r = find((java.awt.Container) k, type);
				if (r != null)
				{
					return r;
				}
			}
		}
		return null;
	}
}

