import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class SettingsFingerprintTest
{
	private static Map<String, String> base()
	{
		Map<String, String> m = new HashMap<>();
		m.put("npchighlight.drawOutline", "true");
		m.put("grounditems.showValue", "true");
		m.put("runelite.npchighlightplugin", "true");
		m.put("runelite.windowBounds", "0,0,800,600");
		m.put("renderreplay.anything", "1");
		return m;
	}

	@Test
	public void sameSettingsSameHashRegardlessOfOrderAndIgnoredKeys()
	{
		Map<String, String> a = base();
		Map<String, String> b = new java.util.LinkedHashMap<>();
		b.put("grounditems.showValue", "true");
		b.put("runelite.npchighlightplugin", "true");
		b.put("npchighlight.drawOutline", "true");
		b.put("runelite.windowBounds", "9,9,1,1");   // window state is ignored
		b.put("renderreplay.anything", "2");          // our own settings are ignored
		assertEquals(SettingsFingerprint.of(a).overall, SettingsFingerprint.of(b).overall);
	}

	@Test
	public void changedSettingNamesTheGroup()
	{
		Map<String, String> a = base();
		Map<String, String> b = base();
		b.put("npchighlight.drawOutline", "false");
		SettingsFingerprint fa = SettingsFingerprint.of(a), fb = SettingsFingerprint.of(b);
		assertNotEquals(fa.overall, fb.overall);
		assertEquals(Arrays.asList("npchighlight"), SettingsFingerprint.diff(fa.groups, fb.groups));
	}

	@Test
	public void pluginToggleCountsButOtherRuneliteKeysDoNot()
	{
		Map<String, String> a = base();
		Map<String, String> b = base();
		b.put("runelite.grounditemsplugin", "true");   // newly enabled plugin
		assertTrue(SettingsFingerprint.diff(SettingsFingerprint.of(a).groups, SettingsFingerprint.of(b).groups).contains("runelite"));
	}

	@Test
	public void selfRewrittenValuesDoNotTriggerAWarning()
	{
		Map<String, String> a = base();
		Map<String, String> b = base();
		a.put("lastSeenOnline.Some Player", "1789840000000");
		b.put("lastSeenOnline.Some Player", "1789841234567");
		assertEquals(SettingsFingerprint.of(a).overall, SettingsFingerprint.of(b).overall);
	}
}

package com.renderreplay;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Random;
import org.junit.Test;

public class UiFramesTest
{
	private static int[] noisy(Random r, int[] base, int changes)
	{
		int[] a = base.clone();
		for (int i = 0; i < changes; i++)
		{
			a[r.nextInt(a.length)] = r.nextInt();
		}
		return a;
	}

	@Test
	public void deltaChainReconstructsEveryFrameExactly()
	{
		Random r = new Random(7);
		int[] f0 = noisy(r, new int[50_000], 8000);
		int[] f1 = noisy(r, f0, 300);
		int[] f2 = noisy(r, f1, 0);   // identical frame
		int[] f3 = noisy(r, f2, 9000);
		int[][] frames = {f0, f1, f2, f3};

		byte[][] enc = new byte[frames.length][];
		int[] prev = null;
		for (int i = 0; i < frames.length; i++)
		{
			enc[i] = UiFrames.encode(prev, frames[i]);
			prev = frames[i];
		}

		int[] rebuilt = new int[50_000];
		for (int i = 0; i < frames.length; i++)
		{
			assertEquals(50_000, UiFrames.length(enc[i]));
			UiFrames.apply(enc[i], rebuilt);
			assertArrayEquals("frame " + i, frames[i], rebuilt);
		}
		assertTrue("identical frame should be tiny", enc[2].length < 64);
	}

	@Test
	public void changedRunsAreStoredWithoutTheirSurroundings()
	{
		Random r = new Random(3);
		int w = 400, h = 300;
		int[] before = new int[w * h];
		for (int i = 0; i < before.length; i++)
		{
			before[i] = r.nextInt();
		}
		int[] after = before.clone();
		for (int y = 100; y < 140; y++)       // a 60 x 40 block is redrawn
		{
			for (int x = 50; x < 110; x++)
			{
				after[y * w + x] = r.nextInt();
			}
		}
		after[5] ^= 1;                        // two pixels two apart: one run
		after[8] ^= 1;
		after[w * h - 1] ^= 1;                // the last pixel

		byte[] enc = UiFrames.encode(before, after);
		assertTrue("about 4 bytes per changed pixel, was " + enc.length, enc.length < 60 * 40 * 4 + 1200);
		int[] rebuilt = before.clone();
		UiFrames.apply(enc, rebuilt);
		assertArrayEquals(after, rebuilt);
	}

	@Test(expected = IllegalArgumentException.class)
	public void wrongSizedTargetIsRejected()
	{
		UiFrames.apply(UiFrames.encode(null, new int[10]), new int[11]);
	}

	@Test
	public void keyframeMustClearStalePixelsLeftByEarlierFrames()
	{
		int n = 1000;
		int[] a = new int[n];
		a[10] = 0xff00ff00;                  // an overlay pixel that later moves away
		int[] b = new int[n];
		b[500] = 0xff00ff00;                 // same overlay now elsewhere; pixel 10 is transparent again

		byte[] encA = UiFrames.encode(null, a);
		byte[] keyB = UiFrames.encode(null, b);   // keyframes are encoded against zeros
		int[] buf = new int[n];
		UiFrames.applyFrame(encA, buf, true);
		UiFrames.applyFrame(keyB, buf, true);
		assertArrayEquals("no ghost of the old overlay position", b, buf);

		// documents the bug this guards against: plain apply() on a keyframe leaves a ghost
		int[] naive = new int[n];
		UiFrames.apply(encA, naive);
		UiFrames.apply(keyB, naive);
		assertEquals("the naive path keeps the stale pixel", 0xff00ff00, naive[10]);
	}
}
